    // Per-tier scratch sizes for fdsva_so_contract (inline-CUDA users only — the host launchers always use TIER_SHARED).
    // At TIER_SHARED the 4*NV^3 inner scratch lives in s_temp; at TIER_LITE/MINIMAL it moves to d_workspace, freeing shared memory for the caller's outer kernel.
    // fdsva_so_contract scratch sizing, keyed on the INNER's placement choice
    // (SCRATCH_IN_SMEM) rather than a tier — the inner decides placement, the
    // caller sizes both arenas from these. FDSVA_SO_SCRATCH_IN_SMEM<TIER>()
    // gives the placement codegen assigned to each tier for THIS robot.
    template <typename T, bool SCRATCH_IN_SMEM = true> __host__ __device__ constexpr size_t FDSVA_SO_INNER_SMEM_BYTES() { return SCRATCH_IN_SMEM ? sizeof(T) * static_cast<size_t>(97556) : static_cast<size_t>(0); }
    template <typename T, bool SCRATCH_IN_SMEM = true> __host__ __device__ constexpr size_t FDSVA_SO_INNER_WORKSPACE_BYTES() { return SCRATCH_IN_SMEM ? static_cast<size_t>(0) : sizeof(T) * static_cast<size_t>(97556); }
    // Per-robot tier->placement map: contraction scratch stays in smem at any rung that doesn't set use_workspace_temp.
    template <int TIER> __host__ __device__ constexpr bool FDSVA_SO_SCRATCH_IN_SMEM() { return (TIER == TIER_SHARED) ? false : (TIER == TIER_LITE) ? false : false; }
    // Inner-controlled placement API (design rollout): each inline inner is keyed on a
    // placement bool and decides arena pointers itself. *_INNER_{SMEM,WORKSPACE}_BYTES<T, IN_SMEM>
    // give the two arena sizes; *_<...>_IN_SMEM<TIER>() give the per-robot tier->placement
    // map codegen assigned (multiple tiers may share a placement on small robots).
    // --- minv_inner (F-region) ---
    template <typename T, bool F_IN_SMEM = true> __host__ __device__ constexpr size_t MINV_INNER_SMEM_BYTES() { return sizeof(T) * static_cast<size_t>(1535 + 5046 * (F_IN_SMEM ? 1 : 0)); }
    template <typename T, bool F_IN_SMEM = true> __host__ __device__ constexpr size_t MINV_INNER_WORKSPACE_BYTES() { return F_IN_SMEM ? static_cast<size_t>(0) : sizeof(T) * static_cast<size_t>(5046); }
    template <int TIER> __host__ __device__ constexpr bool MINV_F_IN_SMEM() { return (TIER == TIER_SHARED) ? true : (TIER == TIER_LITE) ? true : false; }
    // --- forward_dynamics_inner (internal Minv F-region) ---
    template <typename T, bool MINV_F_IN_SMEM = true> __host__ __device__ constexpr size_t FD_INNER_SMEM_BYTES() { return MINV_F_IN_SMEM ? sizeof(T) * static_cast<size_t>(7422) : sizeof(T) * static_cast<size_t>(2376); }
    template <typename T, bool MINV_F_IN_SMEM = true> __host__ __device__ constexpr size_t FD_INNER_WORKSPACE_BYTES() { return MINV_F_IN_SMEM ? static_cast<size_t>(0) : sizeof(T) * static_cast<size_t>(5046); }
    template <int TIER> __host__ __device__ constexpr bool FD_MINV_F_IN_SMEM() { return (TIER == TIER_SHARED) ? true : (TIER == TIER_LITE) ? true : false; }
    // --- integrator_inner (forwards the FD inner's Minv F-region lever) ---
    template <typename T, bool MINV_F_IN_SMEM = true> __host__ __device__ constexpr size_t INTEGRATOR_INNER_SMEM_BYTES() { return MINV_F_IN_SMEM ? sizeof(T) * static_cast<size_t>(7422) : sizeof(T) * static_cast<size_t>(2376); }
    template <typename T, bool MINV_F_IN_SMEM = true> __host__ __device__ constexpr size_t INTEGRATOR_INNER_WORKSPACE_BYTES() { return MINV_F_IN_SMEM ? static_cast<size_t>(0) : sizeof(T) * static_cast<size_t>(5046); }
    // --- aba_inner (scratch band, surgical-spill ladder) ---
    // Levels: 0=full (smem), 1=surgical (hot smem + cold d_cold), 2=workspace (whole band global).
