    /**
     * @file barrier.cuh
     * @brief Barrier policy for the shared `*_impl` bodies (cgrps dedup + TRAILING_SYNC).
     *
     * Every public single-block op is written ONCE as a `*_impl(Bar bar, ...)` body
     * templated on a *barrier policy* that carries the thread `rank()`/`size()` and a
     * `sync()`. The plain `glass::` surface passes `BlockBarrier` (threadIdx/blockDim
     * + `__syncthreads()`); the `glass::cgrps::` surface passes a `GroupBarrier`
     * (cooperative-groups handle + `cooperative_groups::sync`, defined in
     * `src/cgrps/`). Routing BOTH the internal and the trailing barrier through
     * `bar.sync()` is what lets one body serve both surfaces — that barrier
     * primitive is the only thing that ever differed between them.
     *
     * `BlockBarrier` names no cooperative-groups type, so `glass.cuh` stays
     * dependency-free; the `GroupBarrier` twin is only compiled when a caller
     * includes `<cooperative_groups.h>` via `glass-cgrps.cuh`.
     *
     * Uniformity rule (project-wide): every public op takes `bool TRAILING_SYNC=true`
     * and ends on `if constexpr (TRAILING_SYNC) bar.sync();`, so the result is valid
     * for ALL threads by default. Callers that own the following barrier pass
     * `false` to elide it. For ops that already ended on a barrier this is
     * byte-identical; for the elementwise/reduce-tail ops it adds a strictly-safer
     * trailing barrier.
     */
    struct BlockBarrier {
        __device__ __forceinline__ uint32_t rank() const {
            return threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        }
        __device__ __forceinline__ uint32_t size() const {
            return blockDim.x * blockDim.y * blockDim.z;
        }
        __device__ __forceinline__ void sync() const { __syncthreads(); }
    };
    
    // ─────────────────────────────────────────────────────────────────────────────
    // ct_size — compile-time size carrier for the factor/solve `*_impl` bodies.
    //
    // The shared impls take their dimension through a deduced `SizeT` template
    // parameter instead of a hard `uint32_t`. The runtime public overloads pass a
    // plain `uint32_t` (unchanged behavior); the compile-time-size overloads pass
    // `ct_size<N>{}`, whose constexpr conversion makes every use of the dimension a
    // compile-time constant after inlining — so nvcc unrolls the loops and
    // strength-reduces the `%`/`/` indexing with NO body duplication (the same
    // effect `gemm_impl_ct` gets from its dedicated body). A self-made carrier
    // rather than std::integral_constant so no system header lands inside
    // `namespace glass` (this file is included inside the namespace by glass.cuh).
    // Defined here (not in trsv.cuh, its original home) because barrier.cuh is the
    // FIRST header glass.cuh pulls in and the one downstream vendoring already
    // carries — every factor/solve user (trsv/inv/syev/ldlt/…) sees it regardless
    // of which subset of headers a consumer embeds.
    // ─────────────────────────────────────────────────────────────────────────────
    template <uint32_t V>
    struct ct_size {
        __host__ __device__ constexpr operator uint32_t() const { return V; }
    };
    
    // ─────────────────────────────────────────────────────────────────────────────
    // beta_blend — BLAS beta==0 semantics for every beta-taking op.
    //
    // BLAS (and cuBLAS) guarantee that when `beta == 0` the destination is
    // WRITE-ONLY: it need not hold a valid value on input. A naive
    // `alpha*res + beta*dst` breaks that guarantee — `0 * NaN == NaN`, so cold
    // scratch left as NaN by a previous kernel poisons the result even though
    // beta is zero (found 2026-07-08: GRiD's generated RNEA passes beta=0 gemvs
    // over uninitialized s_vaf smem; diverged rollouts leave NaN on the SM and
    // the "zero" blend propagates it). The beta != 0 arm is an EXPLICIT fused
    // multiply-add intrinsic, not `acc + beta*dst`: a plain expression leaves the
    // FMA-contraction choice to ptxas, which decides per kernel and broke
    // warp-vs-block bit-identity (test_syrk_warp); a single FFMA/DFMA is the same
    // instruction in every instantiation. The compiler cannot fold the select
    // away, because `beta*dst == 0` does not hold for floats. Every beta-form op
    // must route its blend through this helper. (Bit-note vs the pre-helper code:
    // results are identical at beta ∈ {0, 1} — every consumer's case — and may
    // differ in the last ULP at fractional beta, where the old code's contraction
    // was unspecified anyway.)
    // ─────────────────────────────────────────────────────────────────────────────
    __device__ __forceinline__ float beta_blend_fma(float acc, float beta, float dst) {
        return __fmaf_rn(beta, dst, acc);
    }
    __device__ __forceinline__ double beta_blend_fma(double acc, double beta, double dst) {
        return __fma_rn(beta, dst, acc);
    }
    template <typename T>
    __device__ __forceinline__ T beta_blend_fma(T acc, T beta, T dst) {
        return acc + beta * dst;
    }
    
    template <typename T>
    __device__ __forceinline__ T beta_blend(T acc, T beta, const T &dst) {
        return (beta != static_cast<T>(0)) ? beta_blend_fma(acc, beta, dst) : acc;
    }
    // END GLASS src/base/barrier.cuh
    
    // BEGIN GLASS src/base/L1/reduce.cuh
    
    /**
     * @brief Sum reduction: `x[0] = Σ x[i]` (in-place, destructive).
     *
     * Default `threadIdx`-based halving reduce; the block cooperatively sums the
     * vector and leaves the total in `x[0]` (the input is overwritten). NumPy
     * equivalent: `np.sum(x)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param n  Number of elements.
     * @param x  In/out vector of length `n`; the sum lands in `x[0]`.
     */
    // Shared body: default halving (tree) reduce; result in x[0]. The barrier policy
    // supplies rank/size + the internal AND trailing sync, so the plain glass:: and
    // the cgrps:: surfaces share this one body. TRAILING_SYNC (default true) makes
    // x[0] valid for ALL threads; pass false when the caller owns the next barrier.
    template <typename Bar, typename T, bool TRAILING_SYNC = true>
    __device__ void reduce_impl(Bar bar, uint32_t n, T *x)
    {
        uint32_t rank = bar.rank(), size = bar.size();
        uint32_t left = n;
        while (left > 3) {
            bool odd = left % 2;
            left = (left - odd) / 2;
            for (uint32_t i = rank; i < left; i += size) x[i] += x[i + left];
            if (rank == 0 && odd) x[0] += x[2*left];
            bar.sync();
        }
        if (rank == 0) { for (uint32_t i = 1; i < left; i++) x[0] += x[i]; }
        if constexpr (TRAILING_SYNC) bar.sync();
    }
    
    // default threadIdx-based halving reduce; result in x[0]
    template <typename T, bool TRAILING_SYNC = true>
    __device__ void reduce(uint32_t n, T *x)
    {
        reduce_impl<BlockBarrier, T, TRAILING_SYNC>(BlockBarrier{}, n, x);
    }
    
    /**
     * @brief Sum reduction: `x[0] = Σ x[i]` (in-place), compile-time size.
     *
     * Compile-time-`N` overload of the halving reduce. NumPy equivalent: `np.sum(x)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @tparam N  Number of elements (compile-time constant).
     * @param x  In/out vector of length `N`; the sum lands in `x[0]`.
     */
    template <typename T, uint32_t N, bool TRAILING_SYNC = true>
    __device__ void reduce(T *x)
    {
        reduce_impl<BlockBarrier, T, TRAILING_SYNC>(BlockBarrier{}, N, x);
    }
    
    /**
     * @brief Sum reduction: `x[0] = Σ x[i]` (in-place), low-memory variant.
     *
     * Thread 0 serially accumulates all elements into `x[0]`; uses no scratch.
     * NumPy equivalent: `np.sum(x)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param n  Number of elements.
     * @param x  In/out vector of length `n`; the sum lands in `x[0]`.
     */
    template <typename T, bool TRAILING_SYNC = true>
    __device__ void reduce_lowmem(uint32_t n, T *x)
    {
        if (threadIdx.x == 0 && threadIdx.y == 0 && threadIdx.z == 0)
            for (uint32_t i = 1; i < n; i++) x[0] += x[i];
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief Sum reduction: `x[0] = Σ x[i]` (in-place), low-memory, compile-time size.
     *
     * Compile-time-`N` overload; thread 0 serially accumulates into `x[0]`.
     * NumPy equivalent: `np.sum(x)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @tparam N  Number of elements (compile-time constant).
     * @param x  In/out vector of length `N`; the sum lands in `x[0]`.
     */
    template <typename T, uint32_t N, bool TRAILING_SYNC = true>
    __device__ void reduce_lowmem(T *x)
    {
        if (threadIdx.x == 0 && threadIdx.y == 0 && threadIdx.z == 0)
            for (uint32_t i = 1; i < N; i++) x[0] += x[i];
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    /**
     * @brief Shared-scratch size in bytes for the `reduce_fast` ops.
     *
     * The warp-shuffle reduce combines across warps through one scratch slot per
     * warp: `ceil(block_threads / 32)` elements of `T`. Allocate
     * `reduce_fast_scratch_bytes<T>(block_threads)` for the `s_scratch` argument.
     *
     * @tparam T  Scalar type.
     * @param block_threads  Number of threads in the launching block.
     * @return Bytes to allocate for `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t reduce_fast_scratch_bytes(uint32_t block_threads) { return static_cast<std::size_t>((block_threads + 31) / 32) * sizeof(T); }
    
    /**
     * @brief Sum reduction: `x[0] = Σ x[i]` (in-place), warp-shuffle variant.
     *
     * Accumulates with a warp-shuffle reduction plus an inter-warp reduction
     * through shared scratch; the total lands in `x[0]`. NumPy equivalent:
     * `np.sum(x)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param n          Number of elements.
     * @param x          In/out vector of length `n`; the sum lands in `x[0]`.
     * @param s_scratch  Shared scratch of `ceil(blockDim/32)` elements (one per warp).
     */
    // warp-shuffle + inter-warp reduce; s_scratch: ceil(blockDim/32)*sizeof(T); result in x[0]
    template <typename T, bool TRAILING_SYNC = true>
    __device__ void reduce_fast(uint32_t n, T *x, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        T val = static_cast<T>(0);
        for (uint32_t i = rank; i < n; i += size) val += x[i];
        for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
        uint32_t lane = rank & 31, warp = rank >> 5;
        if (lane == 0) s_scratch[warp] = val;
        __syncthreads();
        uint32_t nw = (size + 31) / 32;
        if (rank < 32) {
            val = (rank < nw) ? s_scratch[rank] : static_cast<T>(0);
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (rank == 0) x[0] = val;
        }
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief Sum reduction: `x[0] = Σ x[i]` (in-place), warp-shuffle, compile-time size.
     *
     * Compile-time-`N` overload of the warp-shuffle reduce. NumPy equivalent:
     * `np.sum(x)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @tparam N  Number of elements (compile-time constant).
     * @param x          In/out vector of length `N`; the sum lands in `x[0]`.
     * @param s_scratch  Shared scratch of `ceil(blockDim/32)` elements (one per warp).
     */
    template <typename T, uint32_t N, bool TRAILING_SYNC = true>
    __device__ void reduce_fast(T *x, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        T val = static_cast<T>(0);
        for (uint32_t i = rank; i < N; i += size) val += x[i];
        for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
        uint32_t lane = rank & 31, warp = rank >> 5;
        if (lane == 0) s_scratch[warp] = val;
        __syncthreads();
        uint32_t nw = (size + 31) / 32;
        if (rank < 32) {
            val = (rank < nw) ? s_scratch[rank] : static_cast<T>(0);
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (rank == 0) x[0] = val;
        }
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    // ── register-partial → block-sum overload ────────────────────────────────
    // Block-reduce one PER-THREAD register value `partial` (one contribution per
    // thread) and return the block total to EVERY thread, with no x[] buffer to
    // materialize the partials first.  This is the entry point for fused
    // "compute-a-partial-then-sum" patterns (e.g. cost/barrier kernels that form
    // a per-thread term and previously did a serial thread-0 sum): each thread
    // passes its own contribution directly.
    //
    // s_scratch must hold ceil(blockDim/32) elements (one per warp), the same
    // sizing as the array overloads above.  The result is broadcast to all
    // threads (s_scratch[0] holds the total on return); the routine ends on a
    // __syncthreads(), so s_scratch is safe to reuse afterwards.  Threads that
    // have no contribution should pass partial = 0.
    /**
     * @brief Block-sum of a per-thread register value: returns `Σ partial`.
     *
     * Reduces one PER-THREAD contribution `partial` (one per thread) across the
     * block and returns the total to EVERY thread, with no intermediate `x[]`
     * buffer. This is the entry point for fused "compute-a-partial-then-sum"
     * patterns (e.g. cost/barrier kernels). The result is also broadcast through
     * `s_scratch[0]`; the routine ends on a `__syncthreads()`, so `s_scratch` is
     * safe to reuse afterwards. Threads with no contribution should pass `0`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param partial    This thread's contribution to the block sum.
     * @param s_scratch  Shared scratch of `ceil(blockDim/32)` elements (one per warp);
     *                   on return `s_scratch[0]` holds the total.
     * @return The block-wide total `Σ partial`, identical on every thread.
     */
    template <typename T, bool TRAILING_SYNC = true>
    __device__ T reduce_fast(T partial, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        T val = partial;
        for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
        uint32_t lane = rank & 31, warp = rank >> 5;
        if (lane == 0) s_scratch[warp] = val;
        __syncthreads();
        uint32_t nw = (size + 31) / 32;
        if (rank < 32) {
            val = (rank < nw) ? s_scratch[rank] : static_cast<T>(0);
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (rank == 0) s_scratch[0] = val;
        }
        __syncthreads();
        T total = s_scratch[0];
        if constexpr (TRAILING_SYNC) __syncthreads();
        return total;
    }
    namespace warp {
        // Single-warp reductions: raw __shfl, no shared scratch, no inter-warp combine.
        // For warp-per-problem kernels (one 32-lane warp owns the reduction). The
        // caller must run a full warp (mask 0xffffffff); partial-warp callers must
        // pass 0 from inactive lanes. Distinct from reduce_fast, which is
        // block-scoped (warp-shuffle + shared inter-warp combine).
    
        /**
         * @brief Sum reduction within one warp: `x[0] = Σ x[i]` (in-place), single-warp.
         *
         * One 32-lane warp sums the vector with `__shfl_down_sync`; the total lands in
         * `x[0]` (input overwritten). No shared scratch, no inter-warp combine. NumPy
         * equivalent: `np.sum(x)`.
         *
         * @tparam T  Scalar type (e.g. `float`, `double`).
         * @param n  Number of elements.
         * @param x  In/out vector of length `n`; the sum lands in `x[0]`.
         */
        template <typename T>
        __device__ void reduce(uint32_t n, T *x)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            T val = static_cast<T>(0);
            for (uint32_t i = lane; i < n; i += 32) val += x[i];
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (lane == 0) x[0] = val;
            __syncwarp();
        }
    
        /**
         * @brief Sum reduction within one warp: `x[0] = Σ x[i]` (in-place), single-warp, compile-time size.
         *
         * Compile-time-`N` overload. NumPy equivalent: `np.sum(x)`.
         *
         * @tparam T  Scalar type (e.g. `float`, `double`).
         * @tparam N  Number of elements (compile-time constant).
         * @param x  In/out vector of length `N`; the sum lands in `x[0]`.
         */
        template <typename T, uint32_t N>
        __device__ void reduce(T *x)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            T val = static_cast<T>(0);
            for (uint32_t i = lane; i < N; i += 32) val += x[i];
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (lane == 0) x[0] = val;
            __syncwarp();
        }
    
        /**
         * @brief Warp-sum of a per-lane register value: returns `Σ partial` on every lane.
         *
         * Reduces one PER-LANE contribution across a single warp and broadcasts the
         * total back to all 32 lanes — no `x[]` buffer, no shared scratch. The entry
         * point for fused "compute-a-partial-then-sum" patterns inside a warp (e.g.
         * row-norm / residual accumulation). Inactive lanes should pass `0`.
         *
         * @tparam T  Scalar type (e.g. `float`, `double`).
         * @param partial  This lane's contribution.
         * @return The warp-wide total `Σ partial`, identical on every lane.
         */
        template <typename T>
        __device__ T reduce(T partial)
        {
            T val = partial;
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            return __shfl_sync(0xffffffff, val, 0);
        }
    }
    
    /**
     * @brief Fixed 32-way pairwise tree reduce of a register array (returns the sum in p[0]).
     *
     * Combines 32 partials in the EXACT pairwise grouping that `glass::warp::reduce`
     * produces in lane 0 (a `__shfl_down_sync` tree with offsets 16,8,4,2,1), so a
     * serial caller (e.g. a sub-warp fallback below 32 threads) matches the
     * full-warp caller bit-for-bit. This is the shared primitive that lets the
     * contraction-parallel `*_reduced` engines stay thread-count invariant across the
     * 32-thread boundary. NumPy equivalent: `np.sum(p)` (different rounding).
     *
     * @tparam T  Scalar type.
     * @param p  In/out array of 32 partials; on return `p[0]` holds the total (p is clobbered).
     * @return The sum of `p[0..31]`.
     */
    template <typename T>
    __device__ __forceinline__ T reduced_tree32(T p[32])
    {
        #pragma unroll
        for (uint32_t off = 16; off > 0; off >>= 1)
            for (uint32_t l = 0; l < off; ++l) p[l] += p[l + off];
        return p[0];
    }
    // END GLASS src/base/L1/reduce.cuh
    
    // BEGIN GLASS src/base/L1/dot.cuh
    
    /**
     * @brief Inner product: `y[0] = x · y` (DOT), in-place.
     *
     * Multiplies the vectors element-wise into `y`, then runs a block-wide halving
     * reduce so the scalar result lands in `y[0]` (uses `y` as scratch — it is
     * overwritten). NumPy equivalent: `np.dot(x, y)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param n  Number of elements.
     * @param x  Input vector of length `n`.
     * @param y  In/out vector of length `n`; the dot product lands in `y[0]`.
     */
    // Shared body: y = x·y (result in y[0]); element-wise multiply then halving
    // reduce on y. The trailing barrier rides on reduce_impl's TRAILING_SYNC.
    template <typename Bar, typename T, bool TRAILING_SYNC = true>
    __device__ void dot_impl(Bar bar, uint32_t n, T *x, T *y)
    {
        uint32_t rank = bar.rank(), size = bar.size();
        for (uint32_t i = rank; i < n; i += size) y[i] *= x[i];
        bar.sync();
        reduce_impl<Bar, T, TRAILING_SYNC>(bar, n, y);
    }
    
    // in-place: y = x·y (result in y[0]); uses halving reduce on y
    template <typename T, bool TRAILING_SYNC = true>
    __device__ void dot(uint32_t n, T *x, T *y)
    {
        dot_impl<BlockBarrier, T, TRAILING_SYNC>(BlockBarrier{}, n, x, y);
    }
    
    /**
     * @brief Inner product: `y[0] = x · y` (DOT), in-place, compile-time size.
     *
     * Compile-time-`N` overload; the scalar result lands in `y[0]` (uses `y` as
     * scratch). NumPy equivalent: `np.dot(x, y)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @tparam N  Number of elements (compile-time constant).
     * @param x  Input vector of length `N`.
     * @param y  In/out vector of length `N`; the dot product lands in `y[0]`.
     */
    template <typename T, uint32_t N, bool TRAILING_SYNC = true>
    __device__ void dot(T *x, T *y)
    {
        dot_impl<BlockBarrier, T, TRAILING_SYNC>(BlockBarrier{}, N, x, y);
    }
    
    /**
     * @brief Inner product: `out[0] = x · y` (DOT), low-memory variant.
     *
     * Writes the element-wise products into `out`, then thread 0 serially
     * accumulates them into `out[0]`, leaving `x` and `y` untouched. NumPy
     * equivalent: `np.dot_lowmem(x, y)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param n    Number of elements.
     * @param x    Input vector of length `n`.
     * @param y    Input vector of length `n`.
     * @param out  Length-`n` scratch/output buffer; the result lands in `out[0]`.
     */
    // out: length-n scratch; result in out[0]
    template <typename T, bool TRAILING_SYNC = true>
    __device__ void dot_lowmem(uint32_t n, T *x, T *y, T *out)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        for (uint32_t i = rank; i < n; i += size) out[i] = x[i]*y[i];
        __syncthreads();
        if (rank == 0) { for (uint32_t i = 1; i < n; i++) out[0] += out[i]; }
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    namespace warp {
        // Single-warp dot products: one 32-lane warp owns the reduction (raw __shfl,
        // no shared scratch). For warp-per-problem kernels packing many small dots
        // into one block via independent warps (threadIdx.y selects the warp). The
        // caller must run a full 32-lane warp (mask 0xffffffff). Distinct from
        // dot_fast, which is block-scoped (warp-shuffle + shared inter-warp
        // combine). The result is broadcast to EVERY lane, so the value is usable
        // immediately by all lanes without a follow-up read.
    
        /**
         * @brief Inner product within one warp: returns `x · y` on every lane, single-warp.
         *
         * One 32-lane warp forms the element-wise products and reduces them with
         * `__shfl_down_sync`, then BROADCASTS the scalar total back to all 32 lanes via
         * `__shfl_sync` (from a lane's register, never a shared re-read — immune to the
         * `__restrict__` stale-cache miscompile). Inputs are left untouched; no shared
         * scratch, no `__syncthreads`. Full 32 lanes required; independent warps may run
         * distinct problems concurrently. NumPy equivalent: `np.dot(x, y)`.
         *
         * @tparam T  Scalar type (e.g. `float`, `double`).
         * @param n  Number of elements.
         * @param x  Input vector of length `n`.
         * @param y  Input vector of length `n`.
         * @return The inner product `x · y`, identical on every lane.
         */
        template <typename T>
        __device__ T dot(uint32_t n, T *x, T *y)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            T val = static_cast<T>(0);
            for (uint32_t i = lane; i < n; i += 32) val += x[i]*y[i];
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffffu, val, off);
            return __shfl_sync(0xffffffffu, val, 0);
        }
    
        /**
         * @brief Inner product within one warp: returns `x · y` on every lane, single-warp, compile-time size.
         *
         * Compile-time-`N` overload of the single-warp dot. Reduces with
         * `__shfl_down_sync` and broadcasts the total to all 32 lanes from a register.
         * No shared scratch, no `__syncthreads`. NumPy equivalent: `np.dot(x, y)`.
         *
         * @tparam T  Scalar type (e.g. `float`, `double`).
         * @tparam N  Number of elements (compile-time constant).
         * @param x  Input vector of length `N`.
         * @param y  Input vector of length `N`.
         * @return The inner product `x · y`, identical on every lane.
         */
        template <typename T, uint32_t N>
        __device__ T dot(T *x, T *y)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            T val = static_cast<T>(0);
            for (uint32_t i = lane; i < N; i += 32) val += x[i]*y[i];
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffffu, val, off);
            return __shfl_sync(0xffffffffu, val, 0);
        }
    }
    
    /**
     * @brief Shared-scratch size in bytes for the `dot_fast` ops.
     *
     * The warp-shuffle dot combines across warps through one scratch slot per warp:
     * `ceil(block_threads / 32)` elements of `T`. Allocate
     * `dot_fast_scratch_bytes<T>(block_threads)` for the `s_scratch` argument.
     *
     * @tparam T  Scalar type.
     * @param block_threads  Number of threads in the launching block.
     * @return Bytes to allocate for `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t dot_fast_scratch_bytes(uint32_t block_threads) { return static_cast<std::size_t>((block_threads + 31) / 32) * sizeof(T); }
    
    /**
     * @brief Inner product: `out[0] = x · y` (DOT), warp-shuffle variant.
     *
     * Accumulates the element-wise products with a warp-shuffle reduction plus
     * an inter-warp reduction through shared scratch, leaving `x` and `y`
     * untouched. NumPy equivalent: `np.dot_fast(x, y)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @param n          Number of elements.
     * @param x          Input vector of length `n`.
     * @param y          Input vector of length `n`.
     * @param out        Output buffer; the result lands in `out[0]`.
     * @param s_scratch  Shared scratch of `ceil(blockDim/32)` elements (one per warp).
     */
    // s_scratch: ceil(blockDim/32)*sizeof(T); result in out[0]
    template <typename T, bool TRAILING_SYNC = true>
    __device__ void dot_fast(uint32_t n, T *x, T *y, T *out, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        T val = static_cast<T>(0);
        for (uint32_t i = rank; i < n; i += size) val += x[i]*y[i];
        for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
        uint32_t lane = rank & 31, warp = rank >> 5;
        if (lane == 0) s_scratch[warp] = val;
        __syncthreads();
        uint32_t nw = (size + 31) / 32;
        if (rank < 32) {
            val = (rank < nw) ? s_scratch[rank] : static_cast<T>(0);
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (rank == 0) out[0] = val;
        }
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief Inner product: `out[0] = x · y` (DOT), warp-shuffle, compile-time size.
     *
     * Compile-time-`N` overload of the warp-shuffle dot product. NumPy
     * equivalent: `np.dot_fast(x, y)`.
     *
     * @tparam T  Scalar type (e.g. `float`, `double`).
     * @tparam N  Number of elements (compile-time constant).
     * @param x          Input vector of length `N`.
     * @param y          Input vector of length `N`.
     * @param out        Output buffer; the result lands in `out[0]`.
     * @param s_scratch  Shared scratch of `ceil(blockDim/32)` elements (one per warp).
     */
    template <typename T, uint32_t N, bool TRAILING_SYNC = true>
    __device__ void dot_fast(T *x, T *y, T *out, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        T val = static_cast<T>(0);
        for (uint32_t i = rank; i < N; i += size) val += x[i]*y[i];
        for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
        uint32_t lane = rank & 31, warp = rank >> 5;
        if (lane == 0) s_scratch[warp] = val;
        __syncthreads();
        uint32_t nw = (size + 31) / 32;
        if (rank < 32) {
            val = (rank < nw) ? s_scratch[rank] : static_cast<T>(0);
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (rank == 0) out[0] = val;
        }
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    // END GLASS src/base/L1/dot.cuh
    
    // BEGIN GLASS src/base/L1/dot_strided.cuh
    
    // Per-thread compile-time strided dot product.
    // Computes sum(x[i*SX] * y[i*SY]) for i in 0..N-1.
    // No block-wide reduction — intended for use inside already-parallelized loops
    // (e.g., GRiD generated kernels where the outer loop is already thread-parallel).
    // With SX=SY=1 this is a plain scalar dot.  The inner loop is fully unrolled
    // by the compiler since N, SX, SY are all compile-time constants.
    
    /**
     * @brief Per-thread strided inner product: `Σ x[i*SX] * y[i*SY]` (DOT, strided).
     *
     * A single thread independently walks the full `N`-length product with
     * compile-time strides, returning the scalar result. There is NO block-wide
     * reduction — intended for use inside an already thread-parallel outer loop
     * (e.g. GRiD generated kernels). With `SX = SY = 1` this is a plain scalar dot;
     * the inner loop is fully unrolled. NumPy equivalent: `np.dot(x[::SX], y[::SY])`.
     *
     * @tparam T   Scalar type (e.g. `float`, `double`).
     * @tparam N   Number of products to accumulate (compile-time constant).
     * @tparam SX  Element stride into `x` (compile-time, default 1).
     * @tparam SY  Element stride into `y` (compile-time, default 1).
     * @param x  Input vector, accessed at indices `0, SX, 2*SX, …`.
     * @param y  Input vector, accessed at indices `0, SY, 2*SY, …`.
     * @return The strided inner product `Σ x[i*SX] * y[i*SY]`.
     */
    template <typename T, uint32_t N, uint32_t SX = 1, uint32_t SY = 1>
    __device__ T dot_strided(const T* x, const T* y)
    {
        T res = static_cast<T>(0);
        for (uint32_t i = 0; i < N; i++)
            res += x[i * SX] * y[i * SY];
        return res;
    }
    
    /**
     * @brief Per-thread strided inner product, store-to-pointer overload.
     *
     * Same per-thread strided dot as the value-returning overload, but writes the
     * scalar result to `*out`. NumPy equivalent: `out[0] = np.dot(x[::SX], y[::SY])`.
     *
     * @tparam T   Scalar type (e.g. `float`, `double`).
     * @tparam N   Number of products to accumulate (compile-time constant).
     * @tparam SX  Element stride into `x` (compile-time, default 1).
     * @tparam SY  Element stride into `y` (compile-time, default 1).
     * @param x    Input vector, accessed at indices `0, SX, 2*SX, …`.
     * @param y    Input vector, accessed at indices `0, SY, 2*SY, …`.
     * @param out  Destination for the scalar result.
     */
    template <typename T, uint32_t N, uint32_t SX = 1, uint32_t SY = 1>
    __device__ void dot_strided(const T* x, const T* y, T* out)
    {
        *out = dot_strided<T, N, SX, SY>(x, y);
    }
    // END GLASS src/base/L1/dot_strided.cuh
    
    // BEGIN GLASS src/base/L1/dot_strided_coalesced.cuh
    
    // Block-COOPERATIVE strided dot product with coalesced global loads.
    //
    // Computes the SAME value as dot_strided<T,N,SX,SY>:
    //     sum_{i=0}^{N-1} x[i*SX] * y[i*SY]
    // but is a *sibling* primitive, NOT a drop-in template swap for dot_strided:
    //
    //   * dot_strided<T,N,SX,SY> is PER-THREAD (no synchronization): every calling
    //     thread independently walks the full N-length stride and returns T.  It is
    //     meant for use inside an already-thread-parallel outer loop.  With a large
    //     stride SX, thread t reads x[0], x[SX], x[2*SX], ... — addresses that are
    //     SX apart, so a single thread's loads are uncoalesced (and every thread
    //     redundantly reads the same data).
    //
    //   * dot_strided_coalesced is BLOCK-WIDE: the whole block cooperates on ONE
    //     dot product.  The i-loop is distributed across threads with a block-stride
    //     (thread rank handles i = rank, rank+size, ...), so at each step threads
    //     0,1,2,... read x[rank*SX] for consecutive rank — i.e. consecutive threads
    //     touch addresses SX apart.  When SX is itself the inner contiguous axis of
    //     a 2D access pattern (the common "column of a row-major / strided matrix"
    //     case in GRiD), transposing the iteration this way makes the per-warp load
    //     a coalesced burst instead of a strided gather.  Partial sums are then
    //     combined with a warp-shuffle + shared-scratch block reduction (same idiom
    //     as glass::reduce_fast).
    //
    // Because it performs a block reduction it REQUIRES a block-wide launch and a
    // __syncthreads-safe context; it writes the scalar result to *out (visible to
    // all threads after the trailing barrier).  Callers in a per-thread context
    // must keep using dot_strided instead.
    //
    // s_scratch must hold ceil(blockDim/32) elements of T.
    
    /**
     * @brief Block-cooperative strided inner product with coalesced loads (DOT, strided).
     *
     * Computes the same value as `dot_strided<T,N,SX,SY>` (`Σ x[i*SX] * y[i*SY]`),
     * but the WHOLE block cooperates on one dot product: the `i`-loop is distributed
     * across threads with a block stride so consecutive ranks touch addresses `SX`
     * apart, turning a per-warp strided gather into a coalesced burst when `SX` is
     * the inner contiguous axis. Partial sums are combined via warp-shuffle plus a
     * shared-scratch block reduction; the scalar result is broadcast to `*out`
     * (visible to all threads after the trailing barrier). Requires a block-wide,
     * `__syncthreads`-safe launch — use `dot_strided` instead in a per-thread
     * context. NumPy equivalent: `np.dot(x[::SX], y[::SY])`.
     *
     * @tparam T   Scalar type (e.g. `float`, `double`).
     * @tparam N   Number of products to accumulate (compile-time constant).
     * @tparam SX  Element stride into `x` (compile-time, default 1).
     * @tparam SY  Element stride into `y` (compile-time, default 1).
     * @param x          Input vector, accessed at indices `0, SX, 2*SX, …`.
     * @param y          Input vector, accessed at indices `0, SY, 2*SY, …`.
     * @param out        Destination for the scalar result (broadcast to all threads).
     * @param s_scratch  Shared scratch of `ceil(blockDim/32)` elements (one per warp).
     */
    template <typename T, uint32_t N, uint32_t SX = 1, uint32_t SY = 1, bool TRAILING_SYNC = true>
    __device__ void dot_strided_coalesced(const T* x, const T* y, T* out, T* s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
    
        // Each thread accumulates a partial over its block-strided slice of i.
        // Consecutive ranks read consecutive (i*SX, i*SY) base addresses.
        T val = static_cast<T>(0);
        for (uint32_t i = rank; i < N; i += size)
            val += x[i * SX] * y[i * SY];
    
        // Warp-level reduce, then inter-warp reduce via shared scratch.
        for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
        uint32_t lane = rank & 31, warp = rank >> 5;
        if (lane == 0) s_scratch[warp] = val;
        __syncthreads();
        uint32_t nw = (size + 31) / 32;
        if (rank < 32) {
            val = (rank < nw) ? s_scratch[rank] : static_cast<T>(0);
            for (int off = 16; off > 0; off >>= 1) val += __shfl_down_sync(0xffffffff, val, off);
            if (rank == 0) *out = val;
        }
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    // END GLASS src/base/L1/dot_strided_coalesced.cuh
    
    // BEGIN GLASS src/base/L2/gemv.cuh
    
    // core impl: explicit rank/size + layout flags
    template <typename T, bool TRANSPOSE, bool ROW_MAJOR_A>
    __device__ void gemv_impl(uint32_t rank, uint32_t size,
                               uint32_t m, uint32_t n,
                               T alpha, const T *A, const T *x, T beta, T *y)
    {
        if (TRANSPOSE) {
            for (uint32_t row = rank; row < n; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < m; col++) {
                    T a = ROW_MAJOR_A ? A[col*n + row] : A[col + row*m];
                    res += a * x[col];
                }
                y[row] = beta_blend(alpha*res, beta, y[row]);
            }
        } else {
            for (uint32_t row = rank; row < m; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < n; col++) {
                    T a = ROW_MAJOR_A ? A[row*n + col] : A[row + col*m];
                    res += a * x[col];
                }
                y[row] = beta_blend(alpha*res, beta, y[row]);
            }
        }
    }
    
    template <typename T, bool TRANSPOSE, bool ROW_MAJOR_A>
    __device__ void gemv_impl(uint32_t rank, uint32_t size,
                               uint32_t m, uint32_t n,
                               T alpha, const T *A, const T *x, T *y)
    {
        if (TRANSPOSE) {
            for (uint32_t row = rank; row < n; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < m; col++) {
                    T a = ROW_MAJOR_A ? A[col*n + row] : A[col + row*m];
                    res += a * x[col];
                }
                y[row] = alpha*res;
            }
        } else {
            for (uint32_t row = rank; row < m; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < n; col++) {
                    T a = ROW_MAJOR_A ? A[row*n + col] : A[row + col*m];
                    res += a * x[col];
                }
                y[row] = alpha*res;
            }
        }
    }
    
    // ─── runtime variants ─────────────────────────────────────────────────────────
    
    /**
     * @brief Matrix-vector product: `y = alpha * A * x + beta * y` (GEMV).
     *
     * Threads are distributed over the output rows of the `m×n` matrix `A`. Set
     * `TRANSPOSE=true` to compute `Aᵀ * x` and `ROW_MAJOR=true` for row-major `A`
     * (`A` is column-major by default). NumPy equivalent: `y = alpha*A@x + beta*y`
     * (or `alpha*A.T@x + beta*y` when transposed).
     *
     * Unlike `gemm` — where a row-major operand is just a transpose, so the only
     * layout flag is `ROW_MAJOR_C` — GEMV keeps a per-matrix `ROW_MAJOR` flag:
     * `TRANSPOSE` already selects the mathematical operation (`A·x` vs `Aᵀ·x`), so it
     * cannot also stand in for the storage order. `TRANSPOSE` and `ROW_MAJOR` are
     * therefore independent. (This flag fully subsumes the former `gemv_ex`, which
     * was just `gemv` with the defaults removed and has been deleted.)
     *
     * @tparam T          Scalar type (e.g. `float`, `double`).
     * @tparam TRANSPOSE  When true, multiply by `Aᵀ` instead of `A` (default false).
     * @tparam ROW_MAJOR  When true, `A` is stored row-major (default false = column-major).
     * @param m      Number of rows of `A`.
     * @param n      Number of columns of `A`.
     * @param alpha  Scalar multiplier on the product.
     * @param A      Input matrix of `m*n` elements.
     * @param x      Input vector (length `n`, or `m` when transposed).
     * @param beta   Scalar multiplier on the prior `y`.
     * @param y      In/out vector (length `m`, or `n` when transposed).
     */
    template <typename T, bool TRANSPOSE = false, bool ROW_MAJOR = false, bool TRAILING_SYNC = true>
    __device__ void gemv(uint32_t m, uint32_t n, T alpha, const T *A, const T *x, T beta, T *y)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemv_impl<T, TRANSPOSE, ROW_MAJOR>(rank, size, m, n, alpha, A, x, beta, y);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief Matrix-vector product: `y = alpha * A * x` (GEMV), no-beta overload.
     *
     * Same as the full GEMV but overwrites `y` (no `beta * y` term). Set
     * `TRANSPOSE=true` for `Aᵀ * x` and `ROW_MAJOR=true` for row-major `A`. NumPy
     * equivalent: `y = alpha*A@x` (or `alpha*A.T@x` when transposed).
     *
     * @tparam T          Scalar type (e.g. `float`, `double`).
     * @tparam TRANSPOSE  When true, multiply by `Aᵀ` instead of `A` (default false).
     * @tparam ROW_MAJOR  When true, `A` is stored row-major (default false = column-major).
     * @param m      Number of rows of `A`.
     * @param n      Number of columns of `A`.
     * @param alpha  Scalar multiplier on the product.
     * @param A      Input matrix of `m*n` elements.
     * @param x      Input vector (length `n`, or `m` when transposed).
     * @param y      Output vector (length `m`, or `n` when transposed).
     */
    template <typename T, bool TRANSPOSE = false, bool ROW_MAJOR = false, bool TRAILING_SYNC = true>
    __device__ void gemv(uint32_t m, uint32_t n, T alpha, const T *A, const T *x, T *y)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemv_impl<T, TRANSPOSE, ROW_MAJOR>(rank, size, m, n, alpha, A, x, y);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    // compile-time impl: M, N as template params so inner col-loop is fully unrolled
    template <typename T, uint32_t M, uint32_t N, bool TRANSPOSE, bool ROW_MAJOR_A>
    __device__ void gemv_impl_ct(uint32_t rank, uint32_t size,
                                  T alpha, const T *A, const T *x, T beta, T *y)
    {
        if (TRANSPOSE) {
            for (uint32_t row = rank; row < N; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < M; col++) {
                    T a = ROW_MAJOR_A ? A[col*N + row] : A[col + row*M];
                    res += a * x[col];
                }
                y[row] = beta_blend(alpha*res, beta, y[row]);
            }
        } else {
            for (uint32_t row = rank; row < M; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < N; col++) {
                    T a = ROW_MAJOR_A ? A[row*N + col] : A[row + col*M];
                    res += a * x[col];
                }
                y[row] = beta_blend(alpha*res, beta, y[row]);
            }
        }
    }
    
    template <typename T, uint32_t M, uint32_t N, bool TRANSPOSE, bool ROW_MAJOR_A>
    __device__ void gemv_impl_ct(uint32_t rank, uint32_t size,
                                  T alpha, const T *A, const T *x, T *y)
    {
        if (TRANSPOSE) {
            for (uint32_t row = rank; row < N; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < M; col++) {
                    T a = ROW_MAJOR_A ? A[col*N + row] : A[col + row*M];
                    res += a * x[col];
                }
                y[row] = alpha*res;
            }
        } else {
            for (uint32_t row = rank; row < M; row += size) {
                T res = static_cast<T>(0);
                for (uint32_t col = 0; col < N; col++) {
                    T a = ROW_MAJOR_A ? A[row*N + col] : A[row + col*M];
                    res += a * x[col];
                }
                y[row] = alpha*res;
            }
        }
    }
    
    // ─── compile-time size variants ───────────────────────────────────────────────
    
    /**
     * @brief Matrix-vector product: `y = alpha * A * x + beta * y` (GEMV), compile-time size.
     *
     * Compile-time-`M`,`N` overload; the inner column loop is fully unrolled. Set
     * `TRANSPOSE=true` for `Aᵀ * x` and `ROW_MAJOR=true` for row-major `A`. NumPy
     * equivalent: `y = alpha*A@x + beta*y` (or `alpha*A.T@x + beta*y`).
     *
     * @tparam T          Scalar type (e.g. `float`, `double`).
     * @tparam M          Number of rows of `A` (compile-time constant).
     * @tparam N          Number of columns of `A` (compile-time constant).
     * @tparam TRANSPOSE  When true, multiply by `Aᵀ` instead of `A` (default false).
     * @tparam ROW_MAJOR  When true, `A` is stored row-major (default false = column-major).
     * @param alpha  Scalar multiplier on the product.
     * @param A      Input matrix of `M*N` elements.
     * @param x      Input vector (length `N`, or `M` when transposed).
     * @param beta   Scalar multiplier on the prior `y`.
     * @param y      In/out vector (length `M`, or `N` when transposed).
     */
    template <typename T, uint32_t M, uint32_t N, bool TRANSPOSE = false, bool ROW_MAJOR = false, bool TRAILING_SYNC = true>
    __device__ void gemv(T alpha, const T *A, const T *x, T beta, T *y)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemv_impl_ct<T, M, N, TRANSPOSE, ROW_MAJOR>(rank, size, alpha, A, x, beta, y);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief Matrix-vector product: `y = alpha * A * x` (GEMV), compile-time size, no-beta overload.
     *
     * Compile-time-`M`,`N` overload that overwrites `y` (no `beta * y` term). NumPy
     * equivalent: `y = alpha*A@x` (or `alpha*A.T@x` when transposed).
     *
     * @tparam T          Scalar type (e.g. `float`, `double`).
     * @tparam M          Number of rows of `A` (compile-time constant).
     * @tparam N          Number of columns of `A` (compile-time constant).
     * @tparam TRANSPOSE  When true, multiply by `Aᵀ` instead of `A` (default false).
     * @tparam ROW_MAJOR  When true, `A` is stored row-major (default false = column-major).
     * @param alpha  Scalar multiplier on the product.
     * @param A      Input matrix of `M*N` elements.
     * @param x      Input vector (length `N`, or `M` when transposed).
     * @param y      Output vector (length `M`, or `N` when transposed).
     */
    template <typename T, uint32_t M, uint32_t N, bool TRANSPOSE = false, bool ROW_MAJOR = false, bool TRAILING_SYNC = true>
    __device__ void gemv(T alpha, const T *A, const T *x, T *y)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemv_impl_ct<T, M, N, TRANSPOSE, ROW_MAJOR>(rank, size, alpha, A, x, y);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    namespace warp {
        // Single-warp GEMV: one 32-lane warp computes the matvec, lanes striding over
        // the output rows (lane i owns output rows i, i+32, …). Each lane's row is an
        // independent inner product — no cross-lane communication, no shared scratch,
        // no `__syncthreads`. Reuses the block impl `gemv_impl_ct(lane, 32u, …)` exactly
        // as `warp::gemm` reuses `gemm_impl_ct`. For warp-per-problem kernels packing
        // many small matvecs into one block via independent warps. Full 32 lanes
        // required.
    
        /**
         * @brief Matrix-vector product within one warp: `y = alpha * A * x + beta * y` (GEMV), single-warp, compile-time size.
         *
         * One 32-lane warp computes the matvec with lanes striding over the output rows
         * of the `M×N` matrix `A` (each row an independent inner product). Set
         * `TRANSPOSE=true` for `Aᵀ * x` and `ROW_MAJOR=true` for row-major `A`. No shared
         * scratch, no `__syncthreads`; independent warps may run distinct problems
         * concurrently. Full 32 lanes required. `y` is read only when `beta != 0`
         * (BLAS semantics: `beta == 0` treats `y` as write-only). NumPy
         * equivalent: `y = alpha*A@x + beta*y` (or `alpha*A.T@x + beta*y` when transposed).
         *
         * @tparam T          Scalar type (e.g. `float`, `double`).
         * @tparam M          Number of rows of `A` (compile-time constant).
         * @tparam N          Number of columns of `A` (compile-time constant).
         * @tparam TRANSPOSE  When true, multiply by `Aᵀ` instead of `A` (default false).
         * @tparam ROW_MAJOR  When true, `A` is stored row-major (default false = column-major).
         * @param alpha  Scalar multiplier on the product.
         * @param A      Input matrix of `M*N` elements.
         * @param x      Input vector (length `N`, or `M` when transposed).
         * @param beta   Scalar multiplier on the prior `y`.
         * @param y      In/out vector (length `M`, or `N` when transposed).
         */
        template <typename T, uint32_t M, uint32_t N, bool TRANSPOSE = false, bool ROW_MAJOR = false>
        __device__ void gemv(T alpha, const T *A, const T *x, T beta, T *y)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            gemv_impl_ct<T, M, N, TRANSPOSE, ROW_MAJOR>(lane, 32u, alpha, A, x, beta, y);
            __syncwarp();
        }
    
        /**
         * @brief Matrix-vector product within one warp: `y = alpha * A * x` (GEMV), single-warp, compile-time size, implicit beta = 0.
         *
         * Overwrites `y` (no `beta * y` term — `y` is never read, so it is safe to write
         * into cold/uninitialized scratch). Otherwise identical to the beta overload
         * above. No shared scratch, no `__syncthreads`. Full 32 lanes required. NumPy
         * equivalent: `y = alpha*A@x` (or `alpha*A.T@x` when transposed).
         *
         * @tparam T          Scalar type (e.g. `float`, `double`).
         * @tparam M          Number of rows of `A` (compile-time constant).
         * @tparam N          Number of columns of `A` (compile-time constant).
         * @tparam TRANSPOSE  When true, multiply by `Aᵀ` instead of `A` (default false).
         * @tparam ROW_MAJOR  When true, `A` is stored row-major (default false = column-major).
         * @param alpha  Scalar multiplier on the product.
         * @param A      Input matrix of `M*N` elements.
         * @param x      Input vector (length `N`, or `M` when transposed).
         * @param y      Output vector (length `M`, or `N` when transposed; overwritten).
         */
        template <typename T, uint32_t M, uint32_t N, bool TRANSPOSE = false, bool ROW_MAJOR = false>
        __device__ void gemv(T alpha, const T *A, const T *x, T *y)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            gemv_impl_ct<T, M, N, TRANSPOSE, ROW_MAJOR>(lane, 32u, alpha, A, x, y);
            __syncwarp();
        }
    }
    // END GLASS src/base/L2/gemv.cuh
    
    // BEGIN GLASS src/base/L2/gemv_strided.cuh
    
    // Compile-time-size GEMV with an explicit column-major leading dimension.
    // A[i][j] = A_ptr[i + j*ROW_STRIDE].
    // When ROW_STRIDE == M this is identical to glass::gemv<T,M,N>.
    // Useful for spatial 6x6 matrices embedded in larger arrays (e.g., GRiD).
    //
    // Uses threadIdx-based parallelism (same as gemv_impl_ct): threads are
    // distributed over rows, and the inner column loop is fully unrolled by the
    // compiler since N and ROW_STRIDE are compile-time constants.
    
    /**
     * @brief Column-major GEMV with an explicit leading dimension: `y = alpha * A * x + beta * y`.
     *
     * Compile-time-`M`,`N` matrix-vector product where `A[i][j] = A[i + j*ROW_STRIDE]`,
     * letting an `M×N` matrix be addressed inside a larger array (e.g. a spatial 6×6
     * embedded in a wider buffer, as in GRiD). When `ROW_STRIDE == M` this is
     * identical to `glass::gemv<T,M,N>`. NumPy equivalent: `y = alpha*A@x + beta*y`.
     *
     * @tparam T           Scalar type (e.g. `float`, `double`).
     * @tparam M           Number of rows of `A` (compile-time constant).
     * @tparam N           Number of columns of `A` (compile-time constant).
     * @tparam ROW_STRIDE  Column-major leading dimension of `A` (default `M`).
     * @param alpha  Scalar multiplier on the product.
     * @param A      Input matrix, addressed at `A[row + col*ROW_STRIDE]`.
     * @param x      Input vector of length `N`.
     * @param beta   Scalar multiplier on the prior `y`.
     * @param y      In/out vector of length `M`.
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t ROW_STRIDE = M>
    __device__ void gemv_strided(T alpha, const T* A, const T* x, T beta, T* y)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        for (uint32_t row = rank; row < M; row += size) {
            T res = static_cast<T>(0);
            for (uint32_t col = 0; col < N; col++)
                res += A[row + col * ROW_STRIDE] * x[col];
            y[row] = beta_blend(alpha * res, beta, y[row]);
        }
    }
    
    /**
     * @brief Column-major GEMV with an explicit leading dimension: `y = alpha * A * x`, no-beta overload.
     *
     * No-`beta` variant of the strided GEMV that overwrites `y`, with
     * `A[i][j] = A[i + j*ROW_STRIDE]`. NumPy equivalent: `y = alpha*A@x`.
     *
     * @tparam T           Scalar type (e.g. `float`, `double`).
     * @tparam M           Number of rows of `A` (compile-time constant).
     * @tparam N           Number of columns of `A` (compile-time constant).
     * @tparam ROW_STRIDE  Column-major leading dimension of `A` (default `M`).
     * @param alpha  Scalar multiplier on the product.
     * @param A      Input matrix, addressed at `A[row + col*ROW_STRIDE]`.
     * @param x      Input vector of length `N`.
     * @param y      Output vector of length `M`.
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t ROW_STRIDE = M>
    __device__ void gemv_strided(T alpha, const T* A, const T* x, T* y)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        for (uint32_t row = rank; row < M; row += size) {
            T res = static_cast<T>(0);
            for (uint32_t col = 0; col < N; col++)
                res += A[row + col * ROW_STRIDE] * x[col];
            y[row] = alpha * res;
        }
    }
    // END GLASS src/base/L2/gemv_strided.cuh
    
    // BEGIN GLASS src/base/L2/gemv_segmented.cuh
    
    // Segmented (batched) compile-time-size column-major GEMV.
    //
    // Computes `segments` independent small GEMVs concurrently in a single block,
    // each of the form  y_seg = alpha * A_seg * x_seg + beta * y_seg, where every
    // A_seg is M rows x N cols, column-major with leading dimension ROW_STRIDE
    // (A_seg[i][j] = A[seg_a_off[seg] + i + j*ROW_STRIDE]).  M, N, ROW_STRIDE are
    // compile-time so the inner column loop is fully unrolled.  This is the
    // segmented analogue of gemv_strided<T,M,N,ROW_STRIDE>: instead of one
    // matrix it walks `segments` of them, with per-segment base offsets supplied by
    // the descriptor arrays seg_a_off / seg_x_off / seg_y_off.
    //
    // The kernel runs ONE block-stride loop over the flattened `segments*M` output
    // rows; thread `rank` owns row `r`, decoded as seg = r / M, row = r % M, so all
    // segments are computed simultaneously by the block (good when each GEMV is too
    // small (<= ~6xN) to fill the block on its own).
    //
    // When FUSE_SCALED_ADD is true an extra per-segment scaled vector add is fused
    // into the same pass: after computing the GEMV result for output row, we add
    // S[seg_s_off[seg] + row] * scalar[seg].  S has the same per-segment layout as
    // y (contiguous OUT_ROWS-vectors at seg_s_off), and scalar is one value per
    // segment.  This costs no extra global write — it folds into the single y[]
    // store, so FUSE_SCALED_ADD is only available on the non-atomic path (it relies
    // on the single read-modify-write of y).
    //
    // ── Generalizations (template flags, all default to the original behavior) ────
    // TRANSPOSE (default false): when true, each segment computes the TRANSPOSED
    //   product  y_seg[n] = alpha * Σ_i A_seg[i][n] * x_seg[i] (+ beta*y_seg[n]) for
    //   n in [0,N) — i.e.  Aᵀ_seg · x_seg.  A_seg is still M×N col-major with
    //   leading dimension ROW_STRIDE (A_seg[i][n] = A[a_off + i + n*ROW_STRIDE]),
    //   but now x_seg has M contiguous values and y_seg has N contiguous values.
    //   The block-stride loop runs over `segments*N` outputs; thread `rank` owns
    //   output n, decoded as seg = r / N, n = r % N.  This is the leaf→root
    //   (backward-pass) direction GRiD's recursions need (the Xᵀ·f map).
    //
    // ATOMIC_Y (default false): when true, the per-output result is accumulated
    //   into y via atomicAdd instead of being written.  This lets segments share or
    //   overlap their y ranges (the parent-accumulation / tree-reduction case where
    //   several child segments add into the SAME parent rows).  Under ATOMIC_Y the
    //   operation is the pure accumulate  y_seg += alpha*(A_seg·x_seg)  (or the
    //   transposed Aᵀ_seg·x_seg).  ── beta is intentionally NOT applied in the
    //   atomic path: scaling the prior y by beta is ill-defined under concurrent
    //   atomicAdds (the read of y races the writes), so the caller must pre-scale /
    //   pre-zero y before the call and treat this as a pure accumulator.  The atomic
    //   overload therefore takes no beta argument.  FUSE_SCALED_ADD is likewise
    //   unavailable under ATOMIC_Y (it folds into a non-atomic store); accumulate
    //   the scaled vector separately if needed.
    //
    // Output-row count per segment is  OUT_ROWS = (TRANSPOSE ? N : M).
    //
    // Descriptor / index convention (all IDX_T, element offsets not byte offsets):
    //   seg_a_off[seg] : base element index of A_seg within A   (len `segments`)
    //   seg_x_off[seg] : base element index of x_seg within x    (len `segments`)
    //   seg_y_off[seg] : base element index of y_seg within y    (len `segments`)
    //   seg_s_off[seg] : base element index of S_seg within S    (len `segments`, FUSE only)
    //   scalar[seg]    : per-segment fused-add multiplier         (len `segments`, FUSE only)
    // Non-transpose: x_seg is N contiguous values; y_seg / S_seg are M contiguous.
    // Transpose:     x_seg is M contiguous values; y_seg / S_seg are N contiguous.
    // Segments may overlap or alias freely in A/x.  Without ATOMIC_Y, y_seg ranges
    // must be DISJOINT (each output row written exactly once); with ATOMIC_Y they
    // may overlap freely (results are atomically summed).
    
    /**
     * @brief Segmented (batched) column-major GEMV: `y_seg = alpha*A_seg*x_seg + beta*y_seg` for each segment.
     *
     * Computes `segments` independent small GEMVs concurrently in one block. Each
     * `A_seg` is `M×N`, column-major with leading dimension `ROW_STRIDE`, and base
     * offsets into the flat `A`/`x`/`y` arrays come from the descriptor arrays. A
     * single block-stride loop walks the flattened `segments * OUT_ROWS` outputs
     * (`OUT_ROWS = TRANSPOSE ? N : M`). Optional flags: `TRANSPOSE` computes
     * `Aᵀ_seg · x_seg` (the leaf→root direction); `ATOMIC_Y` accumulates into `y`
     * via `atomicAdd` so segments may overlap (`beta` is then ignored — pre-scale
     * `y` yourself); `FUSE_SCALED_ADD` folds an extra per-segment `S * scalar` term
     * into the single `y` store (non-atomic path only).
     *
     * @tparam T               Scalar type (e.g. `float`, `double`).
     * @tparam M               Rows per segment matrix (compile-time constant).
     * @tparam N               Columns per segment matrix (compile-time constant).
     * @tparam ROW_STRIDE      Column-major leading dimension of each `A_seg` (default `M`).
     * @tparam FUSE_SCALED_ADD When true, add `S[seg]*scalar[seg]` into the output (non-atomic only).
     * @tparam TRANSPOSE       When true, each segment computes `Aᵀ_seg · x_seg`.
     * @tparam ATOMIC_Y        When true, accumulate into `y` with `atomicAdd` (overlap-safe).
     * @tparam IDX_T           Index type of the offset descriptor arrays (default `int`).
     * @param segments    Number of independent GEMVs.
     * @param seg_a_off   Per-segment base element offsets of `A_seg` within `A`.
     * @param seg_x_off   Per-segment base element offsets of `x_seg` within `x`.
     * @param seg_y_off   Per-segment base element offsets of `y_seg` within `y`.
     * @param A           Flat backing array of all segment matrices.
     * @param x           Flat backing array of all segment input vectors.
     * @param y           Flat backing array of all segment output vectors (in/out).
     * @param alpha       Scalar multiplier on each segment product.
     * @param beta        Scalar multiplier on the prior `y` (ignored under `ATOMIC_Y`).
     * @param seg_s_off   Per-segment offsets of `S_seg` within `S` (FUSE only).
     * @param S           Flat backing array for the fused scaled-add term (FUSE only).
     * @param scalar      Per-segment multiplier for the fused scaled-add (FUSE only).
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t ROW_STRIDE = M,
              bool FUSE_SCALED_ADD = false, bool TRANSPOSE = false,
              bool ATOMIC_Y = false, typename IDX_T = int>
    __device__ void gemv_segmented(
        uint32_t segments,
        const IDX_T* seg_a_off, const IDX_T* seg_x_off, const IDX_T* seg_y_off,
        const T* A, const T* x, T* y, T alpha, T beta,
        const IDX_T* seg_s_off = nullptr, const T* S = nullptr, const T* scalar = nullptr)
    {
        static_assert(!(ATOMIC_Y && FUSE_SCALED_ADD),
                      "FUSE_SCALED_ADD folds into a non-atomic store; not available under ATOMIC_Y");
        constexpr uint32_t OUT_ROWS = TRANSPOSE ? N : M;   // output rows per segment
        constexpr uint32_t CONTRACT = TRANSPOSE ? M : N;   // contracted dimension
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        uint32_t total = segments * OUT_ROWS;
        for (uint32_t r = rank; r < total; r += size) {
            uint32_t seg = r / OUT_ROWS;
            uint32_t out = r % OUT_ROWS;                    // output index within segment
            uint32_t a_base = static_cast<uint32_t>(seg_a_off[seg]);
            uint32_t x_base = static_cast<uint32_t>(seg_x_off[seg]);
            uint32_t y_base = static_cast<uint32_t>(seg_y_off[seg]);
            T res = static_cast<T>(0);
            #pragma unroll
            for (uint32_t k = 0; k < CONTRACT; k++) {
                // Non-transpose: A[i=out][j=k]  → A[out + k*ROW_STRIDE]
                // Transpose:     A[i=k][n=out]  → A[k   + out*ROW_STRIDE]
                uint32_t a_idx = TRANSPOSE ? (a_base + k + out * ROW_STRIDE)
                                           : (a_base + out + k * ROW_STRIDE);
                res += A[a_idx] * x[x_base + k];
            }
            if (ATOMIC_Y) {
                atomicAdd(&y[y_base + out], alpha * res);
            } else {
                T val = beta_blend(alpha * res, beta, y[y_base + out]);
                if (FUSE_SCALED_ADD)
                    val += S[static_cast<uint32_t>(seg_s_off[seg]) + out] * scalar[seg];
                y[y_base + out] = val;
            }
        }
    }
    
    /**
     * @brief Segmented (batched) column-major GEMV, no-beta overload: `y_seg = alpha*A_seg*x_seg` per segment.
     *
     * No-`beta` variant of `gemv_segmented`: each segment overwrites its
     * `y_seg` (optionally plus the fused scaled-add) or computes the transpose. This
     * also serves as the `ATOMIC_Y` entry point, since atomic accumulate takes no
     * `beta` (see the full overload's note on beta-under-atomic).
     *
     * @tparam T               Scalar type (e.g. `float`, `double`).
     * @tparam M               Rows per segment matrix (compile-time constant).
     * @tparam N               Columns per segment matrix (compile-time constant).
     * @tparam ROW_STRIDE      Column-major leading dimension of each `A_seg` (default `M`).
     * @tparam FUSE_SCALED_ADD When true, add `S[seg]*scalar[seg]` into the output (non-atomic only).
     * @tparam TRANSPOSE       When true, each segment computes `Aᵀ_seg · x_seg`.
     * @tparam ATOMIC_Y        When true, accumulate into `y` with `atomicAdd` (overlap-safe).
     * @tparam IDX_T           Index type of the offset descriptor arrays (default `int`).
     * @param segments    Number of independent GEMVs.
     * @param seg_a_off   Per-segment base element offsets of `A_seg` within `A`.
     * @param seg_x_off   Per-segment base element offsets of `x_seg` within `x`.
     * @param seg_y_off   Per-segment base element offsets of `y_seg` within `y`.
     * @param A           Flat backing array of all segment matrices.
     * @param x           Flat backing array of all segment input vectors.
     * @param y           Flat backing array of all segment output vectors (out, or accumulated under `ATOMIC_Y`).
     * @param alpha       Scalar multiplier on each segment product.
     * @param seg_s_off   Per-segment offsets of `S_seg` within `S` (FUSE only).
     * @param S           Flat backing array for the fused scaled-add term (FUSE only).
     * @param scalar      Per-segment multiplier for the fused scaled-add (FUSE only).
     */
    // No-beta overload: y_seg = alpha * A_seg * x_seg (+ fused scaled add), or its
    // transpose.  Doubles as the ATOMIC_Y entry point (atomic accumulate takes no
    // beta — see the header note on beta-under-atomic).
    template <typename T, uint32_t M, uint32_t N, uint32_t ROW_STRIDE = M,
              bool FUSE_SCALED_ADD = false, bool TRANSPOSE = false,
              bool ATOMIC_Y = false, typename IDX_T = int>
    __device__ void gemv_segmented(
        uint32_t segments,
        const IDX_T* seg_a_off, const IDX_T* seg_x_off, const IDX_T* seg_y_off,
        const T* A, const T* x, T* y, T alpha,
        const IDX_T* seg_s_off = nullptr, const T* S = nullptr, const T* scalar = nullptr)
    {
        static_assert(!(ATOMIC_Y && FUSE_SCALED_ADD),
                      "FUSE_SCALED_ADD folds into a non-atomic store; not available under ATOMIC_Y");
        constexpr uint32_t OUT_ROWS = TRANSPOSE ? N : M;
        constexpr uint32_t CONTRACT = TRANSPOSE ? M : N;
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        uint32_t total = segments * OUT_ROWS;
        for (uint32_t r = rank; r < total; r += size) {
            uint32_t seg = r / OUT_ROWS;
            uint32_t out = r % OUT_ROWS;
            uint32_t a_base = static_cast<uint32_t>(seg_a_off[seg]);
            uint32_t x_base = static_cast<uint32_t>(seg_x_off[seg]);
            uint32_t y_base = static_cast<uint32_t>(seg_y_off[seg]);
            T res = static_cast<T>(0);
            #pragma unroll
            for (uint32_t k = 0; k < CONTRACT; k++) {
                uint32_t a_idx = TRANSPOSE ? (a_base + k + out * ROW_STRIDE)
                                           : (a_base + out + k * ROW_STRIDE);
                res += A[a_idx] * x[x_base + k];
            }
            if (ATOMIC_Y) {
                atomicAdd(&y[y_base + out], alpha * res);
            } else {
                T val = alpha * res;
                if (FUSE_SCALED_ADD)
                    val += S[static_cast<uint32_t>(seg_s_off[seg]) + out] * scalar[seg];
                y[y_base + out] = val;
            }
        }
    }
    // END GLASS src/base/L2/gemv_segmented.cuh
    
    // BEGIN GLASS src/base/L3/gemm.cuh
    
    // ─── GEMM: standard-BLAS convention ──────────────────────────────────────────
    //
    //   C = alpha * op(A) * op(B) + beta * C
    //
    //   C is M×N, the contraction dimension is K (this matches BLAS / cuBLASDx /
    //   NumPy / Eigen — `C[m,n] = alpha·Σ_k op(A)[m,k]·op(B)[k,n] + beta·C[m,n]`).
    //
    //   op(A) is M×K:  TRANSPOSE_A=false ⇒ A is M×K (A[m + k*M]);
    //                  TRANSPOSE_A=true  ⇒ A is K×M (A[k + m*K], op(A)=Aᵀ).
    //   op(B) is K×N:  TRANSPOSE_B=false ⇒ B is K×N (B[k + n*K]);
    //                  TRANSPOSE_B=true  ⇒ B is N×K (B[n + k*N], op(B)=Bᵀ).
    //   C:             ROW_MAJOR_C=false ⇒ column-major (C[m + n*M], LDC=M);
    //                  ROW_MAJOR_C=true  ⇒ row-major   (C[m*N + n]).
    //
    // All four transpose combinations work at any M,N,K (no squareness assumption).
    // Each C[m,n] is written by exactly one thread/lane (serial-K inner loop, no
    // reduction) ⇒ trivially thread-count invariant. Column-major operands by default.
    //
    // Fast path: when TRANSPOSE_A=false and ROW_MAJOR_C=false (any TRANSPOSE_B),
    // threads own 4-row register tiles of a C column (B value reused across 4 FMAs,
    // contiguous A rows vector-loaded when aligned) — same per-element ascending-k
    // accumulation order, so results stay bit-identical across thread counts.
    // A, B, C must not alias each other (C is written while A/B are read; declared
    // __restrict__). A and B may point to the SAME data (both are read-only).
    //
    // Row-major operands need no separate path: a row-major M×K matrix is exactly a
    // column-major K×M matrix, so pass it with the matching TRANSPOSE flag (see
    // examples/11_rowmajor_is_transpose.cu). That is why there is a single ROW_MAJOR_C
    // output flag and no per-operand row-major flags.
    //
    // NumPy: C = alpha*opA(A) @ opB(B) + beta*C ;
    // Eigen: C.noalias() = alpha*(opA(A)*opB(B)) + beta*C;  (column-major default)
    
    // ─── shared 4-row register-tile helpers ──────────────────────────────────────
    // Identical guarded copy lives in L2/gemv.cuh, L3/gemm.cuh, and L3/syrk.cuh:
    // these base headers are #include'd inside `namespace glass { }` (with #pragma
    // once), so whichever the umbrella pulls in first defines the block and the
    // guard skips the twins — no dependency on include order.
    #ifndef GRID_VENDORED_GLASS_TILE4_HELPERS_DEFINED
    #define GRID_VENDORED_GLASS_TILE4_HELPERS_DEFINED
    
    // Scalar types with a 16-byte vector load (float4 / 2×double2).
    template <typename T> struct tile4_has_vec { static constexpr bool value = false; };
    template <> struct tile4_has_vec<float>  { static constexpr bool value = true; };
    template <> struct tile4_has_vec<double> { static constexpr bool value = true; };
    
    // Load 4 consecutive elements p[0..3] into registers. The vector overloads
    // require `p` 16-byte aligned. Loads only change HOW values reach registers —
    // never any output's accumulation order — so vector vs scalar is bit-identical.
    __device__ __forceinline__ void tile4_load(const float *p, float &a0, float &a1, float &a2, float &a3)
    {
        float4 v = *reinterpret_cast<const float4 *>(p);
        a0 = v.x; a1 = v.y; a2 = v.z; a3 = v.w;
    }
    __device__ __forceinline__ void tile4_load(const double *p, double &a0, double &a1, double &a2, double &a3)
    {
        double2 v0 = *reinterpret_cast<const double2 *>(p);
        double2 v1 = *reinterpret_cast<const double2 *>(p + 2);
        a0 = v0.x; a1 = v0.y; a2 = v1.x; a3 = v1.y;
    }
    template <typename T>
    __device__ __forceinline__ void tile4_load(const T *p, T &a0, T &a1, T &a2, T &a3)
    {
        a0 = p[0]; a1 = p[1]; a2 = p[2]; a3 = p[3];
    }
    
    // Base-pointer half of the vector-load precondition: with a leading dimension
    // that is a multiple of 4 (float; 2 suffices for double but we require 4
    // uniformly) and 4-row tiles starting at row r ≡ 0 (mod 4), every tile start
    // A + r + k*ld stays 16-byte aligned iff the base pointer is.
    template <typename T>
    __device__ __forceinline__ bool tile4_aligned(const T *p)
    {
        return (reinterpret_cast<uintptr_t>(p) & 0xFu) == 0u;
    }
    // 4-row tiles pay off only when every C column decomposes into WHOLE tiles
    // and M is big enough for the B-register reuse to beat the 4x loss in
    // parallel work units: an M%4 tail runs its rows serially inside one work
    // unit and bottlenecks the whole block (measured sm_120: non-multiple-of-4
    // M loses at every size probed — 5..81), and M=8 leaves too few tiles to
    // feed more than one warp (loses at 64+ threads). Multiples of 4 from 12 up
    // win at every probed thread count.
    __host__ __device__ constexpr bool tile4_profitable(uint32_t m)
    {
        return (m % 4u == 0u) && (m >= 12u);
    }
    #endif  // GRID_VENDORED_GLASS_TILE4_HELPERS_DEFINED
    
    // ─── 4-row register-tiled gemm cores (TRANSPOSE_A=false, ROW_MAJOR_C=false) ──
    // Each thread owns TILE=4 CONSECUTIVE ROWS of one C column: the flat M*N output
    // element space becomes ceil(M/4)*N row-tiles, strided over the block exactly
    // like gemm_impl strides elements (thread t handles tiles t, t+size, …). Per k,
    // B[k,n] is loaded ONCE into a register and reused by 4 FMAs against the
    // contiguous A[r..r+3, k] (one float4 / two double2 when M%4==0 and A is
    // 16-byte aligned; scalar loads otherwise and for the M%4 tail rows). Each C
    // element accumulates in its own register with the SAME serial ascending-k
    // chain as the untiled loop and is written by exactly one thread, so
    // thread-count invariance stays bit-identical. HAS_BETA folds the beta /
    // implicit-beta=0 overloads into one body (beta unused and C never read when
    // false). No interior sync needed — disjoint outputs, exactly like gemm_impl.
    
    template <typename T, bool TRANSPOSE_B, bool HAS_BETA, bool VEC>
    __device__ __forceinline__ void gemm_tile4_loop(uint32_t rank, uint32_t size,
                                                    uint32_t m_, uint32_t n_, uint32_t k_,
                                                    T alpha, const T *__restrict__ A,
                                                    const T *__restrict__ B,
                                                    T beta, T *__restrict__ C)
    {
        const uint32_t tpc    = (m_ + 3u) / 4u;   // 4-row tiles per column of C
        const uint32_t ntiles = tpc * n_;
        for (uint32_t t = rank; t < ntiles; t += size) {
            const uint32_t n = t / tpc;
            const uint32_t r = (t % tpc) * 4u;
            if (r + 4u <= m_) {                    // full 4-row tile
                T acc0 = static_cast<T>(0), acc1 = static_cast<T>(0);
                T acc2 = static_cast<T>(0), acc3 = static_cast<T>(0);
                for (uint32_t k = 0; k < k_; k++) {
                    const T b = TRANSPOSE_B ? B[n + k*n_] : B[k + n*k_];
                    T a0, a1, a2, a3;
                    if constexpr (VEC) {
                        tile4_load(A + (r + k*m_), a0, a1, a2, a3);
                    } else {
                        a0 = A[r      + k*m_]; a1 = A[r + 1u + k*m_];
                        a2 = A[r + 2u + k*m_]; a3 = A[r + 3u + k*m_];
                    }
                    acc0 += a0 * b; acc1 += a1 * b; acc2 += a2 * b; acc3 += a3 * b;
                }
                T *__restrict__ c = C + (r + n*m_);
                if constexpr (HAS_BETA) {
                    c[0] = beta_blend(alpha*acc0, beta, c[0]);
                    c[1] = beta_blend(alpha*acc1, beta, c[1]);
                    c[2] = beta_blend(alpha*acc2, beta, c[2]);
                    c[3] = beta_blend(alpha*acc3, beta, c[3]);
                } else {
                    c[0] = alpha*acc0; c[1] = alpha*acc1;
                    c[2] = alpha*acc2; c[3] = alpha*acc3;
                }
            } else {                               // m_%4 tail rows: scalar per row
                for (uint32_t m = r; m < m_; m++) {
                    T res = static_cast<T>(0);
                    for (uint32_t k = 0; k < k_; k++) {
                        const T b = TRANSPOSE_B ? B[n + k*n_] : B[k + n*k_];
                        res += A[m + k*m_] * b;
                    }
                    if constexpr (HAS_BETA) C[m + n*m_] = beta_blend(alpha*res, beta, C[m + n*m_]);
                    else                    C[m + n*m_] = alpha*res;
                }
            }
        }
    }
    
    template <typename T, bool TRANSPOSE_B, bool HAS_BETA>
    __device__ void gemm_tile4(uint32_t rank, uint32_t size,
                               uint32_t m_, uint32_t n_, uint32_t k_,
                               T alpha, const T *__restrict__ A, const T *__restrict__ B,
                               T beta, T *__restrict__ C)
    {
        if constexpr (tile4_has_vec<T>::value) {
            if ((m_ % 4u == 0u) && tile4_aligned(A)) {
                gemm_tile4_loop<T, TRANSPOSE_B, HAS_BETA, true>(rank, size, m_, n_, k_, alpha, A, B, beta, C);
                return;
            }
        }
        gemm_tile4_loop<T, TRANSPOSE_B, HAS_BETA, false>(rank, size, m_, n_, k_, alpha, A, B, beta, C);
    }
    
    // compile-time twin: M, N, K as template params (magic-number div/mod, fully
    // unrolled k loop; M%4 tail statically absent when M is a multiple of 4).
    template <typename T, uint32_t M, uint32_t N, uint32_t K, bool TRANSPOSE_B, bool HAS_BETA, bool VEC>
    __device__ __forceinline__ void gemm_tile4_loop_ct(uint32_t rank, uint32_t size,
                                                       T alpha, const T *__restrict__ A,
                                                       const T *__restrict__ B,
                                                       T beta, T *__restrict__ C)
    {
        constexpr uint32_t TPC    = (M + 3u) / 4u;   // 4-row tiles per column of C
        constexpr uint32_t NTILES = TPC * N;
        for (uint32_t t = rank; t < NTILES; t += size) {
            const uint32_t n = t / TPC;
            const uint32_t r = (t % TPC) * 4u;
            if (r + 4u <= M) {                     // full 4-row tile
                T acc0 = static_cast<T>(0), acc1 = static_cast<T>(0);
                T acc2 = static_cast<T>(0), acc3 = static_cast<T>(0);
                for (uint32_t k = 0; k < K; k++) {
                    const T b = TRANSPOSE_B ? B[n + k*N] : B[k + n*K];
                    T a0, a1, a2, a3;
                    if constexpr (VEC) {
                        tile4_load(A + (r + k*M), a0, a1, a2, a3);
                    } else {
                        a0 = A[r      + k*M]; a1 = A[r + 1u + k*M];
                        a2 = A[r + 2u + k*M]; a3 = A[r + 3u + k*M];
                    }
                    acc0 += a0 * b; acc1 += a1 * b; acc2 += a2 * b; acc3 += a3 * b;
                }
                T *__restrict__ c = C + (r + n*M);
                if constexpr (HAS_BETA) {
                    c[0] = beta_blend(alpha*acc0, beta, c[0]);
                    c[1] = beta_blend(alpha*acc1, beta, c[1]);
                    c[2] = beta_blend(alpha*acc2, beta, c[2]);
                    c[3] = beta_blend(alpha*acc3, beta, c[3]);
                } else {
                    c[0] = alpha*acc0; c[1] = alpha*acc1;
                    c[2] = alpha*acc2; c[3] = alpha*acc3;
                }
            } else {                               // M%4 tail rows: scalar per row
                for (uint32_t m = r; m < M; m++) {
                    T res = static_cast<T>(0);
                    for (uint32_t k = 0; k < K; k++) {
                        const T b = TRANSPOSE_B ? B[n + k*N] : B[k + n*K];
                        res += A[m + k*M] * b;
                    }
                    if constexpr (HAS_BETA) C[m + n*M] = beta_blend(alpha*res, beta, C[m + n*M]);
                    else                    C[m + n*M] = alpha*res;
                }
            }
        }
    }
    
    template <typename T, uint32_t M, uint32_t N, uint32_t K, bool TRANSPOSE_B, bool HAS_BETA>
    __device__ void gemm_tile4_ct(uint32_t rank, uint32_t size,
                                  T alpha, const T *__restrict__ A, const T *__restrict__ B,
                                  T beta, T *__restrict__ C)
    {
        if constexpr (tile4_has_vec<T>::value && (M % 4u == 0u)) {
            if (tile4_aligned(A)) {
                gemm_tile4_loop_ct<T, M, N, K, TRANSPOSE_B, HAS_BETA, true>(rank, size, alpha, A, B, beta, C);
                return;
            }
        }
        gemm_tile4_loop_ct<T, M, N, K, TRANSPOSE_B, HAS_BETA, false>(rank, size, alpha, A, B, beta, C);
    }
    
    // ─── core impls: explicit rank/size + (TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C) ──
    // No-transpose-A, column-major-C combos route to the 4-row register-tiled core
    // when tile4_profitable(m) says the tiles win (M a multiple of 4, M >= 8 —
    // measured sm_120 crossover); every other case takes the one-output-per-thread
    // flat loop, byte-identical to before. Tiled and flat accumulate each C element
    // with the same serial ascending-k chain, so the two paths agree bit-for-bit
    // and the runtime gate cannot break thread-count invariance.
    
    template <typename T, bool TRANSPOSE_A, bool TRANSPOSE_B, bool ROW_MAJOR_C>
    __device__ void gemm_impl(uint32_t rank, uint32_t size,
                              uint32_t m_, uint32_t n_, uint32_t k_,
                              T alpha, const T *__restrict__ A, const T *__restrict__ B,
                              T beta, T *__restrict__ C)
    {
        if constexpr (!TRANSPOSE_A && !ROW_MAJOR_C) {
            if (tile4_profitable(m_)) {
                gemm_tile4<T, TRANSPOSE_B, true>(rank, size, m_, n_, k_, alpha, A, B, beta, C);
                return;
            }
        }
        const uint32_t maxel = m_ * n_;
        for (uint32_t el = rank; el < maxel; el += size) {
            uint32_t m = el % m_, n = el / m_;
            T res = static_cast<T>(0);
            for (uint32_t k = 0; k < k_; k++) {
                T a = TRANSPOSE_A ? A[k + m*k_] : A[m + k*m_];
                T b = TRANSPOSE_B ? B[n + k*n_] : B[k + n*k_];
                res += a * b;
            }
            uint32_t cidx = ROW_MAJOR_C ? (m*n_ + n) : (m + n*m_);
            C[cidx] = beta_blend(alpha*res, beta, C[cidx]);
        }
    }
    
    template <typename T, bool TRANSPOSE_A, bool TRANSPOSE_B, bool ROW_MAJOR_C>
    __device__ void gemm_impl(uint32_t rank, uint32_t size,
                              uint32_t m_, uint32_t n_, uint32_t k_,
                              T alpha, const T *__restrict__ A, const T *__restrict__ B,
                              T *__restrict__ C)
    {
        if constexpr (!TRANSPOSE_A && !ROW_MAJOR_C) {
            if (tile4_profitable(m_)) {
                gemm_tile4<T, TRANSPOSE_B, false>(rank, size, m_, n_, k_, alpha, A, B, static_cast<T>(0), C);
                return;
            }
        }
        const uint32_t maxel = m_ * n_;
        for (uint32_t el = rank; el < maxel; el += size) {
            uint32_t m = el % m_, n = el / m_;
            T res = static_cast<T>(0);
            for (uint32_t k = 0; k < k_; k++) {
                T a = TRANSPOSE_A ? A[k + m*k_] : A[m + k*m_];
                T b = TRANSPOSE_B ? B[n + k*n_] : B[k + n*k_];
                res += a * b;
            }
            uint32_t cidx = ROW_MAJOR_C ? (m*n_ + n) : (m + n*m_);
            C[cidx] = alpha*res;
        }
    }
    
    // compile-time impl: M, N, K as template params so el%M and el/M use cheap
    // compiler-generated magic-number multiply instead of MUFU.RCP, and the inner
    // K-loop is fully unrolled.
    template <typename T, uint32_t M, uint32_t N, uint32_t K,
              bool TRANSPOSE_A, bool TRANSPOSE_B, bool ROW_MAJOR_C>
    __device__ void gemm_impl_ct(uint32_t rank, uint32_t size,
                                 T alpha, const T *__restrict__ A, const T *__restrict__ B,
                                 T beta, T *__restrict__ C)
    {
        if constexpr (!TRANSPOSE_A && !ROW_MAJOR_C && tile4_profitable(M)) {
            gemm_tile4_ct<T, M, N, K, TRANSPOSE_B, true>(rank, size, alpha, A, B, beta, C);
        } else {
            constexpr uint32_t maxel = M * N;
            for (uint32_t el = rank; el < maxel; el += size) {
                uint32_t m = el % M, n = el / M;
                T res = static_cast<T>(0);
                for (uint32_t k = 0; k < K; k++) {
                    T a = TRANSPOSE_A ? A[k + m*K] : A[m + k*M];
                    T b = TRANSPOSE_B ? B[n + k*N] : B[k + n*K];
                    res += a * b;
                }
                uint32_t cidx = ROW_MAJOR_C ? (m*N + n) : (m + n*M);
                C[cidx] = beta_blend(alpha*res, beta, C[cidx]);
            }
        }
    }
    
    template <typename T, uint32_t M, uint32_t N, uint32_t K,
              bool TRANSPOSE_A, bool TRANSPOSE_B, bool ROW_MAJOR_C>
    __device__ void gemm_impl_ct(uint32_t rank, uint32_t size,
                                 T alpha, const T *__restrict__ A, const T *__restrict__ B,
                                 T *__restrict__ C)
    {
        if constexpr (!TRANSPOSE_A && !ROW_MAJOR_C && tile4_profitable(M)) {
            gemm_tile4_ct<T, M, N, K, TRANSPOSE_B, false>(rank, size, alpha, A, B, static_cast<T>(0), C);
        } else {
            constexpr uint32_t maxel = M * N;
            for (uint32_t el = rank; el < maxel; el += size) {
                uint32_t m = el % M, n = el / M;
                T res = static_cast<T>(0);
                for (uint32_t k = 0; k < K; k++) {
                    T a = TRANSPOSE_A ? A[k + m*K] : A[m + k*M];
                    T b = TRANSPOSE_B ? B[n + k*N] : B[k + n*K];
                    res += a * b;
                }
                uint32_t cidx = ROW_MAJOR_C ? (m*N + n) : (m + n*M);
                C[cidx] = alpha*res;
            }
        }
    }
    
    // ─── runtime variants ─────────────────────────────────────────────────────────
    
    /**
     * @brief General matrix-matrix multiply: `C = alpha * op(A) * op(B) + beta * C` (GEMM).
     *
     * Standard BLAS convention: `C` is `m×n`, contraction `k`. Runtime-size,
     * single-block, flat-element parallelism: each thread owns output elements
     * strided over the block. NumPy: `C = alpha * opA(A) @ opB(B) + beta * C`;
     * Eigen: `C.noalias() = alpha*(opA(A)*opB(B)) + beta*C;`.
     *
     * @tparam T  Scalar type.
     * @tparam TRANSPOSE_A  If true, `A` is `k×m` and `op(A)=Aᵀ` (else `A` is `m×k`).
     * @tparam TRANSPOSE_B  If true, `B` is `n×k` and `op(B)=Bᵀ` (else `B` is `k×n`).
     * @tparam ROW_MAJOR_C  Output storage order (false = column-major / Fortran, LDC=m).
     * @param m,n,k  Dimensions: `C` is `m×n`, contraction `k`.
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices (column-major; shapes per the transpose flags).
     * @param beta   Scalar multiplier on the existing C (read only when `beta != 0`).
     * @param C      In/out result matrix.
     */
    template <typename T, bool TRANSPOSE_A = false, bool TRANSPOSE_B = false, bool ROW_MAJOR_C = false, bool TRAILING_SYNC = true>
    __device__ void gemm(uint32_t m, uint32_t n, uint32_t k,
                         T alpha, const T *__restrict__ A, const T *__restrict__ B,
                         T beta, T *__restrict__ C)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemm_impl<T, TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C>(rank, size, m, n, k, alpha, A, B, beta, C);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief GEMM with implicit `beta = 0`: `C = alpha * op(A) * op(B)` (overwrite).
     *
     * Runtime-size overload that overwrites C (the existing C is not read), avoiding
     * the `beta * C` term. NumPy: `C = alpha * opA(A) @ opB(B)`.
     *
     * @tparam T  Scalar type.
     * @tparam TRANSPOSE_A  If true, `A` is `k×m` and `op(A)=Aᵀ`.
     * @tparam TRANSPOSE_B  If true, `B` is `n×k` and `op(B)=Bᵀ`.
     * @tparam ROW_MAJOR_C  Output storage order (false = column-major).
     * @param m,n,k  Dimensions: `C` is `m×n`, contraction `k`.
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices.
     * @param C      Output result matrix (overwritten).
     */
    template <typename T, bool TRANSPOSE_A = false, bool TRANSPOSE_B = false, bool ROW_MAJOR_C = false, bool TRAILING_SYNC = true>
    __device__ void gemm(uint32_t m, uint32_t n, uint32_t k,
                         T alpha, const T *__restrict__ A, const T *__restrict__ B,
                         T *__restrict__ C)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemm_impl<T, TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C>(rank, size, m, n, k, alpha, A, B, C);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    // ─── compile-time size variants ───────────────────────────────────────────────
    
    /**
     * @brief Compile-time-size GEMM: `C = alpha * op(A) * op(B) + beta * C` (GEMM).
     *
     * Dimensions are template parameters so the compiler unrolls the inner loop and
     * replaces the `el % M` / `el / M` index math with magic-number multiplies.
     * Standard BLAS convention: `C` is `M×N`, contraction `K`. NumPy:
     * `C = alpha * opA(A) @ opB(B) + beta * C`; Eigen:
     * `C.noalias() = alpha*(opA(A)*opB(B)) + beta*C;`.
     *
     * @tparam T  Scalar type.
     * @tparam M,N,K  `C` is `M×N`, contraction `K`.
     * @tparam TRANSPOSE_A  If true, `A` is `K×M` and `op(A)=Aᵀ` (else `A` is `M×K`).
     * @tparam TRANSPOSE_B  If true, `B` is `N×K` and `op(B)=Bᵀ` (else `B` is `K×N`).
     * @tparam ROW_MAJOR_C  Output storage order (false = column-major / Fortran, LDC=M).
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices.
     * @param beta   Scalar multiplier on the existing C (read only when `beta != 0`).
     * @param C      In/out result matrix.
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t K,
              bool TRANSPOSE_A = false, bool TRANSPOSE_B = false, bool ROW_MAJOR_C = false, bool TRAILING_SYNC = true>
    __device__ void gemm(T alpha, const T *__restrict__ A, const T *__restrict__ B, T beta, T *__restrict__ C)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemm_impl_ct<T, M, N, K, TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C>(rank, size, alpha, A, B, beta, C);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    /**
     * @brief Compile-time-size GEMM with implicit `beta = 0`: `C = alpha * op(A) * op(B)`.
     *
     * Compile-time-size overload that overwrites C (the existing C is not read).
     * NumPy: `C = alpha * opA(A) @ opB(B)`.
     *
     * @tparam T  Scalar type.
     * @tparam M,N,K  `C` is `M×N`, contraction `K`.
     * @tparam TRANSPOSE_A  If true, `A` is `K×M` and `op(A)=Aᵀ`.
     * @tparam TRANSPOSE_B  If true, `B` is `N×K` and `op(B)=Bᵀ`.
     * @tparam ROW_MAJOR_C  Output storage order (false = column-major).
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices.
     * @param C      Output result matrix (overwritten).
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t K,
              bool TRANSPOSE_A = false, bool TRANSPOSE_B = false, bool ROW_MAJOR_C = false, bool TRAILING_SYNC = true>
    __device__ void gemm(T alpha, const T *__restrict__ A, const T *__restrict__ B, T *__restrict__ C)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        gemm_impl_ct<T, M, N, K, TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C>(rank, size, alpha, A, B, C);
        if constexpr (TRAILING_SYNC) __syncthreads();
    }
    
    // ─── single-warp compile-time GEMM ───────────────────────────────────────────
    namespace warp {
        /**
         * @brief Single-warp compile-time-size GEMM: `C = alpha * op(A) * op(B) + beta * C`.
         *
         * One 32-lane warp computes the product with flat per-element parallelism
         * (lanes stride over the `M*N` outputs, serial-K inner loop) — same semantics
         * as the block-scoped compile-time `gemm`, but scoped to a single warp for
         * warp-per-problem kernels (e.g. 4×4 homogeneous-transform multiplies). No
         * inter-lane communication, no sync. `C` must not alias `A`/`B`.
         *
         * @tparam T  Scalar type.
         * @tparam M,N,K  `C` is `M×N`, contraction `K`.
         * @tparam TRANSPOSE_A  If true, `A` is `K×M` and `op(A)=Aᵀ`.
         * @tparam TRANSPOSE_B  If true, `B` is `N×K` and `op(B)=Bᵀ`.
         * @tparam ROW_MAJOR_C  Output storage order (false = column-major).
         * @param alpha  Scalar multiplier on the product.
         * @param A,B    Input matrices.
         * @param beta   Scalar multiplier on the existing C (read only when `beta != 0`).
         * @param C      In/out result matrix.
         */
        template <typename T, uint32_t M, uint32_t N, uint32_t K,
                  bool TRANSPOSE_A = false, bool TRANSPOSE_B = false, bool ROW_MAJOR_C = false>
        __device__ void gemm(T alpha, const T *__restrict__ A, const T *__restrict__ B, T beta, T *__restrict__ C)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            gemm_impl_ct<T, M, N, K, TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C>(lane, 32u, alpha, A, B, beta, C);
        }
    
        /**
         * @brief Single-warp compile-time-size GEMM with implicit `beta = 0`: `C = alpha * op(A) * op(B)`.
         *
         * Overwrites C (the existing C is not read). Otherwise identical to the
         * beta overload above.
         *
         * @tparam T  Scalar type.
         * @tparam M,N,K  `C` is `M×N`, contraction `K`.
         * @tparam TRANSPOSE_A  If true, `A` is `K×M` and `op(A)=Aᵀ`.
         * @tparam TRANSPOSE_B  If true, `B` is `N×K` and `op(B)=Bᵀ`.
         * @tparam ROW_MAJOR_C  Output storage order (false = column-major).
         * @param alpha  Scalar multiplier on the product.
         * @param A,B    Input matrices.
         * @param C      Output result matrix (overwritten).
         */
        template <typename T, uint32_t M, uint32_t N, uint32_t K,
                  bool TRANSPOSE_A = false, bool TRANSPOSE_B = false, bool ROW_MAJOR_C = false>
        __device__ void gemm(T alpha, const T *__restrict__ A, const T *__restrict__ B, T *__restrict__ C)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            gemm_impl_ct<T, M, N, K, TRANSPOSE_A, TRANSPOSE_B, ROW_MAJOR_C>(lane, 32u, alpha, A, B, C);
        }
    }
    
    // ─── tiled GEMM (shared-memory staging, column-major, no transpose) ──────────
    /**
     * @brief Tiled GEMM with shared-memory staging: `C = alpha * A * B + beta * C`.
     *
     * Standard convention, column-major, no transpose. `C` is `m×n`, contraction
     * `k`. Stages `TILE`-wide column blocks of A (`m×TILE`) and the matching row
     * blocks of B (`TILE×n`) into the caller-provided shared scratch, accumulating
     * across tiles. Single-block; best when A/B values can be reused from shared
     * memory. NumPy: `C = alpha * A @ B + beta * C`.
     *
     * @tparam T  Scalar type.
     * @tparam TILE  Column-block width staged per pass.
     * @param m,n,k  Dimensions: A is m×k, B is k×n, C is m×n.
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices (column-major).
     * @param beta   Scalar multiplier on the existing C (read only when `beta != 0`).
     * @param C      In/out result matrix.
     * @param s_A    Shared scratch of `m * TILE` elements for the A tile.
     * @param s_B    Shared scratch of `TILE * n` elements for the B tile.
     */
    template <typename T, int TILE = 8>
    __device__ void gemm_tiled(uint32_t m, uint32_t n, uint32_t k,
                                T alpha, const T *__restrict__ A, const T *__restrict__ B,
                                T beta, T *__restrict__ C,
                                T *s_A, T *s_B)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        uint32_t mn   = m * n;
        bool valid    = (rank < mn);
        uint32_t crow = valid ? (rank % m) : 0;
        uint32_t ccol = valid ? (rank / m) : 0;
        T acc = static_cast<T>(0);
    
        for (uint32_t t = 0; t < k; t += TILE) {
            uint32_t tile_end = (t + TILE < k) ? (t + TILE) : k;
            uint32_t tile_w   = tile_end - t;
            // stage A columns [t, t+tile_w):  A is m×k col-major (LDA=m)
            for (uint32_t i = rank; i < m * tile_w; i += size) {
                uint32_t ar = i % m, ac = i / m;
                s_A[ar + ac*m] = A[ar + (t+ac)*m];
            }
            // stage B rows [t, t+tile_w):  B is k×n col-major (LDB=k)
            for (uint32_t i = rank; i < tile_w * n; i += size) {
                uint32_t br = i % tile_w, bc = i / tile_w;
                s_B[br + bc*tile_w] = B[(t+br) + bc*k];
            }
            __syncthreads();
            if (valid) {
                for (uint32_t i = 0; i < tile_w; i++)
                    acc += s_A[crow + i*m] * s_B[i + ccol*tile_w];
            }
            __syncthreads();
        }
        if (valid) C[crow + ccol*m] = beta_blend(alpha*acc, beta, C[crow + ccol*m]);
    }
    
    // ─── auto-dispatch: tiled when scratch provided and m*n <= blockDim ──────────
    /**
     * @brief Auto-dispatching GEMM: `C = alpha * A * B + beta * C` (column-major).
     *
     * Selects `gemm_tiled` when shared-memory scratch is provided and one output
     * element fits per thread (`m * n <= blockDim`); otherwise falls back to the
     * plain `gemm`. Standard convention: C is m×n, contraction k. Single-block.
     * NumPy: `C = alpha * A @ B + beta * C`.
     *
     * @tparam T  Scalar type.
     * @tparam TILE  Tile width passed through to `gemm_tiled`.
     * @param m,n,k  Dimensions: A is m×k, B is k×n, C is m×n.
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices (column-major).
     * @param beta   Scalar multiplier on the existing C (read only when `beta != 0`).
     * @param C      In/out result matrix.
     * @param s_A    Optional shared scratch for the A tile (nullptr selects the plain path).
     * @param s_B    Optional shared scratch for the B tile.
     */
    template <typename T, int TILE = 8>
    __device__ void gemm_dispatch(uint32_t m, uint32_t n, uint32_t k,
                                   T alpha, const T *__restrict__ A, const T *__restrict__ B,
                                   T beta, T *__restrict__ C,
                                   T *s_A = nullptr, T *s_B = nullptr)
    {
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        if (s_A != nullptr && m*n <= size)
            gemm_tiled<T, TILE>(m, n, k, alpha, A, B, beta, C, s_A, s_B);
        else
            gemm<T>(m, n, k, alpha, A, B, beta, C);
    }
    // END GLASS src/base/L3/gemm.cuh
    
    // BEGIN GLASS src/base/L3/gemm_strided.cuh
    
    // Compile-time-size GEMM (standard BLAS convention) with explicit column-major
    // leading dimensions for A and B.
    //   C is M×N, contraction K.
    //   A is M×K column-major with leading dim A_RS:  A[m][k] = A[m + k*A_RS].
    //   B is K×N column-major with leading dim B_RS:  B[k][n] = B[k + n*B_RS].
    //   Output C is standard column-major with LDC = M.
    // When A_RS==M and B_RS==K this is identical to glass::gemm<T,M,N,K>.
    //
    // Uses flat-element parallelism (same as gemm_impl_ct): each thread owns one
    // output element el in [rank..M*N) step size.  row=el%M and col=el/M use the
    // compiler magic-multiply since M is compile-time.  The inner K-loop is fully
    // unrolled since K, A_RS, B_RS are all compile-time constants.
    
    /**
     * @brief Strided compile-time GEMM: `C = alpha * A * B + beta * C` with custom leading dims.
     *
     * Column-major GEMM (standard convention: C is M×N, contraction K) where A and B
     * carry explicit leading dimensions (column strides): `A[m][k] = A[m + k*A_RS]`,
     * `B[k][n] = B[k + n*B_RS]`. Output C is standard column-major with LDC = M. When
     * `A_RS == M` and `B_RS == K` this is identical to `glass::gemm<T,M,N,K>`.
     * Single-block, flat-element parallelism; the inner K-loop is fully unrolled.
     * NumPy: `C = alpha * A @ B + beta * C` on the strided sub-views.
     *
     * @tparam T  Scalar type.
     * @tparam M,N,K  Compile-time dimensions: A is M×K, B is K×N, C is M×N (contraction K).
     * @tparam A_RS  Column stride (leading dimension) of A (default M).
     * @tparam B_RS  Column stride (leading dimension) of B (default K).
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices (column-major, strided).
     * @param beta   Scalar multiplier on the existing C (read only when `beta != 0`).
     * @param C      In/out result matrix (column-major, LDC = M).
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t K,
              uint32_t A_RS = M, uint32_t B_RS = K>
    __device__ void gemm_strided(T alpha, const T* A, const T* B, T beta, T* C)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        for (uint32_t el = rank; el < M * N; el += size) {
            uint32_t m = el % M, n = el / M;
            T res = static_cast<T>(0);
            for (uint32_t k = 0; k < K; k++)
                res += A[m + k * A_RS] * B[k + n * B_RS];
            C[m + n * M] = beta_blend(alpha * res, beta, C[m + n * M]);
        }
    }
    
    /**
     * @brief Strided compile-time GEMM with implicit `beta = 0`: `C = alpha * A * B`.
     *
     * Same as the beta overload but overwrites C (the existing C is not read).
     * Column-major with explicit leading dims `A_RS` / `B_RS`; LDC = M. NumPy:
     * `C = alpha * A @ B`.
     *
     * @tparam T  Scalar type.
     * @tparam M,N,K  Compile-time dimensions: A is M×K, B is K×N, C is M×N (contraction K).
     * @tparam A_RS  Column stride (leading dimension) of A (default M).
     * @tparam B_RS  Column stride (leading dimension) of B (default K).
     * @param alpha  Scalar multiplier on the product.
     * @param A,B    Input matrices (column-major, strided).
     * @param C      Output result matrix (overwritten; column-major, LDC = M).
     */
    template <typename T, uint32_t M, uint32_t N, uint32_t K,
              uint32_t A_RS = M, uint32_t B_RS = K>
    __device__ void gemm_strided(T alpha, const T* A, const T* B, T* C)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        for (uint32_t el = rank; el < M * N; el += size) {
            uint32_t m = el % M, n = el / M;
            T res = static_cast<T>(0);
            for (uint32_t k = 0; k < K; k++)
                res += A[m + k * A_RS] * B[k + n * B_RS];
            C[m + n * M] = alpha * res;
        }
    }
    // END GLASS src/base/L3/gemm_strided.cuh
    
    // BEGIN GLASS src/base/L3/gemm_batched_indexed.cuh
    
    // Indexed batched small square GEMM: for each pair p in [0, pairs),
    //   C[c_idx[p]] = A[a_idx[p]] * B[b_idx[p]]
    // where every matrix is DIM x DIM, column-major (element (i,j) at i + j*DIM),
    // and the *_idx arrays select which matrix slot in the contiguous base buffers
    // participates in pair p.  A_base / B_base / C_base are flat arrays of DIM*DIM
    // matrices; a_idx[p] is a MATRIX index, so the matrix lives at offset
    // a_idx[p]*DIM*DIM (likewise B and C).  DIM is compile-time (default 4), so the
    // inner contraction loop is fully unrolled.
    //
    // One block-stride loop over the flattened `pairs*DIM*DIM` output elements:
    // thread `rank` owns global element e, decoded as pair = e/(DIM*DIM),
    // el = e%(DIM*DIM), row = el%DIM, col = el/DIM.  This is the indexed/gather
    // analogue of gemm_strided — useful for assembling many independent 4x4
    // (e.g. SE(3) / spatial-transform) products selected by index lists, computing
    // all `pairs` concurrently in a single block.
    //
    // ── Generalizations (template flags, all default to the original behavior) ────
    // These mirror the L2 segmented-gemv TRANSPOSE / ATOMIC_Y additions and give the
    // matrix-valued backward passes (e.g. the world-frame second-order Step-5
    // propagation Xᵀ·M·X → parent, and IA-block accumulation) first-party support.
    //
    // TRANSPOSE_A (default false): pair p computes  C_p = A_pᵀ · B_p, i.e. the left
    //   factor is read transposed (A_p[k][row] instead of A_p[row][k]).  This is the
    //   Xᵀ-on-the-left direction the GRiD backward recursions propagate.  A_p is
    //   still stored DIM×DIM col-major; only the index it is read at changes.
    //
    // TRANSPOSE_B (default false): pair p reads the right factor transposed
    //   (B_p[col][k] instead of B_p[k][col]), giving C_p = A_p · B_pᵀ.  Combine with
    //   TRANSPOSE_A for C_p = A_pᵀ · B_pᵀ.  All matrices are square DIM×DIM, so the
    //   output is always DIM×DIM regardless of the transpose flags.
    //
    // ATOMIC_C (default false): the per-element result is accumulated into C via
    //   atomicAdd instead of being written.  This RELAXES the distinct-c_idx
    //   requirement: several pairs may target the SAME c_idx slot (the parent-block
    //   accumulation where many children add into one parent), and their products
    //   are atomically summed.  Each thread owns a single output element and issues
    //   exactly one atomicAdd to ITS OWN element Cp[el], so there is no intra-tile
    //   race — overlap is only ACROSS pairs sharing a c slot, which the atomic
    //   resolves.  Under ATOMIC_C the operation is the pure accumulate
    //   C[c_idx[p]] += A_p(ᵀ) · B_p(ᵀ); the caller must PRE-ZERO (or pre-load) the
    //   touched C slots, exactly as a beta term would — no beta is applied here (a
    //   read-modify-write scaled prior C would race the concurrent atomicAdds, the
    //   same rule the L2 ATOMIC_Y path documents).
    //
    // Index convention (all IDX_T, MATRIX indices not element offsets):
    //   a_idx[p] : matrix slot of the left factor   in A_base   (len `pairs`)
    //   b_idx[p] : matrix slot of the right factor  in B_base   (len `pairs`)
    //   c_idx[p] : matrix slot of the destination   in C_base   (len `pairs`)
    // Without ATOMIC_C, distinct pairs MUST target distinct c_idx slots (each output
    // written once); with ATOMIC_C they may share c_idx freely (summed atomically).
    // a_idx / b_idx may repeat or alias freely.  No alpha/beta — pure C = A*B
    // overwrite (or, under ATOMIC_C, pure += accumulate into pre-zeroed C).
    
    /**
     * @brief Indexed/gather batched square GEMM: `C[c_idx[p]] = op(A[a_idx[p]]) * op(B[b_idx[p]])`.
     *
     * For each pair `p` in `[0, pairs)` multiplies two `DIM x DIM` column-major
     * matrices selected by index into flat base buffers (`a_idx[p]` is a MATRIX
     * index, so the matrix lives at offset `a_idx[p] * DIM * DIM`), computing all
     * pairs concurrently in a single block. This is the indexed/gather analogue of
     * `gemm_strided`, useful for assembling many independent small (e.g. 4x4
     * SE(3)) products from index lists. No alpha/beta — a pure overwrite
     * (`C = op(A) * op(B)`) unless `ATOMIC_C` is set.
     *
     * Layout flags read the factors transposed in place (matrices stay square
     * `DIM x DIM`, so the output is always `DIM x DIM`):
     * `TRANSPOSE_A` gives `A_p^T * B_p`, `TRANSPOSE_B` gives `A_p * B_p^T`, and both
     * give `A_p^T * B_p^T`. Without `ATOMIC_C`, distinct pairs MUST target distinct
     * `c_idx` slots (each output written once); `a_idx` / `b_idx` may alias freely.
     *
     * @tparam T  Scalar type.
     * @tparam DIM  Compile-time matrix dimension (square; inner loop fully unrolled).
     * @tparam TRANSPOSE_A  If true, the left factor is read transposed (`C_p = A_p^T * ...`).
     * @tparam TRANSPOSE_B  If true, the right factor is read transposed (`... * B_p^T`).
     * @tparam ATOMIC_C  If true, accumulate via atomicAdd (`C[c_idx[p]] += ...`), allowing
     *                   several pairs to share a `c_idx` slot; the caller must PRE-ZERO
     *                   (or pre-load) the touched C slots, and no beta is applied.
     * @tparam IDX_T  Index type of the *_idx arrays.
     * @param pairs   Number of independent GEMMs.
     * @param a_idx   Per-pair matrix slot of the left factor in `A_base` (length `pairs`).
     * @param b_idx   Per-pair matrix slot of the right factor in `B_base` (length `pairs`).
     * @param c_idx   Per-pair matrix slot of the destination in `C_base` (length `pairs`).
     * @param A_base  Flat array of `DIM x DIM` left-factor matrices.
     * @param B_base  Flat array of `DIM x DIM` right-factor matrices.
     * @param C_base  Flat array of `DIM x DIM` destination matrices (written, or accumulated if ATOMIC_C).
     */
    template <typename T, uint32_t DIM = 4, bool TRANSPOSE_A = false,
              bool TRANSPOSE_B = false, bool ATOMIC_C = false, typename IDX_T = int>
    __device__ void gemm_batched_indexed(
        uint32_t pairs, const IDX_T* a_idx, const IDX_T* b_idx, const IDX_T* c_idx,
        const T* A_base, const T* B_base, T* C_base)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        constexpr uint32_t MAT = DIM * DIM;
        uint32_t total = pairs * MAT;
        for (uint32_t e = rank; e < total; e += size) {
            uint32_t pair = e / MAT;
            uint32_t el   = e % MAT;
            uint32_t row  = el % DIM;
            uint32_t col  = el / DIM;
            const T* Ap = A_base + static_cast<uint32_t>(a_idx[pair]) * MAT;
            const T* Bp = B_base + static_cast<uint32_t>(b_idx[pair]) * MAT;
            T* Cp       = C_base + static_cast<uint32_t>(c_idx[pair]) * MAT;
            T res = static_cast<T>(0);
            #pragma unroll
            for (uint32_t ind = 0; ind < DIM; ind++) {
                // A_pᵀ reads A_p[ind][row] = Ap[ind + row*DIM]; else A_p[row][ind].
                T a = TRANSPOSE_A ? Ap[ind + row * DIM] : Ap[row + ind * DIM];
                // B_pᵀ reads B_p[col][ind] = Bp[col + ind*DIM]; else B_p[ind][col].
                T b = TRANSPOSE_B ? Bp[col + ind * DIM] : Bp[ind + col * DIM];
                res += a * b;
            }
            if (ATOMIC_C) atomicAdd(&Cp[el], res);
            else          Cp[el] = res;
        }
    }
    // END GLASS src/base/L3/gemm_batched_indexed.cuh
    
    // BEGIN GLASS src/base/L3/inv.cuh
    
    /**
     * @brief In-place matrix inverse via Gauss-Jordan on an augmented `[A | I]` layout.
     *
     * Reduces a column-major augmented `dimA x (2*dimA)` matrix `[A | I]` so that on
     * return columns `dimA..2*dimA-1` hold `A^-1`. Single-block; the pivot loop is
     * serial (pivot-to-pivot dependency) while each pivot's cell updates are
     * parallelized across the block. NumPy equivalent: `Ainv = np.linalg.inv(A)`.
     *
     * @tparam T  Scalar type.
     * @param dimA    Matrix dimension (A is dimA x dimA).
     * @param A       In/out augmented `[A | I]` buffer (column-major, dimA x 2*dimA);
     *                on return its right half holds `A^-1`.
     * @param s_scratch  Shared scratch of `(2*dimA + 1) * sizeof(T)` bytes.
     */
    // Gauss-Jordan inversion of an augmented dimA×(2*dimA) matrix in-place.
    // Expected layout: column-major [A | I]; on return columns dimA..2*dimA-1 hold A^-1.
    // s_scratch: (2*dimA+1)*sizeof(T) bytes.
    // Shared body: Gauss-Jordan inversion; barrier policy supplies rank/size + the
    // two per-pivot syncs, shared by the glass:: and cgrps:: surfaces.
    // SizeT is deduced: uint32_t from the runtime overload, ct_size<N> from the
    // compile-time overload (constant-folds the trip counts and the %/ indexing).
    template <typename Bar, typename T, typename SizeT>
    __device__ void inv_impl(Bar bar, SizeT dimA, T *A, T *s_scratch)
    {
        uint32_t rank = bar.rank(), size = bar.size();
        for (unsigned pivRC = 0; pivRC < dimA; pivRC++) {
            unsigned pivOff = pivRC * dimA;
            T pvInv = static_cast<T>(1) / A[pivRC + pivOff];
            for (unsigned ind = rank; ind < 2*dimA+1; ind += size) {
                unsigned AInd = (ind < dimA) ? (ind + pivOff) : (pivRC + pivOff + (ind-dimA)*dimA);
                s_scratch[ind] = A[AInd];
            }
            bar.sync();
            for (unsigned ind = rank; ind < dimA*(dimA+1); ind += size) {
                unsigned row = ind % dimA, col = ind / dimA, coff = ind - row;
                if (row == pivRC) A[row + pivOff + coff] *= pvInv;
                else A[row + pivOff + coff] -= s_scratch[row]*pvInv*s_scratch[dimA+col];
            }
            bar.sync();
        }
    }
    
    template <typename T>
    __device__ void inv(uint32_t dimA, T *A, T *s_scratch)
    {
        inv_impl<BlockBarrier, T>(BlockBarrier{}, dimA, A, s_scratch);
    }
    
    /**
     * @brief Compile-time-size in-place matrix inverse (augmented `[A | I]` Gauss-Jordan).
     *
     * Same as the runtime `inv` but with the dimension as a template
     * parameter. NumPy equivalent: `Ainv = np.linalg.inv(A)`.
     *
     * @tparam T  Scalar type.
     * @tparam N  Matrix dimension (A is N x N).
     * @param A       In/out augmented `[A | I]` buffer (column-major, N x 2*N);
     *                on return its right half holds `A^-1`.
     * @param s_scratch  Shared scratch of `(2*N + 1) * sizeof(T)` bytes.
     */
    template <typename T, uint32_t N>
    __device__ void inv(T *A, T *s_scratch)
    {
        inv_impl<BlockBarrier, T>(BlockBarrier{}, ct_size<N>{}, A, s_scratch);
    }
    
    /**
     * @brief Scratch size in bytes for `inv` (augmented `[A | I]`).
     *
     * The unpivoted Gauss-Jordan path saves the active pivot column + row window plus
     * one slot: `2*dimA + 1` elements of `T`. Allocate
     * `inv_scratch_bytes<T>(dimA)` for the `s_scratch` argument.
     *
     * @tparam T  Scalar type.
     * @param dimA  Matrix dimension (A is dimA x dimA).
     * @return Bytes to allocate for `inv`'s `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t inv_scratch_bytes(uint32_t dimA)
    {
        return static_cast<std::size_t>(2 * dimA + 1) * sizeof(T);
    }
    
    /**
     * @brief Scratch size in bytes for `inv_pivoted`.
     *
     * Row pivoting permutes the already-built inverse columns, so (unlike the
     * unpivoted path) the elimination cannot use the reduced active-column window —
     * it must save and update the **full** `2*dimA`-wide pivot row. Layout:
     * `dimA` slots for the pivot column, `2*dimA` for the full pivot row, and **one**
     * trailing slot to broadcast the chosen pivot-row index from the argmax.
     *
     * Total = `3*dimA + 1` elements of `T`.
     *
     * @tparam T  Scalar type.
     * @param dimA  Matrix dimension (A is dimA x dimA).
     * @return Bytes to allocate for `inv_pivoted`'s `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t inv_pivoted_scratch_bytes(uint32_t dimA)
    {
        return static_cast<std::size_t>(3 * dimA + 1) * sizeof(T);
    }
    
    /**
     * @brief In-place ROBUST (partial-pivoting) matrix inverse, augmented `[A | I]`.
     *
     * Partial-pivoting (row-pivoted) Gauss-Jordan sibling of `inv`. Same
     * augmented column-major `dimA x (2*dimA)` `[A | I]` input/output contract: on
     * return columns `dimA..2*dimA-1` hold `A^-1`. NumPy equivalent:
     * `Ainv = np.linalg.inv(A)`.
     *
     * @par Why pivoted
     * The plain `inv` divides by `A[pivRC + pivRC*dimA]` as-is, so it loses
     * accuracy (or fails outright) when a leading pivot is small/zero even though `A`
     * is invertible — e.g. a tiny `A[0,0]` beneath a large later row, or a row
     * permutation that parks a zero on the diagonal. At each step `k` this variant
     * instead selects the row `r >= k` with the largest `|A[r + k*dimA]|`, swaps rows
     * `k` and `r` across the FULL augmented width `[A | I]` (all `2*dimA` columns),
     * then does the identical divide/eliminate. Because both halves are permuted
     * together, the row permutation is absorbed into the result and the returned
     * right half is `A^-1` directly — **no separate `piv` output is needed**.
     *
     * @par Parallelism / barriers
     * Single-block, strided (`ind += size`), thread-count invariant. Per pivot step:
     *   1. save the pivot column + pivot row + augmented column into `s_scratch`;
     *   2. block-wide argmax over the pivot-column tail `[k, dimA)` (deterministic
     *      lower-index tie-break, matching `glass::iamax`) chooses the pivot row `r`,
     *      broadcast to all threads through a shared slot + `__syncthreads()` (never
     *      a racy re-read);
     *   3. if `r != k`, swap rows `k` and `r` across all `2*dimA` columns (parallel);
     *   4. re-save the (now swapped) pivot row/column, then divide/eliminate exactly
     *      as the unpivoted path.
     * Each phase is separated by a barrier so the argmax result and the swapped data
     * are block-visible before they are consumed.
     *
     * @par Scratch
     * `s_scratch` must hold `inv_pivoted_scratch_bytes<T>(dimA)` = `3*dimA + 1`
     * elements of `T`: `dimA` for the pivot column, `2*dimA` for the full pivot row,
     * and one trailing slot to broadcast the chosen pivot-row index.
     *
     * @tparam T  Scalar type.
     * @param dimA    Matrix dimension (A is dimA x dimA).
     * @param A       In/out augmented `[A | I]` buffer (column-major, dimA x 2*dimA);
     *                on return its right half holds `A^-1`.
     * @param s_scratch  Shared scratch of `(3*dimA + 1) * sizeof(T)` bytes.
     */
    // Shared body (runtime + compile-time overloads): SizeT deduced — uint32_t or
    // ct_size<N> (constant-folds the trip counts and the %/ indexing).
    template <typename T, typename SizeT>
    __device__ void inv_pivoted_impl(SizeT dimA, T *A, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        const unsigned W = 2*dimA;          // augmented width
        // s_scratch layout (3*dimA + 1 slots):
        //   [0 .. dimA)       pivot column
        //   [dimA .. 3*dimA)  full pivot row (all 2*dimA augmented columns)
        //   [3*dimA]          broadcast slot for the chosen pivot-row index
        T *s_pcol = s_scratch;
        T *s_prow = &s_scratch[dimA];
        T *s_piv  = &s_scratch[3*dimA];
        for (unsigned pivRC = 0; pivRC < dimA; pivRC++) {
            unsigned pivOff = pivRC * dimA;
    
            // ── Partial pivot: argmax over |A[r + pivOff]| for r in [pivRC, dimA). ──
            // Thread 0 scans the (short) pivot-column tail with a deterministic
            // lower-index tie-break (matching glass::iamax) and broadcasts the chosen
            // row through s_piv; the broadcast + __syncthreads makes it race-free.
            if (rank == 0) {
                T key = static_cast<T>(0);
                uint32_t idx = UINT32_MAX;
                for (unsigned r = pivRC; r < dimA; r++) {
                    T v = A[r + pivOff];
                    v = (v < static_cast<T>(0)) ? -v : v;
                    if (v > key || (v == key && r < idx)) { key = v; idx = r; }
                }
                // All-zero column (singular) → keep the diagonal row (idx==MAX → pivRC).
                s_piv[0] = static_cast<T>((idx == UINT32_MAX) ? pivRC : idx);
            }
            __syncthreads();
            unsigned pivRow = static_cast<unsigned>(s_piv[0]);
    
            // ── Swap rows pivRC and pivRow across the full augmented width [A|I]. ──
            if (pivRow != pivRC) {
                for (unsigned col = rank; col < W; col += size) {
                    unsigned coff = col * dimA;
                    T tmp = A[pivRC + coff];
                    A[pivRC + coff] = A[pivRow + coff];
                    A[pivRow + coff] = tmp;
                }
                __syncthreads();
            }
    
            // ── Save the pivot column and the FULL pivot row, then divide/eliminate
            //    over all 2*dimA columns (row pivoting forbids the reduced window). ──
            for (unsigned r = rank; r < dimA; r += size) s_pcol[r] = A[r + pivOff];
            for (unsigned c = rank; c < W;    c += size) s_prow[c] = A[pivRC + c*dimA];
            __syncthreads();
            T pvInv = static_cast<T>(1) / s_prow[pivRC];
            for (unsigned ind = rank; ind < dimA*W; ind += size) {
                unsigned row = ind % dimA, col = ind / dimA;
                if (row == pivRC) A[row + col*dimA]  = s_prow[col] * pvInv;
                else              A[row + col*dimA] -= s_pcol[row] * pvInv * s_prow[col];
            }
            __syncthreads();
        }
    }
    
    template <typename T>
    __device__ void inv_pivoted(uint32_t dimA, T *A, T *s_scratch)
    {
        inv_pivoted_impl<T>(dimA, A, s_scratch);
    }
    
    /**
     * @brief Compile-time-size ROBUST (partial-pivoting) matrix inverse (`[A | I]`).
     *
     * Same as the runtime `inv_pivoted` but with the dimension as a template
     * parameter; partial-pivoting Gauss-Jordan, tolerant of small leading pivots that
     * the plain `inv` mishandles. NumPy equivalent: `Ainv = np.linalg.inv(A)`.
     *
     * @tparam T  Scalar type.
     * @tparam N  Matrix dimension (A is N x N).
     * @param A       In/out augmented `[A | I]` buffer (column-major, N x 2*N);
     *                on return its right half holds `A^-1`.
     * @param s_scratch  Shared scratch of `(3*N + 1) * sizeof(T)` bytes
     *                (= `inv_pivoted_scratch_bytes<T>(N)`).
     */
    template <typename T, uint32_t N>
    __device__ void inv_pivoted(T *A, T *s_scratch)
    {
        inv_pivoted_impl<T>(ct_size<N>{}, A, s_scratch);
    }
    
    /**
     * @brief Scratch size in bytes for the K-way fused `inv` (`Σ_m (2*dims[m]+1)` elements).
     *
     * @tparam T  Scalar type.
     * @param K     Number of matrices.
     * @param dims  Per-matrix dimensions.
     * @return Bytes to allocate for the fused `inv`'s `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t inv_fused_scratch_bytes(uint32_t K, const uint32_t *dims)
    {
        std::size_t elems = 0;
        for (uint32_t m = 0; m < K; m++) { elems += 2u*dims[m] + 1u; }
        return elems * sizeof(T);
    }
    
    /**
     * @brief Fused in-place inverse of K independent matrices (augmented `[V | I]`).
     *
     * Inverts `K` matrices simultaneously in one block by interleaving their
     * Gauss-Jordan sweeps over a single shared `MAX_DIM = max(dims)` pivot loop:
     * matrix `m` participates while `pivRC < dims[m]` and sits idle thereafter.
     * Every matrix keeps the same augmented `[V | I]` convention as the
     * single-matrix `inv` — buffer `mats[m]` is column-major
     * `dims[m] x (2*dims[m])` and on return its right half holds `inv(mats[m])`.
     * Fewer barriers than K separate calls (one save→update barrier pair per pivot
     * step, shared by all K matrices). Used by GATO's Schur kernel
     * (Q_k, Q_kp1, R_k → K=3).
     *
     * Scratch layout: matrix `m` owns the contiguous span
     * `[Σ_{j<m}(2*dims[j]+1), Σ_{j<=m}(2*dims[j]+1))` of `s_scratch` (each matrix needs
     * `2*dims[m]+1` slots: `dims[m]` for its pivot column, `dims[m]+1` for its pivot
     * row plus the augmented column). The per-matrix base offset is the prefix sum
     * `Σ_{j<m}(2*dims[j]+1)`, recomputed locally per thread by scanning `dims[]`
     * (no shared write, so race-free). Total scratch = `Σ_m (2*dims[m]+1)` elements.
     *
     * NumPy equivalent (per matrix `m`): `inv(m) = np.linalg.inv(mats[m])`.
     *
     * @tparam T  Scalar type.
     * @param K        Number of matrices.
     * @param dims     Per-matrix dimensions (`dims[m]` for matrix `m`).
     * @param MAX_DIM  `max(dims[0..K-1])` — the shared pivot-loop length (precondition).
     * @param mats     Array of K in/out augmented `[V | I]` buffers (column-major,
     *                 `dims[m] x 2*dims[m]`); on return each right half holds its inverse.
     * @param s_scratch   Shared scratch of `inv_fused_scratch_bytes<T>(K, dims)` bytes
     *                    (= `(Σ_m (2*dims[m]+1)) * sizeof(T)`).
     */
    template <typename T>
    __device__ void inv(uint32_t K, const uint32_t *dims, uint32_t MAX_DIM, T **mats, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        for (unsigned pivRC = 0; pivRC < MAX_DIM; pivRC++) {
            // Phase 1: save each active matrix's pivot row + column into its scratch span.
            // Strided over the union of work; per-matrix scratch base = prefix sum of (2*dim+1).
            uint32_t sOff = 0;
            for (unsigned m = 0; m < K; m++) {
                uint32_t dim = dims[m];
                if (pivRC < dim) {
                    T *M = mats[m];
                    T *s_mem = &s_scratch[sOff];
                    unsigned pivOff = pivRC * dim;
                    // pivot column (dim entries) + pivot row & augmented column (dim+1 entries)
                    for (unsigned ind = rank; ind < dim; ind += size)
                        s_mem[ind] = M[ind + pivOff];
                    for (unsigned ind = rank; ind < dim + 1; ind += size)
                        s_mem[ind + dim] = M[ind*dim + pivRC + pivOff];
                }
                sOff += 2*dim + 1;
            }
            __syncthreads();
            // Phase 2: Gauss-Jordan cell update for each active matrix.
            sOff = 0;
            for (unsigned m = 0; m < K; m++) {
                uint32_t dim = dims[m];
                if (pivRC < dim) {
                    T *M = mats[m];
                    T *s_mem = &s_scratch[sOff];
                    unsigned pivOff = pivRC * dim;
                    for (unsigned ind = rank; ind < dim*(dim + 1); ind += size) {
                        unsigned row = ind % dim, col = ind / dim;
                        if (row == pivRC) M[pivOff + ind] /= s_mem[pivRC];
                        else M[pivOff + ind] -= s_mem[row] / s_mem[pivRC] * s_mem[dim + col];
                    }
                }
                sOff += 2*dim + 1;
            }
            __syncthreads();
        }
    }
    
    /**
     * @brief Fused in-place inverse of TWO independent matrices (augmented `[V | I]`).
     *
     * Thin wrapper over the K-way `inv` (K=2). Inverts `A` (dimA x dimA) and
     * `B` (dimB x dimB) simultaneously in one block; same augmented `[V | I]`
     * convention and output as the single-matrix `inv`.
     * NumPy: `Ainv, Binv = inv(A), inv(B)`.
     *
     * @tparam T  Scalar type.
     * @param dimA,dimB  Matrix dimensions.
     * @param MAX_DIM    `max(dimA, dimB)` — the shared pivot-loop length.
     * @param A,B        In/out augmented `[V | I]` buffers (column-major, dim x 2*dim).
     * @param s_scratch     Shared scratch of `(2*dimA + 2*dimB + 2) * sizeof(T)` bytes.
     */
    template <typename T>
    __device__ void inv(uint32_t dimA, uint32_t dimB, uint32_t MAX_DIM, T *A, T *B, T *s_scratch)
    {
        uint32_t dims[2] = {dimA, dimB};
        T *mats[2] = {A, B};
        inv<T>(2, dims, MAX_DIM, mats, s_scratch);
    }
    
    /**
     * @brief Fused in-place inverse of THREE independent matrices (augmented `[V | I]`).
     *
     * Thin wrapper over the K-way `inv` (K=3). Inverts `A`,`B`,`C`
     * simultaneously in one block; same augmented `[V | I]` convention and output as
     * the single-matrix `inv`. Used by GATO's Schur kernel (Q_k, Q_kp1, R_k).
     * NumPy: invert each independently.
     *
     * @tparam T  Scalar type.
     * @param dimA,dimB,dimC  Matrix dimensions.
     * @param MAX_DIM         `max(dimA, dimB, dimC)` — the shared pivot-loop length.
     * @param A,B,C           In/out augmented `[V | I]` buffers (column-major, dim x 2*dim).
     * @param s_scratch          Shared scratch of `(2*dimA + 2*dimB + 2*dimC + 3) * sizeof(T)` bytes.
     */
    template <typename T>
    __device__ void inv(uint32_t dimA, uint32_t dimB, uint32_t dimC, uint32_t MAX_DIM, T *A, T *B, T *C, T *s_scratch)
    {
        uint32_t dims[3] = {dimA, dimB, dimC};
        T *mats[3] = {A, B, C};
        inv<T>(3, dims, MAX_DIM, mats, s_scratch);
    }
    
    
    /**
     * @brief Scratch size in bytes for `inv_dense`.
     *
     * The dual-buffer dense path saves one `3*dimA`-element pivot working set. Allocate
     * `inv_dense_scratch_bytes<T>(dimA)` for the `s_scratch` argument.
     *
     * @tparam T  Scalar type.
     * @param dimA  Matrix dimension (A is dimA x dimA).
     * @return Bytes to allocate for `inv_dense`'s `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t inv_dense_scratch_bytes(uint32_t dimA)
    {
        return static_cast<std::size_t>(3 * dimA) * sizeof(T);
    }
    
    // Block-cooperative Gauss-Jordan inversion of a dimA×dimA matrix.
    //   A:    in/out, column-major dimA×dimA.  On return: A := A^{-1}.
    //   Ainv: workspace, column-major dimA×dimA (overwritten).  On return: A^{-1}.
    //          (Some callers want A unchanged + a separate inverse — they get both.)
    //   s_scratch: shared scratch of size (3*dimA)*sizeof(T).
    // Pivot loop is serial (pivot-to-pivot data dependency); within each pivot, the
    // dimA save and the dimA*dimA cell update are parallelized across the block.
    //
    // Algorithm: same dual-update (A, Ainv) Gauss-Jordan as a classic [A | I] →
    // [I | A^{-1}] reduction but without materializing the augmented layout. A and
    // Ainv are tracked in separate buffers so callers that need A^{-1} alongside
    // the original A get it without extra copies.
    
    /**
     * @brief Dense (no augmented buffer) in-place matrix inverse via dual-update Gauss-Jordan.
     *
     * Inverts a column-major `dimA x dimA` matrix without materializing the `[A | I]`
     * augmented layout: tracks A and a separate inverse buffer through the same
     * `[A | I] -> [I | A^{-1}]` reduction. On return BOTH `A` and `Ainv` hold
     * `A^{-1}` (callers that want the original A preserved should copy it first).
     * Single-block: serial pivot loop, block-parallel per-pivot updates. NumPy
     * equivalent: `Ainv = np.linalg.inv(A)`.
     *
     * @tparam T  Scalar type.
     * @param dimA    Matrix dimension (A is dimA x dimA).
     * @param A       In/out column-major dimA x dimA matrix; on return holds `A^{-1}`.
     * @param Ainv    Workspace column-major dimA x dimA; on return also holds `A^{-1}`.
     * @param s_scratch  Shared scratch of `3 * dimA * sizeof(T)` bytes.
     */
    // Shared body (runtime + compile-time overloads): SizeT deduced — uint32_t or
    // ct_size<N> (constant-folds the trip counts and the %/ indexing).
    template <typename T, typename SizeT>
    __device__ void inv_dense_impl(SizeT dimA, T *A, T *Ainv, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        // Seed Ainv = I (parallel over dimA*dimA cells).
        for (uint32_t ind = rank; ind < dimA*dimA; ind += size) {
            uint32_t row = ind % dimA, col = ind / dimA;
            Ainv[ind] = (row == col) ? static_cast<T>(1) : static_cast<T>(0);
        }
        __syncthreads();
        for (unsigned pivRC = 0; pivRC < dimA; pivRC++) {
            unsigned pivColOffset = pivRC * dimA;
            // Block-cooperative save: pivot row of A, pivot row of Ainv, pivot column of A.
            // 3*dimA entries → block-strided thread distribution.
            for (uint32_t ind = rank; ind < dimA; ind += size) {
                s_scratch[ind]            = A[pivRC + dimA * ind];          // pivot row of A
                s_scratch[ind + dimA]     = Ainv[pivRC + dimA * ind];        // pivot row of Ainv
                s_scratch[ind + dimA * 2] = A[ind + pivColOffset];           // pivot column of A
            }
            __syncthreads();
            T pvInv = static_cast<T>(1) / s_scratch[pivRC];
            // Block-cooperative Gauss-Jordan update across dimA*dimA cells.
            // Each thread owns a unique (row, col) so writes are race-free.
            for (uint32_t ind = rank; ind < dimA * dimA; ind += size) {
                uint32_t row = ind % dimA, col = ind / dimA;
                if (row == pivRC) {
                    A[row + dimA * col]    = s_scratch[col] * pvInv;
                    Ainv[row + dimA * col] = s_scratch[col + dimA] * pvInv;
                } else {
                    T multiplier = s_scratch[row + dimA * 2] * pvInv;
                    A[row + dimA * col]    -= multiplier * s_scratch[col];
                    Ainv[row + dimA * col] -= multiplier * s_scratch[col + dimA];
                }
            }
            __syncthreads();
        }
    }
    
    template <typename T>
    __device__ void inv_dense(uint32_t dimA, T *A, T *Ainv, T *s_scratch)
    {
        inv_dense_impl<T>(dimA, A, Ainv, s_scratch);
    }
    
    /**
     * @brief Compile-time-size dense in-place matrix inverse (dual-update Gauss-Jordan).
     *
     * Same as the runtime `inv_dense` but with the dimension as a template
     * parameter; on return both `A` and `Ainv` hold `A^{-1}`. NumPy equivalent:
     * `Ainv = np.linalg.inv(A)`.
     *
     * @tparam T  Scalar type.
     * @tparam N  Matrix dimension (A is N x N).
     * @param A       In/out column-major N x N matrix; on return holds `A^{-1}`.
     * @param Ainv    Workspace column-major N x N; on return also holds `A^{-1}`.
     * @param s_scratch  Shared scratch of `3 * N * sizeof(T)` bytes.
     */
    template <typename T, uint32_t N>
    __device__ void inv_dense(T *A, T *Ainv, T *s_scratch)
    {
        inv_dense_impl<T>(ct_size<N>{}, A, Ainv, s_scratch);
    }
    
    namespace warp {
        /**
         * @brief Single-warp in-place matrix inverse (unpivoted Gauss-Jordan, augmented `[A | I]`), compile-time size.
         *
         * One 32-lane warp reduces a column-major augmented `N x 2*N` `[A | I]`
         * buffer so that on return columns `N..2*N-1` hold `A^-1` — the same
         * layout, phases, and arithmetic as the block `glass::inv`, scoped to a
         * warp for warp-per-problem kernels (e.g. packing many small Schur-block
         * inversions from GATO/MPCGPU into one block, one warp each). Per pivot:
         * a lane-strided SAVE of the pivot column + active pivot-row window into
         * `s_scratch`, `__syncwarp()`, then a lane-strided Gauss-Jordan cell
         * UPDATE over the `N x (N+1)` active window, `__syncwarp()` — mirroring
         * `inv_impl`'s two-phase structure exactly. The pivot reciprocal is
         * computed redundantly by every lane from the SAVED shared value
         * (`1 / s_scratch[pivRC]`, the same bits every lane) — deterministic, and
         * never a lane-0-register broadcast, so there is nothing for the
         * `__restrict__` stale-shared-reread miscompile (guide §1g) to bite.
         * No `__syncthreads`. Unpivoted: like the block `inv`, it divides by the
         * leading pivots as-is (no row exchange) — use the block `inv_pivoted`
         * when robustness to small/zero leading pivots is needed. Fused K-way and
         * pivoted warp forms are deliberately not provided (future work).
         *
         * NumPy equivalent: `Ainv = np.linalg.inv(A)`.
         *
         * @tparam T  Scalar type.
         * @tparam N  Matrix dimension (A is N x N).
         * @param A          In/out augmented `[A | I]` buffer (column-major, N x 2*N);
         *                   on return its right half holds `A^-1`.
         * @param s_scratch  Scratch of `2*N + 1` elements of `T`
         *                   (= `inv_scratch_bytes<T>(N)` bytes), shared or global.
         *                   Each warp needs its OWN `2*N + 1` span — when packing W
         *                   warps into a block, give warp `w` `s_scratch + w*(2*N+1)`.
         */
        template <typename T, uint32_t N>
        __device__ void inv(T *A, T *s_scratch)
        {
            uint32_t lane = (threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y) & 31;
            for (unsigned pivRC = 0; pivRC < N; pivRC++) {
                unsigned pivOff = pivRC * N;
                // SAVE: pivot column (N entries) + active pivot-row window (N+1 entries).
                for (unsigned ind = lane; ind < 2*N+1; ind += 32) {
                    unsigned AInd = (ind < N) ? (ind + pivOff) : (pivRC + pivOff + (ind-N)*N);
                    s_scratch[ind] = A[AInd];
                }
                __syncwarp();
                // UPDATE: every lane recomputes the pivot reciprocal from the saved
                // pivot value — same bits on all lanes (s_scratch[pivRC] == the
                // pre-save A[pivRC + pivOff] the block impl reads), so the result
                // is deterministic and matches the block path bit-for-bit.
                T pvInv = static_cast<T>(1) / s_scratch[pivRC];
                for (unsigned ind = lane; ind < N*(N+1); ind += 32) {
                    unsigned row = ind % N, col = ind / N, coff = ind - row;
                    if (row == pivRC) A[row + pivOff + coff] *= pvInv;
                    else A[row + pivOff + coff] -= s_scratch[row]*pvInv*s_scratch[N+col];
                }
                __syncwarp();
            }
        }
    }
    // END GLASS src/base/L3/inv.cuh
    
    // BEGIN GLASS src/base/L3/syev.cuh
    
    /**
     * @file syev.cuh
     * @brief Symmetric eigendecomposition via cyclic Jacobi (`syev`) and the
     *        eigenvalue-clamping consumer op (`eig_clamp`).
     *
     * Device-side small symmetric eigensolver (target sizes n ≤ 32 — robot
     * state/control dimensions). Kills the host round-trip solvers like PDDP
     * currently make to `Eigen::SelfAdjointEigenSolver` mid-solve just to clamp
     * Hessian eigenvalues: `eig_clamp` does decompose → clamp → reconstruct
     * entirely inside the block.
     *
     * Algorithm (classical cyclic Jacobi): work on a copy `B = A` in scratch and
     * accumulate `V = I`. For each pair `(p, q)`, `p < q`, in a FIXED cyclic order,
     * compute the Jacobi rotation `(c, s)` annihilating `B[p,q]` (standard stable
     * formulas: `theta = (B_qq - B_pp)/(2 B_pq)`,
     * `t = sign(theta)/(|theta| + sqrt(1 + theta^2))`, `c = 1/sqrt(1 + t^2)`,
     * `s = t*c`) and apply it to rows/cols `p, q` of `B` and columns `p, q` of `V`.
     * Sweeps repeat until `off(B)_F <= eps_T * ||A||_F` (checked once per sweep) or
     * a fixed cap of 15 sweeps; typical convergence is 5–8 sweeps for n ≤ 32.
     * Jacobi always converges for (finite) symmetric input, so there is no
     * CHECK-style failure flag; **NaN/Inf input propagates** into `W`/`V`
     * (garbage-in, NaN-out — the deterministic sort still terminates).
     *
     * Thread-count invariance (bit-identical at any block size): the `(p, q)` pair
     * loop is SERIAL in a fixed order; rank 0 computes `(c, s)` into shared slots
     * followed by a barrier (one FMA chain, identical for every launch); the
     * row/col rotation is thread-strided over the n affected indices, where index
     * `k` owns exactly the entries `{(k,p),(k,q),(p,k),(q,k)}` of `B` (mirror
     * writes keep `B` exactly symmetric) and row `k` of `V` — its new values read
     * only slots owned by the same `k` (the pivot 2x2 block is owned by `k == p`),
     * so the rotation phase has no cross-thread read-after-write hazard and needs
     * no staging. The sweep-end `off(B)` probe and the final ascending selection
     * sort run serially on rank 0 (deterministic), each published through a shared
     * slot + barrier; the sorted copy-out permutes `V`'s columns in parallel
     * through the no-longer-needed `B` scratch.
     */
    
    /**
     * @brief Machine epsilon by scalar width (float / double).
     *
     * Used to scale `syev`'s deterministic convergence / rotation-skip thresholds.
     * Spelled locally (sizeof-keyed constants) so no `<limits>` lands inside
     * `namespace glass` (this header is included inside the namespace).
     *
     * @tparam T  Scalar type (4-byte -> FLT_EPSILON, 8-byte -> DBL_EPSILON).
     * @return Machine epsilon of `T`.
     */
    template <typename T>
    __host__ __device__ constexpr T syev_eps()
    {
        return static_cast<T>(sizeof(T) >= 8 ? 2.220446049250313e-16
                                             : 1.1920928955078125e-7);
    }
    
    /**
     * @brief Scratch size in bytes for `syev`.
     *
     * Exact layout (in `T` elements): `n*n` for the working copy `B` (reused at the
     * end as the eigenvector permutation staging buffer) + `n` slots holding the
     * ascending sort permutation (stored as `uint32_t`, one per `T` slot) + 4
     * control slots (`c`, `s`, the sweep-converged flag, one pad).
     *
     * @tparam T  Scalar type.
     * @param n  Matrix dimension (A is n x n).
     * @return Bytes to allocate for `syev`'s `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t syev_scratch_bytes(uint32_t n)
    {
        return static_cast<std::size_t>(n*n + n + 4) * sizeof(T);
    }
    
    /**
     * @brief Symmetric eigendecomposition `A = V diag(W) Vᵀ` (cyclic Jacobi;
     *        LAPACK `syev` analogue).
     *
     * Computes all eigenvalues and eigenvectors of the symmetric `n x n`
     * column-major matrix `A`. **`A` is preserved** (read-only — the iteration
     * works on a copy in `s_scratch`). On return `W[0..n-1]` holds the eigenvalues
     * in ASCENDING order and column `i` of the column-major `V` holds the unit
     * eigenvector matching `W[i]` (eigenvector signs are arbitrary, as with any
     * eigensolver). NumPy equivalent: `W, V = np.linalg.eigh(A)`.
     *
     * Single-block, thread-count invariant (bit-identical output at any block
     * size), deterministic: fixed cyclic pair order, rank-0 rotation coefficients
     * broadcast via shared memory + barrier, per-sweep `off(B) <= eps*||A||_F`
     * early exit decided by rank 0 into a shared flag, capped at 15 sweeps
     * (typical: 5–8 for n ≤ 32). Rotations with `|B[p,q]|` below a deterministic
     * tiny threshold (`eps*||A||_F / n²`) are skipped. Always converges for finite
     * symmetric input (no failure flag); NaN/Inf input propagates into the outputs.
     *
     * @tparam T  Scalar type (`float` / `double`; use `double` when eigenvalue
     *            clusters must be resolved tightly).
     * @param n          Matrix dimension (A is n x n; designed for n <= 32).
     * @param A          In: n x n symmetric matrix (column-major). NOT modified.
     * @param W          Out: n eigenvalues, ascending.
     * @param V          Out: n x n eigenvectors (column-major; column i ↔ W[i]).
     * @param s_scratch  Shared scratch of `syev_scratch_bytes<T>(n)` bytes.
     */
    // Shared body (runtime + compile-time overloads): SizeT deduced — uint32_t or
    // ct_size<N> (constant-folds the trip counts / indexing).
    template <typename T, typename SizeT>
    __device__ void syev_impl(SizeT n, const T *A, T *W, T *V, T *s_scratch)
    {
        static_assert(sizeof(uint32_t) <= sizeof(T),
                      "syev: the permutation slots assume sizeof(T) >= 4");
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        // Scratch layout — see syev_scratch_bytes: [0, n*n) working copy B (reused
        // as the V-permutation staging buffer at the end); [n*n, n*n + n) the sort
        // permutation (as uint32_t); then 4 control slots: [0]=c, [1]=s,
        // [2]=sweep-converged flag, [3]=pad.
        T *s_B = s_scratch;
        uint32_t *s_perm = reinterpret_cast<uint32_t *>(s_scratch + n*n);
        T *s_ctrl = s_scratch + n*n + n;
    
        // B := A (A stays read-only), V := I. One barrier before the sweeps.
        for (uint32_t idx = rank; idx < n*n; idx += size) {
            s_B[idx] = A[idx];
            uint32_t r = idx % n, c = idx / n;
            V[idx] = (r == c) ? static_cast<T>(1) : static_cast<T>(0);
        }
        __syncthreads();
    
        // Deterministic thresholds, rank-0 registers only (no other thread ever
        // branches on them): convergence target off(B)_F <= eps*||A||_F, and a
        // much smaller per-rotation skip cutoff eps*||A||_F/n² (so the sum of all
        // skipped entries stays far below the convergence target).
        T tol_off = static_cast<T>(0), tol_skip = static_cast<T>(0);
        if (rank == 0) {
            T fro2 = static_cast<T>(0);
            for (uint32_t i = 0; i < n*n; i++) fro2 += s_B[i]*s_B[i];
            tol_off  = syev_eps<T>() * sqrt(fro2);   // type-generic sqrt
            tol_skip = tol_off / static_cast<T>(n*n);
        }
    
        constexpr uint32_t SYEV_MAX_SWEEPS = 15;   // typical convergence: 5-8 sweeps (n <= 32)
        for (uint32_t sweep = 0; sweep < SYEV_MAX_SWEEPS; sweep++) {
            // One cyclic sweep: fixed (p, q) order => deterministic.
            for (uint32_t p = 0; p + 1 < n; p++) {
                for (uint32_t q = p + 1; q < n; q++) {
                    // Rank 0 computes the rotation into shared (identical FMA chain
                    // every launch); a skipped rotation publishes the identity.
                    if (rank == 0) {
                        T bpq = s_B[p + q*n];
                        T abpq = (bpq < static_cast<T>(0)) ? -bpq : bpq;
                        T c = static_cast<T>(1), s = static_cast<T>(0);
                        if (abpq > tol_skip) {
                            T theta = (s_B[q + q*n] - s_B[p + p*n]) / (static_cast<T>(2)*bpq);
                            T atheta = (theta < static_cast<T>(0)) ? -theta : theta;
                            T t = static_cast<T>(1) / (atheta + sqrt(static_cast<T>(1) + theta*theta));
                            if (theta < static_cast<T>(0)) t = -t;
                            c = static_cast<T>(1) / sqrt(static_cast<T>(1) + t*t);
                            s = t*c;
                        }
                        s_ctrl[0] = c; s_ctrl[1] = s;
                    }
                    __syncthreads();                 // (c, s) visible to the block
                    T c = s_ctrl[0], s = s_ctrl[1];
                    if (s != static_cast<T>(0)) {    // uniform branch: same shared values everywhere
                        // Rotate rows/cols p,q of B. Index k owns entries
                        // {(k,p),(k,q),(p,k),(q,k)} — mirror writes keep B exactly
                        // symmetric — and its new values read only k-owned slots
                        // (B[k+p*n], B[k+q*n]), so there is no cross-thread hazard.
                        // The 2x2 pivot block is owned by k == p (k == q idles);
                        // its stable update uses t = s/c: B_pp -= t*B_pq,
                        // B_qq += t*B_pq, B_pq = 0 exactly (the annihilation).
                        T t = s / c;
                        for (uint32_t k = rank; k < n; k += size) {
                            if (k == q) continue;
                            if (k == p) {
                                T bpq = s_B[p + q*n];
                                s_B[p + p*n] -= t*bpq;
                                s_B[q + q*n] += t*bpq;
                                s_B[p + q*n] = static_cast<T>(0);
                                s_B[q + p*n] = static_cast<T>(0);
                            } else {
                                T bkp = s_B[k + p*n], bkq = s_B[k + q*n];
                                T nkp = c*bkp - s*bkq;
                                T nkq = s*bkp + c*bkq;
                                s_B[k + p*n] = nkp; s_B[p + k*n] = nkp;
                                s_B[k + q*n] = nkq; s_B[q + k*n] = nkq;
                            }
                        }
                        // Accumulate the rotation into V's columns p,q (row k is
                        // k-owned; disjoint from the B loop's data, no barrier
                        // needed between the two loops).
                        for (uint32_t k = rank; k < n; k += size) {
                            T vkp = V[k + p*n], vkq = V[k + q*n];
                            V[k + p*n] = c*vkp - s*vkq;
                            V[k + q*n] = s*vkp + c*vkq;
                        }
                    }
                    // UNCONDITIONAL trailing barrier: rotated B/V visible before the
                    // next (c, s) — and, on a skipped rotation, it keeps rank 0 from
                    // overwriting s_ctrl[0..1] while another thread is still reading
                    // the previous pair's values (which could diverge the skip branch).
                    __syncthreads();
                }
            }
            // Sweep-end early exit: rank 0 serially sums the squared off-diagonals
            // (deterministic for any block size) and publishes the verdict.
            if (rank == 0) {
                T off2 = static_cast<T>(0);
                for (uint32_t c = 0; c < n; c++)
                    for (uint32_t r = 0; r < n; r++)
                        if (r != c) off2 += s_B[r + c*n]*s_B[r + c*n];
                s_ctrl[2] = (off2 <= tol_off*tol_off) ? static_cast<T>(1) : static_cast<T>(0);
            }
            __syncthreads();                         // flag visible to the block
            bool done = (s_ctrl[2] != static_cast<T>(0));
            __syncthreads();                         // all reads done before rank 0 rewrites s_ctrl
            if (done) break;                         // uniform: same shared value everywhere
        }
    
        // Ascending sort: rank 0 selection-sorts the diagonal into a permutation
        // (strict '<' => ties keep the lower original index — deterministic).
        if (rank == 0) {
            for (uint32_t i = 0; i < n; i++) s_perm[i] = i;
            for (uint32_t i = 0; i + 1 < n; i++) {
                uint32_t best = i;
                for (uint32_t j = i + 1; j < n; j++)
                    if (s_B[s_perm[j]*n + s_perm[j]] < s_B[s_perm[best]*n + s_perm[best]]) best = j;
                uint32_t tmp = s_perm[i]; s_perm[i] = s_perm[best]; s_perm[best] = tmp;
            }
        }
        __syncthreads();                             // permutation visible to the block
        // Permuted copy-out. Eigenvalues first (they read diag(B))...
        for (uint32_t i = rank; i < n; i += size) {
            uint32_t pi = s_perm[i];
            W[i] = s_B[pi*n + pi];
        }
        __syncthreads();                             // W extracted before B is overwritten
        // ...then permute V's columns through the B scratch (B is dead now).
        for (uint32_t idx = rank; idx < n*n; idx += size) s_B[idx] = V[idx];
        __syncthreads();                             // staging complete before the permuted write
        for (uint32_t idx = rank; idx < n*n; idx += size) {
            uint32_t r = idx % n, c = idx / n;
            V[idx] = s_B[r + s_perm[c]*n];
        }
        __syncthreads();                             // outputs valid for every thread on return
    }
    
    template <typename T>
    __device__ void syev(uint32_t n, const T *A, T *W, T *V, T *s_scratch)
    {
        syev_impl<T>(n, A, W, V, s_scratch);
    }
    
    /**
     * @brief Compile-time-size symmetric eigendecomposition (cyclic Jacobi).
     *
     * Same as the runtime `syev` but with the dimension as a template parameter,
     * letting the compiler bake `N` in (constant-folded trip counts / indexing).
     * `A` is preserved; `W` ascending; `V` column i ↔ `W[i]`. NumPy equivalent:
     * `W, V = np.linalg.eigh(A)`.
     *
     * @tparam T  Scalar type.
     * @tparam N  Matrix dimension (A is N x N; designed for N <= 32).
     * @param A          In: N x N symmetric matrix (column-major). NOT modified.
     * @param W          Out: N eigenvalues, ascending.
     * @param V          Out: N x N eigenvectors (column-major; column i ↔ W[i]).
     * @param s_scratch  Shared scratch of `syev_scratch_bytes<T>(N)` bytes.
     */
    template <typename T, uint32_t N>
    __device__ void syev(const T *A, T *W, T *V, T *s_scratch)
    {
        syev_impl<T>(ct_size<N>{}, A, W, V, s_scratch);
    }
    
    /**
     * @brief Scratch size in bytes for `eig_clamp`.
     *
     * Exact layout (in `T` elements): `n` eigenvalues + `n*n` eigenvectors +
     * `syev`'s own scratch (`n*n + n + 4` — see `syev_scratch_bytes`), i.e.
     * `2*n*n + 2*n + 4` elements total.
     *
     * @tparam T  Scalar type.
     * @param n  Matrix dimension (A is n x n).
     * @return Bytes to allocate for `eig_clamp`'s `s_scratch`.
     */
    template <typename T>
    __host__ __device__ constexpr std::size_t eig_clamp_scratch_bytes(uint32_t n)
    {
        return static_cast<std::size_t>(2*n*n + 2*n + 4) * sizeof(T);
    }
    
    /**
     * @brief Clamp the eigenvalues of a symmetric matrix in place:
     *        `A := V diag(max(W, eps)) Vᵀ` where `W, V = eigh(A)`.
     *
     * The Hessian-regularization op solvers host-round-trip for: eigendecompose the
     * symmetric `n x n` column-major `A` (device-side `syev`), floor every
     * eigenvalue at `eps`, and reconstruct in place — the result is symmetric
     * positive-definite for any symmetric input when `eps > 0` (indefinite and
     * negative-definite inputs included). If `A`'s eigenvalues already all exceed
     * `eps`, the result is `A` up to the eigensolver's round-off. NumPy equivalent:
     * `W, V = np.linalg.eigh(A); A = (V * np.maximum(W, eps)) @ V.T`.
     *
     * The reconstruction is a hand-rolled thread-strided loop (each thread owns
     * disjoint output entries of `A`; it reads only the shared `W`/`V`, so no
     * barrier is needed inside the pass): entry `(r, c)` accumulates
     * `sum_k max(W[k], eps) * V[lo,k] * V[hi,k]` with `lo = min(r,c)`,
     * `hi = max(r,c)` — the canonical operand order makes the mirror entries'
     * FMA chains identical, so the output is exactly symmetric bit-for-bit.
     * Thread-count invariant end to end (inherits `syev`'s determinism).
     *
     * @tparam T  Scalar type.
     * @param n          Matrix dimension (A is n x n; designed for n <= 32).
     * @param A          In/out: n x n symmetric matrix (column-major); on return
     *                   holds the eigenvalue-clamped reconstruction (SPD).
     * @param eps        Eigenvalue floor (e.g. a small positive regularizer).
     * @param s_scratch  Shared scratch of `eig_clamp_scratch_bytes<T>(n)` bytes.
     */
    // Shared body (runtime + compile-time overloads): SizeT deduced — uint32_t or
    // ct_size<N> (constant-folds the trip counts / indexing).
    template <typename T, typename SizeT>
    __device__ void eig_clamp_impl(SizeT n, T *A, T eps, T *s_scratch)
    {
        uint32_t rank = threadIdx.x + threadIdx.y*blockDim.x + threadIdx.z*blockDim.x*blockDim.y;
        uint32_t size = blockDim.x * blockDim.y * blockDim.z;
        // Scratch layout — see eig_clamp_scratch_bytes: W (n) | V (n*n) | syev scratch.
        T *s_W = s_scratch;
        T *s_V = s_scratch + n;
        T *s_sy = s_scratch + n + n*n;
        // syev reads A only in its initial copy phase and ends on a barrier, so A
        // is safely overwritten by the reconstruction below.
        syev_impl<T>(n, A, s_W, s_V, s_sy);
        for (uint32_t idx = rank; idx < n*n; idx += size) {
            uint32_t r = idx % n, c = idx / n;
            uint32_t lo = (r < c) ? r : c, hi = (r < c) ? c : r;
            T sum = static_cast<T>(0);
            for (uint32_t k = 0; k < n; k++) {
                T w = s_W[k];
                if (w < eps) w = eps;
                T t = w * s_V[lo + k*n];       // canonical (lo, hi) order => the
                sum += t * s_V[hi + k*n];      // mirror entry is bit-identical
            }
            A[idx] = sum;
        }
        __syncthreads();                       // clamped A valid for every thread on return
    }
    
    template <typename T>
