            s_XImats[38] = static_cast<T>(-0.174009664070881*s_temp[30]);
            s_XImats[40] = static_cast<T>(0.0512066851313736*s_temp[1] + 0.030465*s_temp[30]);
            s_XImats[41] = static_cast<T>(-0.030465*s_temp[1] + 0.0512066851313736*s_temp[30]);
            s_XImats[43] = static_cast<T>(s_temp[30]);
            s_XImats[44] = static_cast<T>(-s_temp[1]);
            s_XImats[46] = static_cast<T>(0.00530120433669357*s_temp[1]);
            s_XImats[47] = static_cast<T>(0.00530120433669357*s_temp[30]);
            s_XImats[49] = static_cast<T>(0.984743944802856*s_temp[1]);
            s_XImats[50] = static_cast<T>(0.984743944802856*s_temp[30]);
            s_XImats[52] = static_cast<T>(0.00904850253263497*s_temp[1]);
            s_XImats[53] = static_cast<T>(0.00904850253263497*s_temp[30]);
            // X[2]
