    /**
     * Computes the Hessian (and Jacobian) of the End Effector Pose with respect to generalized velocity (d^2/dv^2 tangent, pinocchio convention)
     *
     * Notes:
     *   Closed-form analytic d2(pose)/dv2; matches RBDReference.end_effector_pose_hessian_analytic (which agrees with pinocchio getJointKinematicHessian(LOCAL_WORLD_ALIGNED) to the FD floor fleet-wide; CUDA confirmed on iiwa14-fixed + go2-floating).
     *   Inner-owns scratch placement: the large nv^2 output s_end_effector_pose_hessian moves to d_workspace when !OUT_IN_SMEM. The s_Xworld+s_Sworld+s_E_sc scratch in s_temp stays in smem at every tier.
     *
     * @param s_end_effector_pose_hessian is a pointer to memory of size 6*NUM_VEL*NUM_VEL*NUM_EE where NUM_VEL = 29 and NUM_EE = 1 (d^2(pose)/dv^2 tangent-space Hessian, pinocchio convention)
     * @param s_end_effector_pose_gradient is a pointer to memory of size 6*NUM_VEL*NUM_EE (the d/dv tangent Jacobian at q)
     * @param s_q is the vector of joint positions (size NUM_POS = 29; kept for signature compatibility, unused by the analytic path)
     * @param s_Xhom is the per-joint LOCAL homogeneous-transform buffer (read-only)
     * @param s_temp is helper shared memory of size 2496 (s_Xworld | s_Sworld | s_E_sc; always kept in smem)
     * @param d_workspace is the global spill arena s_end_effector_pose_hessian is repointed at when !OUT_IN_SMEM (else unused)
     * @param d_robotModel is the model-specific helper struct (kept for signature compatibility, unused by the analytic path)
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param s_linalg_smem is optional byte-addressed shared memory (reserved; unused by this inner)
     */
    template <typename T, bool OUT_IN_SMEM = true>
    __device__
    void end_effector_pose_hessian_inner_left_hand_palm_joint(T *s_end_effector_pose_hessian, T *s_end_effector_pose_gradient, const T *s_q, T *s_Xhom, int *s_topology_helpers, T *s_temp, T *d_workspace, const robotModel<T> *d_robotModel, unsigned char *s_linalg_smem) {
        if constexpr (!OUT_IN_SMEM) { s_end_effector_pose_hessian = d_workspace; } else { (void)d_workspace; }
        (void)s_q; (void)d_robotModel; (void)s_linalg_smem;
        // scratch in s_temp: s_Xworld (16*n_joints) | s_Sworld (16*nv*num_ees) | s_E_sc (4*num_ees)
        T *s_Xworld = &s_temp[0];
        T *s_Sworld = &s_temp[624];  // per-DOF world-frame 4x4 generator (S_i_world)
        T *s_E_sc   = &s_temp[1088];  // cy, sy, cp, sp per ee
        //
        // Step 1: forward kinematics -- build s_Xworld[16*j] for every joint via BFS-level chain-up
        //
        // BFS level 0 -> joints [0, 6, 12]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 48; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 0; par = -1; }
            else if (slot < 2){ jid = 6; par = -1; }
            else              { jid = 12; par = -1; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 1 -> joints [1, 7, 13]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 48; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 1; par = 0; }
            else if (slot < 2){ jid = 7; par = 6; }
            else              { jid = 13; par = 12; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 2 -> joints [2, 8, 14]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 48; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 2; par = 1; }
            else if (slot < 2){ jid = 8; par = 7; }
            else              { jid = 14; par = 13; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 3 -> joints [3, 9, 15, 22]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 3; par = 2; }
            else if (slot < 2){ jid = 9; par = 8; }
            else if (slot < 3){ jid = 15; par = 14; }
            else              { jid = 22; par = 14; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 4 -> joints [4, 10, 16, 23]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 4; par = 3; }
            else if (slot < 2){ jid = 10; par = 9; }
            else if (slot < 3){ jid = 16; par = 15; }
            else              { jid = 23; par = 22; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 5 -> joints [5, 11, 17, 24]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 64; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 5; par = 4; }
            else if (slot < 2){ jid = 11; par = 10; }
            else if (slot < 3){ jid = 17; par = 16; }
            else              { jid = 24; par = 23; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 6 -> joints [18, 25]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 32; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 18; par = 17; }
            else              { jid = 25; par = 24; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 7 -> joints [19, 26]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 32; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 19; par = 18; }
            else              { jid = 26; par = 25; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 8 -> joints [20, 27]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 32; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 20; par = 19; }
            else              { jid = 27; par = 26; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        // BFS level 9 -> joints [21, 28]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 32; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int jid; int par;
                 if (slot < 1){ jid = 21; par = 20; }
            else              { jid = 28; par = 27; }
            if (par == -1) {
                s_Xworld[16*jid + ele] = s_Xhom[16*jid + ele];
            }
            else {
                s_Xworld[16*jid + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*jid + 4*col]);
            }
        }
        __syncthreads();
        //
        // Step 1b: world transform of the fixed kinematic target(s): Xworld[anchor] = Xworld[parent] @ Xhom_local[anchor]
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 16; ind += blockDim.x*blockDim.y){
            int slot = ind / 16; int ele = ind % 16;
            int row = ele & 3; int col = ele >> 2;
            // branch to get pointer locations
            int anc; int par;
                 if (slot < 1){ anc = 32; par = 21; }
            s_Xworld[16*anc + ele] = dot_prod<T,4,4,1>(&s_Xworld[16*par + row], &s_Xhom[16*anc + 4*col]);
        }
        __syncthreads();
        //
        // Step 2: build per-DOF world-frame 4x4 generator S_i_world
        //
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 464; ind += blockDim.x*blockDim.y){
            s_Sworld[ind] = static_cast<T>(0);
        }
        __syncthreads();
        for(int sworld_slot = threadIdx.x + threadIdx.y*blockDim.x; sworld_slot < 10; sworld_slot += blockDim.x*blockDim.y){
            if (sworld_slot == 0) {
                // ee=0 vi=12 jid=12 rev ax_local=[0.0, 0.0, 1.0]
                {
                    T axw_0 = s_Xworld[200] * static_cast<T>(1);
                    T axw_1 = s_Xworld[201] * static_cast<T>(1);
                    T axw_2 = s_Xworld[202] * static_cast<T>(1);
                    T pjx = s_Xworld[204];
                    T pjy = s_Xworld[205];
                    T pjz = s_Xworld[206];
                    s_Sworld[192] = static_cast<T>(0);
                    s_Sworld[193] =  axw_2;
                    s_Sworld[194] = -axw_1;
                    s_Sworld[196] = -axw_2;
                    s_Sworld[197] = static_cast<T>(0);
                    s_Sworld[198] =  axw_0;
                    s_Sworld[200] =  axw_1;
                    s_Sworld[201] = -axw_0;
                    s_Sworld[202] = static_cast<T>(0);
                    s_Sworld[204] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[205] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[206] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 1) {
                // ee=0 vi=13 jid=13 rev ax_local=[1.0, 0.0, 0.0]
                {
                    T axw_0 = s_Xworld[208] * static_cast<T>(1);
                    T axw_1 = s_Xworld[209] * static_cast<T>(1);
                    T axw_2 = s_Xworld[210] * static_cast<T>(1);
                    T pjx = s_Xworld[220];
                    T pjy = s_Xworld[221];
                    T pjz = s_Xworld[222];
                    s_Sworld[208] = static_cast<T>(0);
                    s_Sworld[209] =  axw_2;
                    s_Sworld[210] = -axw_1;
                    s_Sworld[212] = -axw_2;
                    s_Sworld[213] = static_cast<T>(0);
                    s_Sworld[214] =  axw_0;
                    s_Sworld[216] =  axw_1;
                    s_Sworld[217] = -axw_0;
                    s_Sworld[218] = static_cast<T>(0);
                    s_Sworld[220] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[221] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[222] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 2) {
                // ee=0 vi=14 jid=14 rev ax_local=[0.0, 1.0, 0.0]
                {
                    T axw_0 = s_Xworld[228] * static_cast<T>(1);
                    T axw_1 = s_Xworld[229] * static_cast<T>(1);
                    T axw_2 = s_Xworld[230] * static_cast<T>(1);
                    T pjx = s_Xworld[236];
                    T pjy = s_Xworld[237];
                    T pjz = s_Xworld[238];
                    s_Sworld[224] = static_cast<T>(0);
                    s_Sworld[225] =  axw_2;
                    s_Sworld[226] = -axw_1;
                    s_Sworld[228] = -axw_2;
                    s_Sworld[229] = static_cast<T>(0);
                    s_Sworld[230] =  axw_0;
                    s_Sworld[232] =  axw_1;
                    s_Sworld[233] = -axw_0;
                    s_Sworld[234] = static_cast<T>(0);
                    s_Sworld[236] = pjy*axw_2 - pjz*axw_1;
                    s_Sworld[237] = pjz*axw_0 - pjx*axw_2;
                    s_Sworld[238] = pjx*axw_1 - pjy*axw_0;
                }
            }
            if (sworld_slot == 3) {
                // ee=0 vi=15 jid=15 rev ax_local=[0.0, 1.0, 0.0]
                {
                    T axw_0 = s_Xworld[244] * static_cast<T>(1);
                    T axw_1 = s_Xworld[245] * static_cast<T>(1);
                    T axw_2 = s_Xworld[246] * static_cast<T>(1);
                    T pjx = s_Xworld[252];
                    T pjy = s_Xworld[253];
