        }
        // X_hom[27] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[27]));
            const T c = static_cast<T>(cos(s_q[27]));
            (void)s; (void)c;
            s_XmatsHom[16*27 + 0] = static_cast<T>(c);
            s_XmatsHom[16*27 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*27 + 8] = static_cast<T>(s);
            s_XmatsHom[16*27 + 10] = static_cast<T>(c);
        }
        // X_hom[28] q-dependent cells
        {
            const T s = static_cast<T>(sin(s_q[28]));
            const T c = static_cast<T>(cos(s_q[28]));
            (void)s; (void)c;
            s_XmatsHom[16*28 + 0] = static_cast<T>(c);
            s_XmatsHom[16*28 + 1] = static_cast<T>(s);
