            s_XmatsHom[16*5 + 10] = static_cast<T>(c);
        }
        if (lane == 6) {
            const T s = static_cast<T>(sin(s_q[6]));
            const T c = static_cast<T>(cos(s_q[6]));
            (void)s; (void)c;
            s_XmatsHom[16*6 + 0] = static_cast<T>(c);
            s_XmatsHom[16*6 + 2] = static_cast<T>(-s);
            s_XmatsHom[16*6 + 8] = static_cast<T>(s);
            s_XmatsHom[16*6 + 10] = static_cast<T>(c);
        }
        if (lane == 7) {
            const T s = static_cast<T>(sin(s_q[7]));
            const T c = static_cast<T>(cos(s_q[7]));
