            if (row == ((s_topology_helpers[29 + jid]) > 0 ? (s_topology_helpers[29 + jid]) - 1 : -(s_topology_helpers[29 + jid]) - 1)){s_vaf[jid6 + ((s_topology_helpers[29 + jid]) > 0 ? (s_topology_helpers[29 + jid]) - 1 : -(s_topology_helpers[29 + jid]) - 1)] += (((s_topology_helpers[29 + jid]) > 0 ? 1 : -1)) * s_qd[jid];}
        }
