        grid_linalg_segmented_row_strided_gemv<T,6,6,6,true>(3, seg_a_off_lvl1, seg_v_x_off_lvl1, seg_v_y_off_lvl1, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0), seg_s_off_lvl1, S_sel_lvl1, s_temp, s_linalg_smem);
        static const int seg_a_x_off_lvl1[3] = {174, 210, 246};
