        __syncthreads();
        grid_linalg_segmented_row_strided_gemv<T,6,6,6,true>(3, seg_a_off_lvl2, seg_v_x_off_lvl2, seg_v_y_off_lvl2, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0), seg_s_off_lvl2, S_sel_lvl2, s_temp, s_linalg_smem);
