        grid_linalg_segmented_row_strided_gemv<T,6,6,6>(3, seg_a_off_lvl2, seg_a_x_off_lvl2, seg_a_y_off_lvl2, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0));
        // sync before a += MxS(v)*qd[S] 
