            mxX_peq_scaled<T>(&s_vaf[174 + 6*jid], &s_vaf[6*jid], (((s_topology_helpers[29 + jid]) > 0 ? 1 : -1)) * s_qd[jid], ((s_topology_helpers[29 + jid]) > 0 ? (s_topology_helpers[29 + jid]) - 1 : -(s_topology_helpers[29 + jid]) - 1));
        }
        __syncthreads();
