        //     joints are: left_wrist_yaw_joint, right_wrist_yaw_joint
        //     links are: left_wrist_yaw_link, right_wrist_yaw_link
        // s_v[k] = X[k]*v[parent_k] + S[k]*qd[k] and s_a[k] = X[k]*a[parent_k] + mxS[k](v[k])*qd[k]
        static const int seg_a_off_lvl9[2] = {756, 1008};
        static const int seg_v_x_off_lvl9[2] = {120, 162};
        static const int seg_v_y_off_lvl9[2] = {126, 168};
        static const int seg_s_off_lvl9[2] = {0, 6};
        static const T S_sel_lvl9[12] = {static_cast<T>(0), static_cast<T>(0), static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0)};
        if(threadIdx.x == 0 && threadIdx.y == 0){
            s_temp[0] = s_qd[21];
            s_temp[1] = s_qd[28];
        }
        __syncthreads();
        grid_linalg_segmented_row_strided_gemv<T,6,6,6,true>(2, seg_a_off_lvl9, seg_v_x_off_lvl9, seg_v_y_off_lvl9, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0), seg_s_off_lvl9, S_sel_lvl9, s_temp, s_linalg_smem);
        static const int seg_a_x_off_lvl9[2] = {294, 336};
        static const int seg_a_y_off_lvl9[2] = {300, 342};
        grid_linalg_segmented_row_strided_gemv<T,6,6,6>(2, seg_a_off_lvl9, seg_a_x_off_lvl9, seg_a_y_off_lvl9, s_XImats, s_vaf, s_vaf, static_cast<T>(1), static_cast<T>(0));
        // sync before a += MxS(v)*qd[S] 
        __syncthreads();
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 2; ind += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = (ind == 0) * 21 + (ind == 1) * 28;
            mx2_peq_scaled<T>(&s_vaf[174 + 6*jid], &s_vaf[6*jid], (1) * s_qd[jid]);
        }
        __syncthreads();
        //
        // s_f in parallel given all v, a
        //
        // s_f[k] = I[k]*a[k] + fx(v[k])*I[k]*v[k]
        // start with s_f[k] = I[k]*a[k] and temp = *I[k]*v[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 348; ind += blockDim.x*blockDim.y){
            int row = ind % 6; int comp = ind / 6; int jid = comp % 29;
            bool IaFlag = comp == jid; int jid6 = 6*jid; int vaOffset = IaFlag * 174 + jid6;
            T *dst = IaFlag ? &s_vaf[348] : s_temp;
            // compute based on the branch and save Iv to temp to prep for fx(v)*Iv and then sync
            dst[jid6 + row] = dot_prod<T,6,6,1>(&s_XImats[1044 + 6*jid6 + row], &s_vaf[vaOffset]);
        }
        __syncthreads();
        // finish with s_f[k] += fx(v[k])*Iv[k]
        for(int jid = threadIdx.x + threadIdx.y*blockDim.x; jid < 29; jid += blockDim.x*blockDim.y){
            int jid6 = 6*jid;
            fx_times_v_peq<T>(&s_vaf[348 + jid6], &s_vaf[jid6], &s_temp[jid6]);
            if (d_f_ext != nullptr) {
                for (int r = 0; r < 6; r++) { s_vaf[348 + jid6 + r] -= d_f_ext[jid6 + r]; }
            }
        }
        __syncthreads();
        //
        // Backward Pass
        //
        // s_f update where bfs_level is 9
        //     joints are: left_wrist_yaw_joint, right_wrist_yaw_joint
        //     links are: left_wrist_yaw_link, right_wrist_yaw_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[756], &s_vaf[474], &s_vaf[468], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[1008], &s_vaf[516], &s_vaf[510], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 8
        //     joints are: left_wrist_pitch_joint, right_wrist_pitch_joint
        //     links are: left_wrist_pitch_link, right_wrist_pitch_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[720], &s_vaf[468], &s_vaf[462], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[972], &s_vaf[510], &s_vaf[504], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 7
        //     joints are: left_wrist_roll_joint, right_wrist_roll_joint
        //     links are: left_wrist_roll_link, right_wrist_roll_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[684], &s_vaf[462], &s_vaf[456], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[936], &s_vaf[504], &s_vaf[498], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 6
        //     joints are: left_elbow_joint, right_elbow_joint
        //     links are: left_elbow_link, right_elbow_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[648], &s_vaf[456], &s_vaf[450], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[900], &s_vaf[498], &s_vaf[492], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 5
        //     joints are: left_ankle_roll_joint, right_ankle_roll_joint, left_shoulder_yaw_joint, right_shoulder_yaw_joint
        //     links are: left_ankle_roll_link, right_ankle_roll_link, left_shoulder_yaw_link, right_shoulder_yaw_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[180], &s_vaf[378], &s_vaf[372], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[396], &s_vaf[414], &s_vaf[408], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[612], &s_vaf[450], &s_vaf[444], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[864], &s_vaf[492], &s_vaf[486], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 4
        //     joints are: left_ankle_pitch_joint, right_ankle_pitch_joint, left_shoulder_roll_joint, right_shoulder_roll_joint
        //     links are: left_ankle_pitch_link, right_ankle_pitch_link, left_shoulder_roll_link, right_shoulder_roll_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[144], &s_vaf[372], &s_vaf[366], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[360], &s_vaf[408], &s_vaf[402], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[576], &s_vaf[444], &s_vaf[438], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[828], &s_vaf[486], &s_vaf[480], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 3
        //     joints are: left_knee_joint, right_knee_joint, left_shoulder_pitch_joint, right_shoulder_pitch_joint
        //     links are: left_knee_link, right_knee_link, left_shoulder_pitch_link, right_shoulder_pitch_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[108], &s_vaf[366], &s_vaf[360], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[324], &s_vaf[402], &s_vaf[396], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[540], &s_vaf[438], &s_vaf[432], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[792], &s_vaf[480], &s_vaf[432], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 2
        //     joints are: left_hip_yaw_joint, right_hip_yaw_joint, waist_pitch_joint
        //     links are: left_hip_yaw_link, right_hip_yaw_link, torso_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[72], &s_vaf[360], &s_vaf[354], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[288], &s_vaf[396], &s_vaf[390], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[504], &s_vaf[432], &s_vaf[426], static_cast<T>(1), static_cast<T>(1));
        // s_f update where bfs_level is 1
        //     joints are: left_hip_roll_joint, right_hip_roll_joint, waist_roll_joint
        //     links are: left_hip_roll_link, right_hip_roll_link, waist_roll_link
        // s_f[parent_k] += X[k]^T*f[k]
        grid_linalg_gemv<T,6,6,true>(&s_XImats[36], &s_vaf[354], &s_vaf[348], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[252], &s_vaf[390], &s_vaf[384], static_cast<T>(1), static_cast<T>(1));
        grid_linalg_gemv<T,6,6,true>(&s_XImats[468], &s_vaf[426], &s_vaf[420], static_cast<T>(1), static_cast<T>(1));
    }

    /**
     * Compute the RNEA (Recursive Newton-Euler Algorithm)
     *
     * @param s_c is the vector of output torques
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
     * @param s_qdd is the vector of joint accelerations
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     * @param gravity is the gravity constant
     */
    template <typename T>
    __device__
    void inverse_dynamics_device(T *s_c,  const T *s_q, const T *s_qd, const T *s_qdd, const robotModel<T> *d_robotModel, T *d_f_ext, const T gravity) {
        // GRID shared arena layout
        //   T s_vaf[522]
        //   T s_XImats[2088]
        //   T s_temp[174]
        //   int s_topology_helpers[175]
        //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
        extern __shared__ __align__(16) unsigned char s_arena[];
        size_t s_arena_offset = 0;
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(522);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
        T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(T) * static_cast<size_t>(174);
        s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
        int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
        s_arena_offset += sizeof(int) * static_cast<size_t>(175);
        unsigned char *s_linalg_smem = nullptr;
        if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
            s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
            s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
            s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
        }
        #ifdef GRID_CUDA_DEBUG_LAYOUT
        assert(s_arena_offset == grid_shared_arena_bytes<T>(2784, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
        #endif
        (void)s_arena_offset;
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        inverse_dynamics_inner<T>(s_c, s_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_f_ext, gravity);
    }

