            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(11801, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
