    /**
     * Compute the f_ext gradient (batched kernel)
     *
     * @param d_dtau_dfext / d_dqdd_dfext are the two outputs (each NV*6*NB per timestep)
     * @param d_workspace is the L2-pinned global spill buffer (outputs / minv-F at spilled tiers)
     * @param d_q is the joint positions, stride_q the per-timestep stride
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param NUM_TIMESTEPS is the trajectory length (or timing reps)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void f_ext_gradient_kernel_single_timing(T *d_dtau_dfext, T *d_dqdd_dfext, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[29]
            //   T s_dtau_dfext[5046]
            //   T s_dqdd_dfext[5046]
            //   T s_XImats[2088]
            //   T s_temp[7422]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dtau_dfext = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(5046);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dqdd_dfext = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(5046);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(7422);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(19631, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            (void)d_workspace;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 29; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (29)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_dtau_dfext into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (29)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (29)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (29)] += _aopt_fb3;
                }
                __syncthreads();
                T *s_Minv = s_temp;
                T *s_fext_temp = &s_temp[841];
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                f_ext_gradient_jacobianT_inner<T>(s_dtau_dfext, s_q, s_XImats, s_topology_helpers, s_fext_temp);
                __syncthreads();
                minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_fext_temp, nullptr);
                __syncthreads();
                // densify Minv (minv emits symmetric-upper)
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 841; ind += blockDim.x*blockDim.y){
                    int r = ind % 29; int c = ind / 29;
                    if (c < r) { s_Minv[r + 29*c] = s_Minv[c + 29*r]; }
                }
                __syncthreads();
                // dqdd/dfext = M^{-1} J^T = -Minv @ (dtau/dfext)
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                    int row = ind % 29; int col = ind / 29;
                    T acc = static_cast<T>(0);
                    for (int k = 0; k < 29; ++k) { acc += s_Minv[row + 29*k] * s_dtau_dfext[k + 29*col]; }
                    s_dqdd_dfext[ind] = -acc;
                }
                __syncthreads();
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_dtau_dfext)[rep & 1023] = reinterpret_cast<const volatile T *>(s_dtau_dfext)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                d_dtau_dfext[ind] = s_dtau_dfext[ind];
            }
            __syncthreads();
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                d_dqdd_dfext[ind] = s_dqdd_dfext[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_LITE) {
            // GRID shared arena layout
            //   T s_q[29]
            //   T s_dtau_dfext[0]
            //   T s_dqdd_dfext[0]
            //   T s_XImats[2088]
            //   T s_temp[2929]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dtau_dfext = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(0);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dqdd_dfext = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(0);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2929);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(5046, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            s_dqdd_dfext = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
            s_dtau_dfext = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>() + 5046*sizeof(T)]);
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 29; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (29)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_dtau_dfext into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (29)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (29)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (29)] += _aopt_fb3;
                }
                __syncthreads();
                T *s_Minv = s_temp;
                T *s_fext_temp = &s_temp[841];
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                f_ext_gradient_jacobianT_inner<T>(s_dtau_dfext, s_q, s_XImats, s_topology_helpers, s_fext_temp);
                __syncthreads();
                T *minv_d_workspace = reinterpret_cast<T *>(&d_workspace[GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
                minv_inner<T, false>(s_Minv, s_q, s_XImats, s_topology_helpers, s_fext_temp, minv_d_workspace);
                __syncthreads();
                // densify Minv (minv emits symmetric-upper)
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 841; ind += blockDim.x*blockDim.y){
                    int r = ind % 29; int c = ind / 29;
                    if (c < r) { s_Minv[r + 29*c] = s_Minv[c + 29*r]; }
                }
                __syncthreads();
                // dqdd/dfext = M^{-1} J^T = -Minv @ (dtau/dfext)
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                    int row = ind % 29; int col = ind / 29;
                    T acc = static_cast<T>(0);
                    for (int k = 0; k < 29; ++k) { acc += s_Minv[row + 29*k] * s_dtau_dfext[k + 29*col]; }
                    s_dqdd_dfext[ind] = -acc;
                }
                __syncthreads();
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_dtau_dfext)[rep & 1023] = reinterpret_cast<const volatile T *>(s_dtau_dfext)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                d_dtau_dfext[ind] = s_dtau_dfext[ind];
            }
            __syncthreads();
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                d_dqdd_dfext[ind] = s_dqdd_dfext[ind];
            }
            __syncthreads();
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q[29]
            //   T s_dtau_dfext[0]
            //   T s_dqdd_dfext[0]
            //   T s_XImats[2088]
            //   T s_temp[2929]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dtau_dfext = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(0);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dqdd_dfext = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(0);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2929);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(5046, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            s_dqdd_dfext = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
            s_dtau_dfext = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>() + 5046*sizeof(T)]);
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 29; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (29)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_dtau_dfext into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_dtau_dfext)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (29)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (29)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (29)] += _aopt_fb3;
                }
                __syncthreads();
                T *s_Minv = s_temp;
                T *s_fext_temp = &s_temp[841];
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
                f_ext_gradient_jacobianT_inner<T>(s_dtau_dfext, s_q, s_XImats, s_topology_helpers, s_fext_temp);
                __syncthreads();
                T *minv_d_workspace = reinterpret_cast<T *>(&d_workspace[GRID_MINV_F_WORKSPACE_OFFSET_BYTES<T>()]);
                minv_inner<T, false>(s_Minv, s_q, s_XImats, s_topology_helpers, s_fext_temp, minv_d_workspace);
                __syncthreads();
                // densify Minv (minv emits symmetric-upper)
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 841; ind += blockDim.x*blockDim.y){
                    int r = ind % 29; int c = ind / 29;
                    if (c < r) { s_Minv[r + 29*c] = s_Minv[c + 29*r]; }
                }
                __syncthreads();
                // dqdd/dfext = M^{-1} J^T = -Minv @ (dtau/dfext)
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                    int row = ind % 29; int col = ind / 29;
                    T acc = static_cast<T>(0);
                    for (int k = 0; k < 29; ++k) { acc += s_Minv[row + 29*k] * s_dtau_dfext[k + 29*col]; }
                    s_dqdd_dfext[ind] = -acc;
                }
                __syncthreads();
                __syncthreads();
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) { reinterpret_cast<volatile T *>(d_dtau_dfext)[rep & 1023] = reinterpret_cast<const volatile T *>(s_dtau_dfext)[rep & 7]; }
            }
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                d_dtau_dfext[ind] = s_dtau_dfext[ind];
            }
            __syncthreads();
            // save down to global
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                d_dqdd_dfext[ind] = s_dqdd_dfext[ind];
            }
            __syncthreads();
        }
    }

    /**
     * Compute the f_ext gradient (host wrapper)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param num_timesteps is the trajectory length (or timing reps)
     * @param streams are CUDA streams for async transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void f_ext_gradient(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "f_ext_gradient requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("f_ext_gradient", F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (!F_EXT_GRADIENT_DQDD_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {f_ext_gradient_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dtau_dfext,hd_data->d_dqdd_dfext,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {f_ext_gradient_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dtau_dfext,hd_data->d_dqdd_dfext,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_dtau_dfext,hd_data->d_dtau_dfext,NUM_VEL*6*NUM_BODIES*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchk(cudaMemcpy(hd_data->h_dqdd_dfext,hd_data->d_dqdd_dfext,NUM_VEL*6*NUM_BODIES*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute the f_ext gradient (host wrapper)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param num_timesteps is the trajectory length (or timing reps)
     * @param streams are CUDA streams for async transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void f_ext_gradient_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "f_ext_gradient requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("f_ext_gradient", F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (!F_EXT_GRADIENT_DQDD_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        if (USE_COMPRESSED_MEM) {f_ext_gradient_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dtau_dfext,hd_data->d_dqdd_dfext,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {f_ext_gradient_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dtau_dfext,hd_data->d_dqdd_dfext,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_dtau_dfext,hd_data->d_dtau_dfext,NUM_VEL*6*NUM_BODIES*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchk(cudaMemcpy(hd_data->h_dqdd_dfext,hd_data->d_dqdd_dfext,NUM_VEL*6*NUM_BODIES*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call F_EXT_GRADIENT %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute the f_ext gradient (host wrapper)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param num_timesteps is the trajectory length (or timing reps)
     * @param streams are CUDA streams for async transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void f_ext_gradient_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "f_ext_gradient requires all-data or dynamics gridData");
        int stride_q = USE_COMPRESSED_MEM ? NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("f_ext_gradient", F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (!F_EXT_GRADIENT_DQDD_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {f_ext_gradient_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dtau_dfext,hd_data->d_dqdd_dfext,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {f_ext_gradient_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dtau_dfext,hd_data->d_dqdd_dfext,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Compute -dJ^T/dq = d(inverse_dynamics_gradient)/dfext (section A.3, fixed base, batched kernel)
     *
     * @param d_f_ext_gradient_dq is the output -dJ^T/dq, size NV*(6*NB)*NV = 146334 per timestep
     * @param d_q is the joint positions, stride_q the per-timestep stride
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param NUM_TIMESTEPS is the trajectory length (or timing reps)
     */
    template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
    __global__
    __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
    void f_ext_gradient_dq_kernel(T *d_f_ext_gradient_dq, unsigned char *d_workspace, const T *d_q, const int stride_q, const robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
        if constexpr (RESOURCE_TIER == TIER_SHARED) {
            // GRID shared arena layout
            //   T s_q[29]
            //   T s_XImats[2088]
            //   T s_temp[12267]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(12267);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(14384, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            (void)d_workspace;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
