                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_f_ext_gradient_dq)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_f_ext_gradient_dq)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_f_ext_gradient_dq)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (29)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (29)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (29)] += _aopt_fb3;
                }
                __syncthreads();
                T *s_f_ext_gradient_dq = d_f_ext_gradient_dq;
                const T fd_h = static_cast<T>(1e-3);
                T *s_qpert = s_temp;
                T *s_jt_temp = &s_temp[29];
                T *s_xi_scratch = &s_temp[2117];
                T *s_JTp = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
                T *s_JTm = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>() + 5046*sizeof(T)]);
                for (int qi = 0; qi < 29; ++qi) {
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                        s_qpert[ind] = s_q[ind];
                    }
                    __syncthreads();
                    if(threadIdx.x == 0 && threadIdx.y == 0){
                        s_qpert[qi] += fd_h;
                    }
                    __syncthreads();
                    load_update_XImats_helpers<T>(s_XImats, s_qpert, s_topology_helpers, d_robotModel, s_xi_scratch);
                    __syncthreads();
                    f_ext_gradient_jacobianT_inner<T>(s_JTp, s_qpert, s_XImats, s_topology_helpers, s_jt_temp);
                    __syncthreads();
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                        s_qpert[ind] = s_q[ind];
                    }
                    __syncthreads();
                    if(threadIdx.x == 0 && threadIdx.y == 0){
                        s_qpert[qi] -= fd_h;
                    }
                    __syncthreads();
                    load_update_XImats_helpers<T>(s_XImats, s_qpert, s_topology_helpers, d_robotModel, s_xi_scratch);
                    __syncthreads();
                    f_ext_gradient_jacobianT_inner<T>(s_JTm, s_qpert, s_XImats, s_topology_helpers, s_jt_temp);
                    __syncthreads();
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                        s_f_ext_gradient_dq[ind + 5046*qi] = (s_JTp[ind] - s_JTm[ind]) / (static_cast<T>(2)*fd_h);
                    }
                    __syncthreads();
                }
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_xi_scratch);
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q[29]
            //   T s_XImats[2088]
            //   T s_temp[2175]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2175);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4292, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            // load to shared mem
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                s_q[ind] = d_q[ind];
            }
            __syncthreads();
            // compute with NUM_TIMESTEPS as NUM_REPS for timing
            for (int rep = 0; rep < NUM_TIMESTEPS; rep++){
                // anti-LICM: volatile reload of inputs each rep
                for(int _aopt_i = threadIdx.x + threadIdx.y*blockDim.x; _aopt_i < 29; _aopt_i += blockDim.x*blockDim.y){
                    reinterpret_cast<volatile T *>(s_q)[_aopt_i] = reinterpret_cast<const volatile T *>(d_q)[_aopt_i];
                }
                __syncthreads();
                // anti-LICM (1/2): stomp one input slot with `rep`
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    reinterpret_cast<volatile T *>(s_q)[rep % (29)] = static_cast<T>(rep);
                }
                // anti-LICM (2/2): feedback prev rep's d_f_ext_gradient_dq into s_q (true loop-carried dep)
                if ((threadIdx.x | threadIdx.y | threadIdx.z) == 0) {
                    T _aopt_fb1 = reinterpret_cast<const volatile T *>(d_f_ext_gradient_dq)[(rep + 0x3FF) & 0x3FF];
                    T _aopt_fb2 = reinterpret_cast<const volatile T *>(d_f_ext_gradient_dq)[(rep + 0x3FE) & 0x3FF];
                    T _aopt_fb3 = reinterpret_cast<const volatile T *>(d_f_ext_gradient_dq)[(rep + 0x3FD) & 0x3FF];
                    reinterpret_cast<volatile T *>(s_q)[(rep + 1) % (29)] += _aopt_fb1;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 2) % (29)] += _aopt_fb2;
                    reinterpret_cast<volatile T *>(s_q)[(rep + 3) % (29)] += _aopt_fb3;
                }
                __syncthreads();
                T *s_f_ext_gradient_dq = d_f_ext_gradient_dq;
                const T fd_h = static_cast<T>(1e-3);
                T *s_qpert = s_temp;
                T *s_jt_temp = &s_temp[29];
                T *s_xi_scratch = &s_temp[2117];
                T *s_JTp = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>()]);
                T *s_JTm = reinterpret_cast<T *>(&d_workspace[GRID_SO_WORKSPACE_TEMP_OFFSET_BYTES<T>() + 5046*sizeof(T)]);
                for (int qi = 0; qi < 29; ++qi) {
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                        s_qpert[ind] = s_q[ind];
                    }
                    __syncthreads();
                    if(threadIdx.x == 0 && threadIdx.y == 0){
                        s_qpert[qi] += fd_h;
                    }
                    __syncthreads();
                    load_update_XImats_helpers<T>(s_XImats, s_qpert, s_topology_helpers, d_robotModel, s_xi_scratch);
                    __syncthreads();
                    f_ext_gradient_jacobianT_inner<T>(s_JTp, s_qpert, s_XImats, s_topology_helpers, s_jt_temp);
                    __syncthreads();
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                        s_qpert[ind] = s_q[ind];
                    }
                    __syncthreads();
                    if(threadIdx.x == 0 && threadIdx.y == 0){
                        s_qpert[qi] -= fd_h;
                    }
                    __syncthreads();
                    load_update_XImats_helpers<T>(s_XImats, s_qpert, s_topology_helpers, d_robotModel, s_xi_scratch);
                    __syncthreads();
                    f_ext_gradient_jacobianT_inner<T>(s_JTm, s_qpert, s_XImats, s_topology_helpers, s_jt_temp);
                    __syncthreads();
                    for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                        s_f_ext_gradient_dq[ind + 5046*qi] = (s_JTp[ind] - s_JTm[ind]) / (static_cast<T>(2)*fd_h);
                    }
                    __syncthreads();
                }
                load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_xi_scratch);
                __syncthreads();
            }
        }
    }

    /**
     * Compute -dJ^T/dq = d(inverse_dynamics_gradient)/dfext (host wrapper, fixed base)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param num_timesteps is the trajectory length (or timing reps)
     * @param streams are CUDA streams for async transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void f_ext_gradient_dq(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                          const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "f_ext_gradient_dq requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("f_ext_gradient_dq", F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (!F_EXT_GRADIENT_DQ_JT_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {f_ext_gradient_dq_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_f_ext_gradient_dq,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {f_ext_gradient_dq_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_f_ext_gradient_dq,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_f_ext_gradient_dq,hd_data->d_f_ext_gradient_dq,NUM_VEL*6*NUM_BODIES*NUM_VEL*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Compute -dJ^T/dq = d(inverse_dynamics_gradient)/dfext (host wrapper, fixed base)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param num_timesteps is the trajectory length (or timing reps)
     * @param streams are CUDA streams for async transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void f_ext_gradient_dq_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                        const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "f_ext_gradient_dq requires all-data or dynamics gridData");
        // start code with memory transfer
        int stride_q;
        if (USE_COMPRESSED_MEM) {stride_q = NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q,hd_data->h_q,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        else {stride_q = 3*NUM_JOINTS; gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q*sizeof(T),cudaMemcpyHostToDevice,streams[0]));}
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("f_ext_gradient_dq", F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (!F_EXT_GRADIENT_DQ_JT_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        if (USE_COMPRESSED_MEM) {f_ext_gradient_dq_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_f_ext_gradient_dq,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {f_ext_gradient_dq_kernel_single_timing<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_f_ext_gradient_dq,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_f_ext_gradient_dq,hd_data->d_f_ext_gradient_dq,NUM_VEL*6*NUM_BODIES*NUM_VEL*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call F_EXT_GRADIENT_DQ %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Compute -dJ^T/dq = d(inverse_dynamics_gradient)/dfext (host wrapper, fixed base)
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the initialized model helpers on the GPU
     * @param num_timesteps is the trajectory length (or timing reps)
     * @param streams are CUDA streams for async transfers
     */
    template <typename T, bool USE_COMPRESSED_MEM = false, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void f_ext_gradient_dq_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const int num_timesteps,
                                       const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "f_ext_gradient_dq requires all-data or dynamics gridData");
        int stride_q = USE_COMPRESSED_MEM ? NUM_JOINTS: 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("f_ext_gradient_dq", F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (!F_EXT_GRADIENT_DQ_JT_IN_SMEM<RESOURCE_TIER>() && hd_data->d_workspace != nullptr) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        if (USE_COMPRESSED_MEM) {f_ext_gradient_dq_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_f_ext_gradient_dq,hd_data->d_workspace,hd_data->d_q,stride_q,d_robotModel,num_timesteps);}
        else                    {f_ext_gradient_dq_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,F_EXT_GRADIENT_DQ_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_f_ext_gradient_dq,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q,d_robotModel,num_timesteps);}
        gpuErrchkKernel();
    }

    /**
     * Computes the Articulated Body Algorithm
     *
     * Notes:
     *   Assumes the XI matricies have already been updated for the given q
     *   Inner-controlled placement, two orthogonal levers decided at the top:
     *     TEMP_IN_SMEM=false                : whole scratch band -> d_workspace (blunt MINIMAL fallback).
     *     TEMP_IN_SMEM=true, COLD_IN_SMEM=true  : PERF, everything in s_temp (byte-identical to the original).
     *     TEMP_IN_SMEM=true, COLD_IN_SMEM=false : SURGICAL -- hot recursion stays in s_temp, only the cold tempMat slab [98*NJ,140*NJ) spills to d_cold (=d_workspace sub-offset).
     *   Caller sizes the arenas from ABA_INNER_{SMEM,WORKSPACE,COLD}_BYTES.
     *
     * @param s_qdd is the vector of joint accelerations
     * @param s_va is a pointer to shared memory of size 2*6*NUM_JOINTS = 348
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_tau is the vector of joint torques
     * @param s_temp is the (shared) scratch; size ABA_INNER_SMEM_BYTES<T, TEMP_IN_SMEM>() (the 140*NJ+ band when TEMP_IN_SMEM, else 0)
     * @param d_workspace is the global scratch. !TEMP_IN_SMEM: the whole band (ABA_INNER_WORKSPACE_BYTES). TEMP_IN_SMEM && !COLD_IN_SMEM: the cold slab d_cold (ABA_INNER_COLD_BYTES = the [98*NJ,140*NJ) tempMat slab). Pass nullptr at PERF (TEMP_IN_SMEM && COLD_IN_SMEM).
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param gravity is the gravity constant
     * @param d_f_ext is the (optional) GLOBAL external forces, body-major 6*NUM_BODIES local-frame, or nullptr
     */
    template <typename T, bool TEMP_IN_SMEM = true, bool COLD_IN_SMEM = true>
    __device__
    void aba_inner(T *s_qdd, T *s_va, const T *s_q, const T *s_qd, const T *s_tau, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_f_ext, const T gravity) {
        if constexpr (!TEMP_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        T *s_cold = s_temp;
        if constexpr (TEMP_IN_SMEM && !COLD_IN_SMEM) { s_cold = d_workspace - 2842; }
        unsigned char *s_linalg_smem = nullptr;
        //
        // Forward Pass
        //
        // s_v where parent is base
        //     joints are: left_hip_pitch_joint, right_hip_pitch_joint, waist_yaw_joint
        //     links are: left_hip_pitch_link, right_hip_pitch_link, waist_yaw_link
        // s_v[k] = S[k]*qd[k]
        for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 18; ind += blockDim.x*blockDim.y){
            int row = ind % 6;
            // non-branching pointer selector
            int jid = (ind < 6) * 0 + (ind < 12 && ind >= 6) * 6 + (ind >= 12) * 12;
            int jid6 = 6*jid;
            s_va[jid6 + row] = static_cast<T>(0);
            if (row == ((s_topology_helpers[29 + jid]) > 0 ? (s_topology_helpers[29 + jid]) - 1 : -(s_topology_helpers[29 + jid]) - 1)){s_va[jid6 + ((s_topology_helpers[29 + jid]) > 0 ? (s_topology_helpers[29 + jid]) - 1 : -(s_topology_helpers[29 + jid]) - 1)] += (((s_topology_helpers[29 + jid]) > 0 ? 1 : -1)) * s_qd[jid];}
        }
        __syncthreads();
        // s_v where bfs_level is 1
        //     joints are: left_hip_roll_joint, right_hip_roll_joint, waist_roll_joint
        //     links are: left_hip_roll_link, right_hip_roll_link, waist_roll_link
        // s_v[k] = X[k]*v[parent_k] + S[k]*qd[k]
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[36], &s_va[0], &s_va[6], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        if(threadIdx.x == 0 && threadIdx.y == 0){
            s_va[6] += (1) * s_qd[1];
        }
        __syncthreads();
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[252], &s_va[36], &s_va[42], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        if(threadIdx.x == 0 && threadIdx.y == 0){
            s_va[42] += (1) * s_qd[7];
        }
        __syncthreads();
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[468], &s_va[72], &s_va[78], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        if(threadIdx.x == 0 && threadIdx.y == 0){
            s_va[78] += (1) * s_qd[13];
        }
        __syncthreads();
        // s_v where bfs_level is 2
        //     joints are: left_hip_yaw_joint, right_hip_yaw_joint, waist_pitch_joint
        //     links are: left_hip_yaw_link, right_hip_yaw_link, torso_link
        // s_v[k] = X[k]*v[parent_k] + S[k]*qd[k]
        grid_linalg_row_strided_gemv<T,6,6,6>(&s_XImats[72], &s_va[6], &s_va[12], static_cast<T>(1), static_cast<T>(0), s_linalg_smem);
        if(threadIdx.x == 0 && threadIdx.y == 0){
            s_va[14] += (1) * s_qd[2];
        }
        __syncthreads();
