            T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
