            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_grad_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(116);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_q_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(58);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            T *s_temp = nullptr;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7235, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[29]; T *s_u = &s_q_qd_u[58];
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 87; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                // compute — the orchestration inner owns its FD-grad s_temp pool placement
                T *s_D_qdd_stage = reinterpret_cast<T *>(&d_workspace[k * GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                T *s_dAB = reinterpret_cast<T *>(&d_workspace[k * GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_INTEGRATOR_GRADIENT_DAB_OFFSET_BYTES<T>()]);
                integrator_with_gradient_device<T, IT, false, false>(s_dAB, s_x_kp1, s_q, s_qd, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, reinterpret_cast<T *>(&d_workspace[k * GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_INTEGRATOR_GRADIENT_INNER_OFFSET_BYTES<T>()]), nullptr, d_robotModel, d_f_ext, gravity, dt);
                __syncthreads();
                // save down to global
                T *d_dAB_k = &d_dAB[k*5046];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                    d_dAB_k[ind] = s_dAB[ind];
                }
                __syncthreads();
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*58];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 58; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
        else if constexpr (RESOURCE_TIER == TIER_MINIMAL) {
            // GRID shared arena layout
            //   T s_q_qd_u[87]
            //   T s_df_du[1682]
            //   T s_dc_du[1682]
            //   T s_vaf[522]
            //   T s_Minv[841]
            //   T s_qdd[29]
            //   T s_q_orig[29]
            //   T s_qd_orig[29]
            //   T s_stage_grad_qdd[116]
            //   T s_dInt_q_6x6[36]
            //   T s_dInt_v_6x6[36]
            //   T s_x_kp1[58]
            //   T s_XImats[2088]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(87);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1682);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1682);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(522);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(841);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_grad_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(116);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_q_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x_kp1 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(58);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            T *s_temp = nullptr;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7235, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[29]; T *s_u = &s_q_qd_u[58];
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                // load to shared mem
                const T *d_q_qd_u_k = &d_q_qd_u[k*stride_q_qd_u];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 87; ind += blockDim.x*blockDim.y){
                    s_q_qd_u[ind] = d_q_qd_u_k[ind];
                }
                __syncthreads();
                // compute — the orchestration inner owns its FD-grad s_temp pool placement
                T *s_D_qdd_stage = reinterpret_cast<T *>(&d_workspace[k * GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                T *s_dAB = reinterpret_cast<T *>(&d_workspace[k * GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_INTEGRATOR_GRADIENT_DAB_OFFSET_BYTES<T>()]);
                integrator_with_gradient_device<T, IT, false, false>(s_dAB, s_x_kp1, s_q, s_qd, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, reinterpret_cast<T *>(&d_workspace[k * GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>() + GRID_INTEGRATOR_GRADIENT_INNER_OFFSET_BYTES<T>()]), nullptr, d_robotModel, d_f_ext, gravity, dt);
                __syncthreads();
                // save down to global
                T *d_dAB_k = &d_dAB[k*5046];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 5046; ind += blockDim.x*blockDim.y){
                    d_dAB_k[ind] = s_dAB[ind];
                }
                __syncthreads();
                // save down to global
                T *d_x_kp1_k = &d_x_kp1[k*58];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 58; ind += blockDim.x*blockDim.y){
                    d_x_kp1_k[ind] = s_x_kp1[ind];
                }
                __syncthreads();
            }
        }
    }

    /**
     * Run the integrator gradient (default Euler) per timestep and also write x_{k+1}
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_with_gradient(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                      const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator_with_gradient requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_u*num_timesteps*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator_with_gradient", INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_GRADIENT_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        integrator_with_gradient_kernel<T, IT, RESOURCE_TIER><<<block_dimms,thread_dimms,INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dAB,hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        if (GRID_INTEGRATOR_GRADIENT_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_dAB,hd_data->d_dAB,2*NUM_JOINTS*3*NUM_JOINTS*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        gpuErrchk(cudaMemcpy(hd_data->h_x_kp1,hd_data->d_x_kp1,(NUM_POS + NUM_VEL)*num_timesteps*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
    }

    /**
     * Run the integrator gradient (default Euler) per timestep and also write x_{k+1}
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_with_gradient_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                                    const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator_with_gradient requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // start code with memory transfer
        gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd_u*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
        gpuErrchkKernel();
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator_with_gradient", INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_GRADIENT_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()));}
        struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
        integrator_with_gradient_kernel_single_timing<T, IT, RESOURCE_TIER><<<block_dimms,thread_dimms,INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dAB,hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        clock_gettime(CLOCK_MONOTONIC,&end);
        if (GRID_INTEGRATOR_GRADIENT_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
        // finally transfer the result back
        gpuErrchk(cudaMemcpy(hd_data->h_dAB,hd_data->d_dAB,2*NUM_JOINTS*3*NUM_JOINTS*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        gpuErrchk(cudaMemcpy(hd_data->h_x_kp1,hd_data->d_x_kp1,(NUM_POS + NUM_VEL)*sizeof(T),cudaMemcpyDeviceToHost));
        gpuErrchkKernel();
        printf("Single Call INTEGRATOR_WITH_GRADIENT %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
    }

    /**
     * Run the integrator gradient (default Euler) per timestep and also write x_{k+1}
     *
     * @param hd_data is the packaged input and output pointers
     * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU
     * @param gravity is the gravity constant
     * @param dt is the integration timestep
     * @param num_timesteps is the length of the trajectory (or overloaded as test_iters for timing)
     * @param streams are pointers to CUDA streams for async memory transfers (if needed)
     */
    template <typename T, IntegratorType IT = IntegratorType::EULER, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
    __host__
    void integrator_with_gradient_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const T dt, const int num_timesteps,
                                   const dim3 block_dimms, const dim3 thread_dimms) {
        static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "integrator_with_gradient requires all-data or dynamics gridData");
        int stride_q_qd_u = 3*NUM_JOINTS;
        // then call the kernel
        gpuErrchk(grid_check_dynamic_shared_memory_bytes("integrator_with_gradient", INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
        if (GRID_INTEGRATOR_GRADIENT_USES_WORKSPACE) {gpuErrchk(grid_begin_l2_persisting(0, hd_data->d_workspace, GRID_WORKSPACE_BYTES_PER_TIMESTEP<T>()*static_cast<size_t>(num_timesteps)));}
        integrator_with_gradient_kernel<T, IT, RESOURCE_TIER><<<block_dimms,thread_dimms,INTEGRATOR_DU_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_dAB,hd_data->d_x_kp1,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd_u,d_robotModel,hd_data->d_f_ext,gravity,dt,num_timesteps);
        gpuErrchkKernel();
        if (GRID_INTEGRATOR_GRADIENT_USES_WORKSPACE) {gpuErrchk(grid_end_l2_persisting(0));}
    }

    /**
     * Computes the second order derivatives of inverse dynamics
     *
     * Notes:
     *   Loads/updates s_XImats from s_q internally (helper runs after the SCRATCH_IN_SMEM repoint so its scratch follows the placement)
     *
     * @param s_idsva_so is a pointer to memory for the final result of size 4*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS = 97556
     * @param s_q is the vector of joint positions
     * @param s_qd is the vector of joint velocities
     * @param s_qdd is the vector of joint accelerations
     * @param s_temp is the shared scratch pool (used when SCRATCH_IN_SMEM) of size  = 16572
     * @param d_workspace is the global scratch pool: routes the whole s_temp arena (when !SCRATCH_IN_SMEM) or just the cold BC slab (when !BC_IN_SMEM)
     * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
     * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
     * @param d_robotModel holds XImats/topology (the inner loads s_XImats internally)
     * @param gravity is the gravity constant
     */
    template <typename T, bool SCRATCH_IN_SMEM = true, bool BC_IN_SMEM = true, bool TP_IN_SMEM = true>
    __device__
    void idsva_so_body_frame_inner(T *s_idsva_so, const T *s_q, const T *s_qd, T *s_qdd, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, const robotModel<T> *d_robotModel, const T gravity) {
        if constexpr (!SCRATCH_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
        load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
        // Relevant Tensors in the order they appear
        // d_workspace: at TIER_SHARED unused; at the surgical BC rung only BC repoints here;
        // at the whole-arena rung s_temp was already repointed to it above.
        T *I = s_XImats + XIMAT_SIZE*NUM_BODIES;
        T *Xup = s_temp + 11*XIMAT_SIZE*NUM_BODIES;
        T *IC = s_temp + XIMAT_SIZE*NUM_BODIES;
        T *Xdown = s_temp;

        T *S = IC + XIMAT_SIZE*NUM_BODIES;
        T *vJ = Xdown;
        T *v = vJ + 6*NUM_BODIES;
        T *Sd = v + 6*NUM_BODIES;
        T *aJ = Sd + 6*NUM_BODIES;
        T *a = aJ + 6*NUM_BODIES;
        T *psid = a + 6*NUM_BODIES;
        T *psidd = S + 6*NUM_BODIES;
        T *a_world = psidd + 6*NUM_BODIES;
        T *f = vJ;
        T *B_IC_S = S + 30*NUM_BODIES + 6;
        


        // Temporary Variables for Computations
        T *I_Xup = S;
        T *crm_v = B_IC_S + 36*NUM_BODIES;
        T *crf_v = crm_v + 36*NUM_BODIES;
        T *IC_v = aJ;
        T *crm_S = crm_v;
        T *crf_S = crf_v;
        T *IC_S = IC_v;
        T *crm_psid = crf_v + 36*NUM_BODIES;
        T *crf_psid = crm_psid + 36*NUM_BODIES;
        T *IC_psid = a;
        T *icrf_f = crf_psid + 36*NUM_BODIES;
        T *psid_Sd = v;
        T *ICT_S = f;
        


        // Main Temporary Tensors For Backward Pass
        T *T1 = IC_S;
        T *T2 = a_world + 6;
        T *T3 = T2 + 6*NUM_BODIES;
        T *T4 = T3 + 6*NUM_BODIES;
        T *D1 = icrf_f;
        T *D2 = D1 + 36*NUM_BODIES;
        T *D3 = B_IC_S;
        T *D4 = crf_psid;
        T *tp_anchor = D2 + 36*NUM_BODIES;
        T *t = tp_anchor;
        if constexpr (!TP_IN_SMEM) { t = d_workspace; }
        T *p1 = t;
        T *p2 = p1 + 6*146;
        T *p3 = p2 + 6*146;
        T *p4 = p3 + 6*146;
        T *p5 = p4 + 6*146;
        T *p6 = p5 + 6*146;
        T *crf_S_IC = crm_psid;
        T *BC = tp_anchor + (TP_IN_SMEM ? 36*146 : 0);
        


        // Final Tensors for Output
        T *d2tau_dq2 = s_idsva_so;
        T *d2tau_dqd2 = d2tau_dq2+ SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS;
        T *d2tau_dvdq = d2tau_dqd2 + SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS;
        T *dM_dq = d2tau_dvdq + SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS;
        if constexpr (!BC_IN_SMEM) { BC = d_workspace; }
        // Initialize output tensor; optimized assembly paths only write structurally nonzero entries.
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 4*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS; i += blockDim.x*blockDim.y){
            s_idsva_so[i] = static_cast<T>(0);
        }
        __syncthreads();
        

        // Compute Xup - parent to child transformation matrices
        // Compute Xup for bfs_level 0
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 108; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 0 + ((i) < 72 && (i) >= 36) * 6 + ((i) >= 72) * 12;
            int X_idx = jid*XIMAT_SIZE;
            Xup[X_idx + i % XIMAT_SIZE] = s_XImats[X_idx + i % XIMAT_SIZE]; // Parent is base
        }
        __syncthreads();
        // Compute Xup for bfs_level 1
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 108; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 1 + ((i) < 72 && (i) >= 36) * 7 + ((i) >= 72) * 13;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 2
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 108; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 2 + ((i) < 72 && (i) >= 36) * 8 + ((i) >= 72) * 14;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 3
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 144; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 3 + ((i) < 72 && (i) >= 36) * 9 + ((i) < 108 && (i) >= 72) * 15 + ((i) >= 108) * 22;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 4
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 144; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 4 + ((i) < 72 && (i) >= 36) * 10 + ((i) < 108 && (i) >= 72) * 16 + ((i) >= 108) * 23;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 5
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 144; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 5 + ((i) < 72 && (i) >= 36) * 11 + ((i) < 108 && (i) >= 72) * 17 + ((i) >= 108) * 24;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 6
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 72; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 18 + ((i) >= 36) * 25;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 7
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 72; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 19 + ((i) >= 36) * 26;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        // Compute Xup for bfs_level 8
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 72; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 20 + ((i) >= 36) * 27;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
