        __syncthreads();
        // Compute Xup for bfs_level 9
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 72; i += blockDim.x*blockDim.y){
            // non-branching pointer selector
            int jid = ((i) < 36) * 21 + ((i) >= 36) * 28;
            int X_idx = jid*XIMAT_SIZE;
            matmul<T>(i % 36, &Xup[s_topology_helpers[jid] * XIMAT_SIZE], &s_XImats[X_idx], &Xup[X_idx], XIMAT_SIZE, 0);
        }
        __syncthreads();
        


        // Compute IC - Centroidal Rigid Body Inertia
        // First I @ Xup
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < XIMAT_SIZE*NUM_BODIES; i += blockDim.x*blockDim.y){
            // All involved matrices are 6x6
            matmul<T>(i, Xup, I, I_Xup, 36, false);
        }
        __syncthreads();
        // Next Xup.T @ I
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < XIMAT_SIZE*NUM_BODIES; i += blockDim.x*blockDim.y){
            // All involved matrices are 6x6
            int mat_idx = (i / 36) * 36;
            matmul_trans<T>(i % 36, &Xup[mat_idx], &I_Xup[mat_idx], &IC[mat_idx], 'a');
        }
        __syncthreads();
        


        // Compute Xdown - child to parent transformation matrices
        for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < XIMAT_SIZE*NUM_BODIES; i += blockDim.x*blockDim.y){
            size_t idx = i % XIMAT_SIZE;
            size_t sub_idx = idx % 18;
            if (idx % 18 == 1 || idx % 18 == 4 || idx % 18 == 8 || idx % 18 == 11) {
                Xdown[i] = Xup[i+5];
                Xdown[i+5] = Xup[i];
            }
            else if (idx % 18 == 2 || idx % 18 == 5) {
                Xdown[i] = Xup[i+10];
                Xdown[i+10] = Xup[i];
            }
            else if (sub_idx != 6 && sub_idx != 9 && sub_idx != 13 && sub_idx != 16 &&
                        sub_idx != 12 && sub_idx != 15)
                Xdown[i] = Xup[i];
            }
            __syncthreads();
            


            // Transform S
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 6*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = i / 6;
                S[i] = (((s_topology_helpers[29 + jid]) > 0 ? 1 : -1)) * Xdown[jid*XIMAT_SIZE + ((s_topology_helpers[29 + jid]) > 0 ? (s_topology_helpers[29 + jid]) - 1 : -(s_topology_helpers[29 + jid]) - 1)*6 + (i % 6)];
            }
            __syncthreads();
            


            // Compute vJ = S @ qd & aJ = S @ qdd
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 2*6*NUM_BODIES; i += blockDim.x*blockDim.y){
                int joint = i / 6;
                if (joint < NUM_BODIES) vJ[i] = S[i] * s_qd[joint];
                else aJ[i - 6*NUM_BODIES] = S[i - 6*NUM_BODIES] * s_qdd[joint - NUM_BODIES];
            }
            __syncthreads();
            


            // Compute v = v[parent] + vJ
            // Compute v for bfs_level 0
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 0 + ((i) < 12 && (i) >= 6) * 6 + ((i) >= 12) * 12;
                int idx = i % 6;
                v[jid*6 + idx] = vJ[jid*6 + idx]; // Parent is base
            }
            __syncthreads();
            // Compute v for bfs_level 1
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 1 + ((i) < 12 && (i) >= 6) * 7 + ((i) >= 12) * 13;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 2
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 2 + ((i) < 12 && (i) >= 6) * 8 + ((i) >= 12) * 14;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 3
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 24; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 3 + ((i) < 12 && (i) >= 6) * 9 + ((i) < 18 && (i) >= 12) * 15 + ((i) >= 18) * 22;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 4
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 24; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 4 + ((i) < 12 && (i) >= 6) * 10 + ((i) < 18 && (i) >= 12) * 16 + ((i) >= 18) * 23;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 5
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 24; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 5 + ((i) < 12 && (i) >= 6) * 11 + ((i) < 18 && (i) >= 12) * 17 + ((i) >= 18) * 24;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 6
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 18 + ((i) >= 6) * 25;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 7
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 19 + ((i) >= 6) * 26;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 8
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 20 + ((i) >= 6) * 27;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute v for bfs_level 9
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 21 + ((i) >= 6) * 28;
                int idx = i % 6;
                v[jid*6 + idx] = v[s_topology_helpers[jid]*6 + idx] + vJ[jid*6 + idx];
            }
            __syncthreads();
            


            // Finish aJ += crm(v[parent])@vJ
            // For base, v[parent] = 0
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 6*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = i / 6;
                int index = i % 6;
                if (s_topology_helpers[jid] != -1) aJ[i] += crm_mul<T>(index, &v[s_topology_helpers[jid]*6], &vJ[jid*6]);
            }
            __syncthreads();
            


            // Compute Sd = crm(v) @ S & psid = crm(v[parent]) @ S
            // For base, v[parent] = 0
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 2*6*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = (i / 6) % NUM_BODIES;
                int index = i % 6;
                if (i < 6*NUM_BODIES) Sd[i] = crm_mul<T>(index, &v[jid*6], &S[jid*6]);
                else {
                    if (s_topology_helpers[jid] == -1) psid[jid*6 + index] = 0;
                    else psid[i - 6 * NUM_BODIES] = crm_mul<T>(index, &v[s_topology_helpers[jid]*6], &S[jid*6]);
                }
            }
            __syncthreads();
            


            // Compute a = a[parent] + aJ
            // Compute a for bfs_level 0
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 0 + ((i) < 12 && (i) >= 6) * 6 + ((i) >= 12) * 12;
                int idx = i % 6;
                a[jid*6+ idx] = aJ[jid*6 + idx] - gravity * (idx == 5); // Base joint's parent is the world
            }
            __syncthreads();
            // Compute a for bfs_level 1
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 1 + ((i) < 12 && (i) >= 6) * 7 + ((i) >= 12) * 13;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 2
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 18; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 2 + ((i) < 12 && (i) >= 6) * 8 + ((i) >= 12) * 14;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 3
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 24; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 3 + ((i) < 12 && (i) >= 6) * 9 + ((i) < 18 && (i) >= 12) * 15 + ((i) >= 18) * 22;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 4
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 24; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 4 + ((i) < 12 && (i) >= 6) * 10 + ((i) < 18 && (i) >= 12) * 16 + ((i) >= 18) * 23;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 5
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 24; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 5 + ((i) < 12 && (i) >= 6) * 11 + ((i) < 18 && (i) >= 12) * 17 + ((i) >= 18) * 24;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 6
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 18 + ((i) >= 6) * 25;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 7
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 19 + ((i) >= 6) * 26;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 8
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 20 + ((i) >= 6) * 27;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            // Compute a for bfs_level 9
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 12; i += blockDim.x*blockDim.y){
                // non-branching pointer selector
                int jid = ((i) < 6) * 21 + ((i) >= 6) * 28;
                int idx = i % 6;
                a[jid*6 + idx] = a[s_topology_helpers[jid]*6 + idx] + aJ[jid*6 + idx];
            }
            __syncthreads();
            


            // Initialize a_world
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 6; i += blockDim.x*blockDim.y){
                if (i < 5) a_world[i] = 0;
                else a_world[5] = -gravity; // a_base = gravity_vec[5] = -GRAVITY = +9.81 (gravity=-9.81)
            }
            __syncthreads();
            


            // Compute psidd = crm(a[parent])@S + crm(v[:,i])@psid[:,i] & IC @ v (for BC) in parallel
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 2*6*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = (i / 6) % NUM_BODIES;
                int index = i % 6;
                if (i < 6*NUM_BODIES) {
                    if (s_topology_helpers[jid] == -1) psidd[i] = crm_mul<T>(index, a_world, &S[jid*6]);
                    else psidd[i] = crm_mul<T>(index, &a[s_topology_helpers[jid]*6], &S[jid*6]) + crm_mul<T>(index, &v[s_topology_helpers[jid]*6], &psid[jid*6]);
                }
                else IC_v[i - 6*NUM_BODIES] = dot_prod<T, 6, 6, 1>(&IC[index + jid*36], &v[jid*6]);
            }
            __syncthreads();
            


            // Need crm(v), crf(v) for BC computation
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 2*36*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = (i / 36) % NUM_BODIES;
                int col = (i / 6) % 6;
                int row = i % 6;
                if (i < 36*NUM_BODIES) crm_v[i] = crm<T>(i % 36, &v[jid*6]);
                else crf_v[(jid*36) + row*6 + col] = -crm<T>(i % 36, &v[jid*6]); // crf is negative tranpose of crm
            }
            __syncthreads();
            


            // Finish BC = crf(v) @ IC + icrf(IC @ v) - IC @ crm(v)
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 36*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = i / 36;
                int row = i % 6;
                int col_idx = (i / 6) * 6;
                BC[i] = dot_prod<T, 6, 6, 1>(&crf_v[jid*36 + row], &IC[col_idx]) +
                        icrf<T>(i % 36, &IC_v[jid*6]) -
                        dot_prod<T, 6, 6, 1>(&IC[jid*36 + row], &crm_v[col_idx]);
            }
            __syncthreads();
            


            // Compute f = IC @ a + crf(v) @ IC @ v
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 6*NUM_BODIES; i += blockDim.x*blockDim.y){
                int jid = i / 6;
                int row = i % 6;
