            // Need crm(S), crf(S), IC@S, crm(psid), crf(psid), IC@psid for B computations & icrf(f), psid+Sd for T3,T4
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 5*36*NUM_BODIES + 3*6*NUM_BODIES; i += blockDim.x*blockDim.y){
