                int col = (i / 6) % 6;
                int row = i % 6;
                if (i < 36*NUM_BODIES) crm_S[i] = crm<T>(i % 36, &S[jid*6]);
                else if (i < 2*36*NUM_BODIES) crf_S[(jid*36) + row*6 + col] = -crm<T>(i % 36, &S[jid*6]); // crf is negative tranpose of crm
                else if (i < 3*36*NUM_BODIES) crm_psid[jid*36 + col*6 + row] = crm<T>(i % 36, &psid[jid*6]);
