                int st_j = st[index];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                if (i < 542 && jid != st_j) d2tau_dq2[jid*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + ancestor_j] += dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
                else if (jid != st_j) d2tau_dq2[jid*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + ancestor_j * SECOND_ORDER_COORDS + st_j] += dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
            }
            __syncthreads();
            


            // Compute t5 = outer(S[j], (Sd+psid)[ancestor])
            // t5[j][k] is stored at t[((j*(j+1)/2) + k)*36]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 146*36; i += blockDim.x*blockDim.y){
                int jid = jids[i / 36];
                int ancestor_j = ancestors_j[i / 36];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                outerProduct<T>(&S[jid*6], &psid_Sd[ancestor_j*6], &t[t_idx], 6, 6, i%36);
            }
            __syncthreads();
            


            // Perform all computations with t5
            // for child d2tau_dvdq[dd, cc, succ_j] += np.dot(t5, D1[:, succ_j])
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 542; i += blockDim.x*blockDim.y){
                int index = i % 542;
                int jid = jids_compute[index];
                int ancestor_j = ancestors_j_compute[index];
                int st_j = st[index];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                if (st_j != jid) d2tau_dvdq[jid*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + ancestor_j] += dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
            }
            __syncthreads();
            


            // Compute t6 = outer(S[ancestor], psid[joint])
            // t6[j][k] is stored at t[((j*(j+1)/2) + k)*36]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 146*36; i += blockDim.x*blockDim.y){
                int jid = jids[i / 36];
                int ancestor_j = ancestors_j[i / 36];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                outerProduct<T>(&S[ancestor_j*6], &psid[jid*6], &t[t_idx], 6, 6, i%36);
            }
            __syncthreads();
            


            // Perform all computations with t6
            // for ancestor d2tau_dvdq[st_j, cc, dd] = -np.dot(t6, D3[:, st_j])
            // for ancestor d2tau_dq[cc, st_j, dd] = np.dot(t6, D2[:, st_j])
            // for ancestor d2tau_dvdq[cc, st_j, dd] = np.dot(t6, D3[:, st_j])
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 1626; i += blockDim.x*blockDim.y){
                int index = i % 542;
                int jid = jids_compute[index];
                int ancestor_j = ancestors_j_compute[index];
                int st_j = st[index];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                if (ancestor_j < jid) {
                    if (i < 542) d2tau_dvdq[st_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + ancestor_j] = -dot_prod<T, 36, 1, 1>(&t[t_idx], &D3[st_j*36]);
                    else if (i < 1084) d2tau_dq2[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + st_j] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D2[st_j*36]);
                    else d2tau_dvdq[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + st_j] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D3[st_j*36]);
                }
            }
            __syncthreads();
            


            // Compute t7 = outer(S[ancestor], psidd[joint])
            // t7[j][k] is stored at t[((j*(j+1)/2) + k)*36]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 146*36; i += blockDim.x*blockDim.y){
                int jid = jids[i / 36];
                int ancestor_j = ancestors_j[i / 36];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                outerProduct<T>(&S[ancestor_j*6], &psidd[jid*6], &t[t_idx], 6, 6, i%36);
            }
            __syncthreads();
            


            // Perform all computations with t7
            // for ancestor d2tau_dq[cc, st_j, dd] += np.dot(t7, D1[:, st_j])
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 542; i += blockDim.x*blockDim.y){
                int index = i % 542;
                int jid = jids_compute[index];
                int ancestor_j = ancestors_j_compute[index];
                int st_j = st[index];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                if (ancestor_j < jid) d2tau_dq2[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + st_j] += dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
            }
            __syncthreads();
            


            // Compute t8 = outer(S[ancestor], S[joint])
            // t8[j][k] is stored at t[((j*(j+1)/2) + k)*36]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 146*36; i += blockDim.x*blockDim.y){
                int jid = jids[i / 36];
                int ancestor_j = ancestors_j[i / 36];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                outerProduct<T>(&S[ancestor_j*6], &S[jid*6], &t[t_idx], 6, 6, i%36);
            }
            __syncthreads();
            


            // Perform all computations with t8
            // for ancestor dM_dq[cc,st_j,dd] = t8.T @ D4[:, st_j]
            // for ancestor dM_dq[st_j,cc,dd] = t8.T @ D4[:, st_j]
            // for child dM_dq[cc, dd, succ_j] = np.dot(t8, D1[:, succ_j])
            // for child dM_dq[dd, cc, succ_j] = np.dot(t8, D1[:, succ_j])// for child & ancestor d2tau_dqd[cc, succ_j, dd] = np.dot(t8, D3[:, succ_j])
            // for child & ancestor d2tau_dqd[cc, dd, succ_j] = np.dot(t8, D3[:, succ_j])
