                int st_j = st[index];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                if (ancestor_j < jid) {
                    if (i < 542) dM_dq[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + jid] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D4[st_j*36]);
                    else if (i < 1084) dM_dq[st_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + ancestor_j * SECOND_ORDER_COORDS + jid] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D4[st_j*36]);
                    if (st_j != jid) {
                        if (i < 1626) d2tau_dqd2[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + st_j] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D3[st_j*36]);
                        else if (i < 2168) d2tau_dqd2[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + jid] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D3[st_j*36]);
                        else if (i < 2710) d2tau_dvdq[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + jid] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D2[st_j*36]);
                    }
                }
                if (jid != st_j && i < 3252) dM_dq[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + st_j] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
                else if (jid != st_j) dM_dq[jid*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + ancestor_j * SECOND_ORDER_COORDS + st_j] = dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
            }
            __syncthreads();
            


            // Compute t9 = outer(S[ancestor], (Sd+psid)[joint])
            // t9[j][k] is stored at t[((j*(j+1)/2) + k)*36]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 146*36; i += blockDim.x*blockDim.y){
                int jid = jids[i / 36];
                int ancestor_j = ancestors_j[i / 36];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                outerProduct<T>(&S[ancestor_j*6], &psid_Sd[jid*6], &t[t_idx], 6, 6, i%36);
            }
            __syncthreads();
            


            // Perform all computations with t9
            // for ancestor & child d2tau_dvdq[cc, dd, succ_j] += np.dot(t9, D1[:, succ_j])
            // for ancestor & child d2tau_dq[cc, dd, succ_j] = d2tau_dq[cc, succ_j, dd]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 1084; i += blockDim.x*blockDim.y){
                int index = i % 542;
                int jid = jids_compute[index];
                int ancestor_j = ancestors_j_compute[index];
                int st_j = st[index];
                int t_idx = t_index_map[jid][ancestor_j]*36;
                if (i < 542 && ancestor_j < jid && st_j != jid) d2tau_dvdq[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + jid] += dot_prod<T, 36, 1, 1>(&t[t_idx], &D1[st_j*36]);
                else if (ancestor_j < jid & st_j != jid) d2tau_dq2[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + st_j * SECOND_ORDER_COORDS + jid] = d2tau_dq2[ancestor_j*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS + jid * SECOND_ORDER_COORDS + st_j];
            }
            __syncthreads();
            


            // Compute p1..p6 in parallel
            // p1 = self.crm(psid_c) @ S_d
            // p2 = self.crm(psidd[:, k]) @ S_d
            // p3 = self.crm(S_c) @ S_d
            // p4 = self.crm(Sd_c + psid_c) @ S_d - 2 * self.crm(psid_d) @ S_c
            // p5 = self.crm(S_d) @ S_c
            // p6 = IC_S[joint] @ crm(S[ancestor]) + S[ancestor] @ crf_S_IC[joint]
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 5256; i += blockDim.x*blockDim.y){
                int index = i % 876;
                int jid = jids[index / 6];
                int ancestor_j = ancestors_j[index / 6];
                int p_idx = t_index_map[jid][ancestor_j]*6;
                if (i < 876) p1[p_idx + i % 6] = crm_mul<T>(i % 6, &psid[ancestor_j*6], &S[jid*6]);
                else if (i < 1752) p2[p_idx + i % 6] = crm_mul<T>(i % 6, &psidd[ancestor_j*6], &S[jid*6]);
                else if (i < 2628) p3[p_idx + i % 6] = crm_mul<T>(i % 6, &S[ancestor_j*6], &S[jid*6]);
                else if (i < 3504) p4[p_idx + i % 6] = crm_mul<T>(i % 6, &psid_Sd[ancestor_j*6], &S[jid*6]) - 2 * crm_mul<T>(i % 6, &psid[jid*6], &S[ancestor_j*6]);
                else if (i < 4380) p5[p_idx + i % 6] = crm_mul<T>(i % 6, &S[jid*6], &S[ancestor_j*6]);
                else p6[p_idx + i % 6] = dot_prod<T, 6, 1, 1>(&IC_S[jid*6], &crm_S[ancestor_j*36 + (i % 6)*6]) + dot_prod<T, 6, 1, 1>(&S[ancestor_j*6], &crf_S_IC[jid*36 + (i % 6)*6]);
            }
            __syncthreads();
            


            // Finish all computations with p1..p5
            // for joint d2tau_dq[st_j, dd, cc] += -np.dot(p1, T2[:, st_j]) + np.dot(p2, T1[:, st_j])
            // for ancestor d2tau_dq[st_j, cc, dd] += -np.dot(p1, T2[:, st_j]) + np.dot(p2, T1[:, st_j])
            // for ancestor d2tau_dvdq[st_j, cc, dd] += -np.dot(p3, T2[:, st_j]) + np.dot(p4, T1[:, st_j])
            // for ancestor d2tau_dq[cc, st_j, dd] -= np.dot(p5, T3[:, st_j])
            // for ancestor && child d2tau_dq[cc, dd, succ_j] -= np.dot(p5, T3[:, st_j])
