         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER>
        __host__
        void idsva_so_world_frame_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                           const dim3 block_dimms, const dim3 thread_dimms) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "idsva_so_world_frame requires all-data or dynamics gridData");
            int stride_q_qd = Q_QD_U_STRIDE;
            // then call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("idsva_so_world_frame", IDSVA_SO_WORLD_FRAME_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()));
            idsva_so_world_frame_kernel<T, RESOURCE_TIER><<<block_dimms,thread_dimms,IDSVA_SO_WORLD_FRAME_DYNAMIC_SHARED_MEM_BYTES<T, RESOURCE_TIER>()>>>(hd_data->d_idsva_so,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);
            gpuErrchkKernel();
        }

        /**
         * Computes the second order derivatives of inverse dynamics (frame picked at codegen time)
         *
         * Notes:
         *   Dispatches to world_frame_inner at codegen time (world for spherical).
         *   Inline-CUDA users: at TIER_LITE/TIER_MINIMAL the inner scratch moves from s_temp to d_workspace, freeing shared memory for the caller's outer kernel
         *
         * @param s_idsva_so is a pointer to memory for the final result of size 4*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS*SECOND_ORDER_COORDS = 97556
         * @param s_q is the vector of joint positions
         * @param s_qd is the vector of joint velocities
         * @param s_qdd is the vector of joint accelerations
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant
         * @param d_workspace is the global scratch buffer; size IDSVA_SO_DEVICE_INLINE_WORKSPACE_BYTES<T, RESOURCE_TIER>() bytes (= 0 at TIER_SHARED, 5886*sizeof(T) at TIER_LITE+). Pass nullptr at TIER_SHARED
         */
        template <typename T, int RESOURCE_TIER = TIER_SHARED>
        __device__
        void idsva_so_device(T *s_idsva_so, const T *s_q, const T *s_qd, const T *s_qdd, const robotModel<T> *d_robotModel, const T gravity, T *d_workspace = nullptr) {
            // GRID shared arena layout
            //   T s_XImats[2088]
            //   T s_temp[5886] (TIER_SHARED only; LITE/MINIMAL route to d_workspace)
            //   int s_topology_helpers[175]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            T *s_temp;
            if constexpr (RESOURCE_TIER == TIER_SHARED) {
                (void)d_workspace;
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(5886);
            }
            else {
                s_temp = d_workspace;
            }
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            if constexpr (RESOURCE_TIER == TIER_SHARED) {
                assert(s_arena_offset == grid_shared_arena_bytes<T>(7974, 175, 0));
            }
            else {
                assert(s_arena_offset == grid_shared_arena_bytes<T>(2088, 175, 0));
            }
            #endif
            (void)s_arena_offset;
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            T *d_temp_spill = nullptr; (void)d_temp_spill;
            idsva_so_world_frame_inner<T, true, true>(s_idsva_so, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_temp_spill, d_robotModel, gravity);
        }

        /**
         * Dispatching IDSVA-SO wrapper (forwards to world_frame at codegen time)
         *
         * Notes:
         *   Body wins ~30x on fixed-base; world wins 2-4x on floating-base. Same numbers either way.
         *
         * @param hd_data is the packaged input and output pointers
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         * @param streams are pointers to CUDA streams for async memory transfers (if needed)
         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL>
        __host__
        void idsva_so(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                              const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
            idsva_so_world_frame<T, KIND>(hd_data, d_robotModel, gravity, num_timesteps, block_dimms, thread_dimms, streams);
        }

        /**
         * Dispatching IDSVA-SO wrapper (forwards to world_frame at codegen time)
         *
         * Notes:
         *   Body wins ~30x on fixed-base; world wins 2-4x on floating-base. Same numbers either way.
         *
         * @param hd_data is the packaged input and output pointers
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         * @param streams are pointers to CUDA streams for async memory transfers (if needed)
         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL>
        __host__
        void idsva_so_single_timing(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                            const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
            static_assert(KIND == GRID_DATA_ALL || KIND == GRID_DATA_DYNAMICS, "idsva_so requires all-data or dynamics gridData");
            int stride_q_qd = Q_QD_U_STRIDE;
            // start code with memory transfer
            gpuErrchk(cudaMemcpyAsync(hd_data->d_q_qd_u,hd_data->h_q_qd_u,stride_q_qd*sizeof(T),cudaMemcpyHostToDevice,streams[0]));
            gpuErrchkKernel();
            // then call the kernel
            gpuErrchk(grid_check_dynamic_shared_memory_bytes("idsva_so", IDSVA_SO_WORLD_FRAME_DYNAMIC_SHARED_MEM_BYTES<T>()));
            struct timespec start, end; clock_gettime(CLOCK_MONOTONIC,&start);
            idsva_so_world_frame_kernel_single_timing<T><<<block_dimms,thread_dimms,IDSVA_SO_WORLD_FRAME_DYNAMIC_SHARED_MEM_BYTES<T>()>>>(hd_data->d_idsva_so,hd_data->d_workspace,hd_data->d_q_qd_u,stride_q_qd,d_robotModel,gravity,num_timesteps);
            gpuErrchkKernel();
            clock_gettime(CLOCK_MONOTONIC,&end);
            // finally transfer the result back
            gpuErrchk(cudaMemcpy(hd_data->h_idsva_so,hd_data->d_idsva_so,SECOND_ORDER_TENSOR_SIZE*sizeof(T),cudaMemcpyDeviceToHost));
            gpuErrchkKernel();
            printf("Single Call IDSVA_SO %fus\n",time_delta_us_timespec(start,end)/static_cast<double>(num_timesteps));
        }

        /**
         * Dispatching IDSVA-SO wrapper (forwards to world_frame at codegen time)
         *
         * Notes:
         *   Body wins ~30x on fixed-base; world wins 2-4x on floating-base. Same numbers either way.
         *
         * @param hd_data is the packaged input and output pointers
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         * @param streams are pointers to CUDA streams for async memory transfers (if needed)
         */
        template <typename T, gridDataKind KIND = GRID_DATA_ALL>
        __host__
        void idsva_so_compute_only(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                                           const dim3 block_dimms, const dim3 thread_dimms) {
            idsva_so_world_frame_compute_only<T, KIND>(hd_data, d_robotModel, gravity, num_timesteps, block_dimms, thread_dimms);
        }

        /**
         * Second Order of Forward Dynamics with Spatial Vector Algebra
         *
         * Notes:
         *   Assumes works with IDSVA
         *   Inline-CUDA users: SCRATCH_IN_SMEM selects where the 4*NV^3 scratch arena lives.
         *     true  -> s_temp (shared memory; fastest, current default).
         *     false -> d_workspace (global; frees shared memory for the caller's outer kernel).
         *   The placement is the INNER's choice (made at the top of this function) so the
         *   kernel/device caller just sizes both arenas from the exposed *_BYTES constants
         *   and hands both pointers in. Codegen maps each RESOURCE_TIER to a SCRATCH_IN_SMEM
         *   value per robot (small robots keep all tiers in smem; large robots spill).
         *
         * @param s_df2 are the second derivatives of forward dynamics WRT q,qd,tau
         * @param s_idsva_so are the second derivative tensors of inverse dynamics
         * @param s_Minv is the inverse mass matrix
         * @param s_df_du is the gradient of the forward dynamics
         * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
         * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
         * @param s_temp is the (shared) scratch buffer; size FDSVA_SO_INNER_SMEM_BYTES<T, SCRATCH_IN_SMEM>() bytes (= 97556*sizeof(T) when SCRATCH_IN_SMEM, else 0)
         * @param d_workspace is the global scratch buffer; size FDSVA_SO_INNER_WORKSPACE_BYTES<T, SCRATCH_IN_SMEM>() bytes (= 97556*sizeof(T) when !SCRATCH_IN_SMEM, else 0). Pass nullptr when SCRATCH_IN_SMEM
         * @param gravity is the gravity constant
         */
        template <typename T, bool SCRATCH_IN_SMEM = true>
        __device__
        void fdsva_so_contract(T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, const T gravity) {
            // Second Derivatives of Inverse Dynamics
            T *d2tau_dqdq = &s_idsva_so[0];
            T *d2tau_dvdv = &s_idsva_so[24389];
            T *d2tau_dvdq = &s_idsva_so[48778];
            T *dM_dq = &s_idsva_so[73167];
            


            // First Derivatives of Forward Dynamics
            T *s_df_dq = s_df_du; T *s_df_dqd = &s_df_du[841];
            


            // Second Derivatives of Forward Dynamics
            T *d2a_dqdq = s_df2;
            T *d2a_dvdq = &s_df2[24389];
            T *d2a_dvdv = &s_df2[48778];
            T *d2a_dtdq = &s_df2[73167];
            


            // Temporary Variables. The 4*n^3 scratch arena placement is the INNER's
            // choice, keyed on SCRATCH_IN_SMEM: s_temp (shared) when true, d_workspace
            // (global) when false. A surgical-spill change is local here: repoint a
            // sub-buffer + update FDSVA_SO_INNER_{SMEM,WORKSPACE}_BYTES.
            T *inner_arena;
            if constexpr (SCRATCH_IN_SMEM) {
                (void)d_workspace;
                inner_arena = s_temp;
            }
            else {
                (void)s_temp;
                inner_arena = d_workspace;
            }
            T *inner_dq = inner_arena; // Inner term for d2a_dqdq
            T *inner_cross = inner_dq + 24389; // Inner term for d2a_dvdq (dM_dq*Minv)
            T *inner_tau = inner_cross + 24389; // Inner term for d2a_dtdq (d2tau_dvdq + dM_dq*da_dv)
            T *rot_dq = inner_tau + 24389; // Rotated (dM_dq*da_dq)^R term used to compute inner_dq
            


            // Start inner term for d2a_dqdq & Fill out Minv
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 25230; ind += blockDim.x*blockDim.y){
                int i = ind / 841 % 29; int j = ind / 29 % 29; int k = ind % 29;
                if (ind < 24389) {
                    inner_dq[ind] = dot_prod<T, 29, 29, 1>(&dM_dq[841*i + k], &s_df_dq[29*j]);
                    rot_dq[i*841 + k*29 + j] = inner_dq[ind];
                }
                else if (k > j) s_Minv[j*29 + k] = s_Minv[k*29 + j];
            }
            __syncthreads();
            // Compute relevant inner subterms in parallel
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 73167; ind += blockDim.x*blockDim.y){
                int i = ind / 841 % 29; int j = ind / 29 % 29; int k = ind % 29;
                if (ind < 24389) inner_dq[ind] += rot_dq[ind] + d2tau_dqdq[ind]; // Started with dM_dq*da_dq
                else if (ind < 48778) inner_cross[i*841 + k*29 + j] = dot_prod<T, 29, 29, 1>(&dM_dq[841*i + k], &s_df_dqd[29*j]) + d2tau_dvdq[i*841 + j*29 + k];
                else inner_tau[i*841 + k*29 + j] = dot_prod<T, 29, 29, 1>(&dM_dq[841*i + k], &s_Minv[29*j]);
            }
            __syncthreads();
            // Multiply by -Minv to finish algorithm
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 97556; ind += blockDim.x*blockDim.y){
                int i = ind / 841 % 29; int j = ind / 29 % 29; int k = ind % 29;
                if (ind < 24389) d2a_dqdq[i*841 + j*29 + k] = -dot_prod<T, 29, 29, 841>(&s_Minv[i], &inner_dq[j + k*29]);
                else if (ind < 48778) d2a_dvdq[i*841 + j*29 + k] = -dot_prod<T, 29, 29, 841>(&s_Minv[i], &inner_cross[j + k*29]);
                else if (ind < 73167) d2a_dvdv[i*841 + j*29 + k] = -dot_prod<T, 29, 29, 841>(&s_Minv[i], &d2tau_dvdv[j + k*29]);
                else d2a_dtdq[i*841 + j*29 + k] = -dot_prod<T, 29, 29, 841>(&s_Minv[i], &inner_tau[j + k*29]);
            }
            __syncthreads();
        }

        /**
         * fdsva_so orchestration as a single inner-owns-placement device function
         *
         * @param s_df2/s_idsva_so/s_Minv/s_df_du/s_qdd/s_q/s_qd/s_u are the in/out buffers (caller places)
         * @param s_temp is the shared scratch pool (used when SCRATCH_IN_SMEM)
         * @param d_workspace is the global scratch pool (used when !SCRATCH_IN_SMEM)
         * @param d_fd_grad_spill is the fd-gradient da_df spill band (used when FD_GRAD_USE_SPILL)
         * @param s_fdsva_temp is the 4*NV^3 contraction scratch (smem or workspace per CONTRACT_IN_SMEM)
         * @param s_XImats is the (shared) memory holding the updated XI matricies for the given s_q
         * @param s_topology_helpers is the (shared) memory location for the topology_helpers (nullptr/unused for serial chains with identical Ss)
         * @param d_robotModel holds XImats/topology; gravity is the gravity constant
         * @param d_idsva_cold_spill is the SO-temp d_workspace region backing the WORLD idsva_so inner's cold trio (only read when !IDSVA_COLD_IN_SMEM)
         */
        template <typename T, bool SCRATCH_IN_SMEM = true, bool FD_GRAD_USE_SPILL = false, bool CONTRACT_IN_SMEM = true, bool IDSVA_COLD_IN_SMEM = true>
        __device__ __forceinline__
        void fdsva_so_device(T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_qdd, const T *s_q, const T *s_qd, const T *s_u, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_fd_grad_spill, T *s_fdsva_temp, const robotModel<T> *d_robotModel, const T gravity, T *d_idsva_cold_spill = nullptr) {
            if constexpr (!SCRATCH_IN_SMEM) { s_temp = d_workspace; } else { (void)d_workspace; }
            T *d_temp_spill = nullptr;
            if constexpr (!IDSVA_COLD_IN_SMEM) { d_temp_spill = d_idsva_cold_spill; } else { (void)d_idsva_cold_spill; }
            load_update_XImats_helpers<T>(s_XImats, s_q, s_topology_helpers, d_robotModel, s_temp);
            minv_inner<T, true>(s_Minv, s_q, s_XImats, s_topology_helpers, s_temp, nullptr);
            forward_dynamics_inner<T, true>(s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, gravity);
            __syncthreads();
            if constexpr (FD_GRAD_USE_SPILL) {
                // Compute FD gradient inline so nested device wrappers do not carve a second shared arena
                T *s_fd_vaf = s_temp;
                T *s_fd_dc_du = s_fd_vaf + 522;
                T *s_fd_temp = s_fd_dc_du + 1682;
                inverse_dynamics_inner_vaf<T>(s_fd_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_fd_temp, nullptr, gravity);
                inverse_dynamics_gradient_inner<T, true>(s_fd_dc_du, s_q, s_qd, s_fd_vaf, s_XImats, s_topology_helpers, s_fd_temp, d_fd_grad_spill, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1682; ind += blockDim.x*blockDim.y){
                    int row = ind % 29; int dc_col_offset = ind - row;
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 29; col++) {
                        int index = (row <= col) * (col * 29 + row) + (row > col) * (row * 29 + col);
                        val += s_Minv[index] * s_fd_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
            }
            else {
                (void)d_fd_grad_spill;
                // Compute FD gradient inline so nested device wrappers do not carve a second shared arena
                T *s_fd_vaf = s_temp;
                T *s_fd_dc_du = s_fd_vaf + 522;
                T *s_fd_temp = s_fd_dc_du + 1682;
                inverse_dynamics_inner_vaf<T>(s_fd_vaf, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_fd_temp, nullptr, gravity);
                inverse_dynamics_gradient_inner<T, false>(s_fd_dc_du, s_q, s_qd, s_fd_vaf, s_XImats, s_topology_helpers, s_fd_temp, nullptr, gravity);
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 1682; ind += blockDim.x*blockDim.y){
                    int row = ind % 29; int dc_col_offset = ind - row;
                    T val = static_cast<T>(0);
                    for(int col = 0; col < 29; col++) {
                        int index = (row <= col) * (col * 29 + row) + (row > col) * (row * 29 + col);
                        val += s_Minv[index] * s_fd_dc_du[dc_col_offset + col];
                    }
                    s_df_du[ind] = -val;
                }
                __syncthreads();
            }
            idsva_so_body_frame_inner<T>(s_idsva_so, s_q, s_qd, s_qdd, s_XImats, s_topology_helpers, s_temp, d_temp_spill, d_robotModel, gravity);
            fdsva_so_contract<T, CONTRACT_IN_SMEM>(s_df2, s_idsva_so, s_Minv, s_df_du, s_XImats, s_topology_helpers, s_temp, s_fdsva_temp, gravity);
        }

        /**
         * Compute the FDSVA_SO (Second Order of Forward Dynamics with Spacial Vector Algebra)
         *
         * @param d_df2 is the second derivatives of forward dynamics WRT q,qd,tau
         * @param d_workspace is the generated global spill workspace
         * @param d_q_qd_u is the vector of joint positions, velocities, torques
         * @param stride_q_qd_u is the stride between each q, qd, qdd
         * @param d_idsva_so is the pointer to the idsva_so output tensor in global memory
         * @param d_robotModel is the pointer to the initialized model specific helpers on the GPU (XImats, topology_helpers, etc.)
         * @param gravity is the gravity constant
         * @param num_timesteps is the length of the trajectory points we need to compute over (or overloaded as test_iters for timing)
         */
        template <typename T, int RESOURCE_TIER = GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
        __global__
        __launch_bounds__(tier_max_threads<RESOURCE_TIER>())
        void fdsva_so_kernel_single_timing(T *d_df2, unsigned char *d_workspace, const T *d_q_qd_u, const int stride_q_qd_u, T *d_idsva_so, const robotModel<T> *d_robotModel, const T gravity, const int NUM_TIMESTEPS) {
            if constexpr (RESOURCE_TIER == TIER_SHARED) {
                // GRID shared arena layout
                //   T s_q_qd_u[87]
                //   T s_qdd[29]
                //   T s_Minv[841]
                //   T s_df_du[1682]
                //   T s_XImats[2088]
                //   T s_temp[16572]
                //   int s_topology_helpers[175]
                extern __shared__ __align__(16) unsigned char s_arena[];
                size_t s_arena_offset = 0;
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_q_qd_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(87);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(29);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(841);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(1682);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(16572);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
                int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(int) * static_cast<size_t>(175);
                #ifdef GRID_CUDA_DEBUG_LAYOUT
                assert(s_arena_offset == grid_shared_arena_bytes<T>(21299, 175, 0));
                #endif
                (void)s_arena_offset;
                T *s_q = s_q_qd_u; T *s_qd = &s_q_qd_u[29]; T *s_u = &s_q_qd_u[58];
                T *d_temp_spill = nullptr; (void)d_temp_spill;
