                    else if (flat % 18 == 2 || flat % 18 == 5) { Xdn[flat] = Xup[flat + 10]; Xdn[flat + 10] = Xup[flat]; }
                    else if (sub_idx != 6 && sub_idx != 9 && sub_idx != 13 && sub_idx != 16 && sub_idx != 12 && sub_idx != 15) { Xdn[flat] = Xup[flat]; }
