                        for (int row = 0; row < 6; ++row) {
                            T a = static_cast<T>(0);
                            for (int kk = 0; kk < 6; ++kk) a += s_oYc[jid*36 + row + 6*kk]*s_dJ[c*6 + kk] + s_Bc[jid*36 + row + 6*kk]*s_Sw[c*6 + kk];
