                int rrow = cor_col_true_vel[ic]; int ccol = cor_col_true_vel[tc];
                T coeff = cor_col_alpha[ic] * cor_col_alpha[tc];
                T val;
                if (kind == 0) {
                    // subtree: Sw[ic]^T dFdv[tc]
                    val = static_cast<T>(0); for (int r = 0; r < 6; ++r) val += s_Sw[ic*6 + r]*s_dFdv[tc*6 + r];
                }
