        __host__
        void all_dynamics(gridData<T, KIND> *hd_data, const robotModel<T> *d_robotModel, const T gravity, const int num_timesteps,
                           const dim3 block_dimms, const dim3 thread_dimms, cudaStream_t *streams) {
