    /**
     * Plant namespace: cost / constraint / plant-step primitives composed over grid::
     *
     */
    namespace grid_plant {
        /**
         * quadratic_state_cost: value = 1/2 * sum_i s_Q[i] * (s_x[i] - s_x_des[i])^2
         *
         * Notes:
         *   Block-cooperative: each thread accumulates its strided terms into s_scratch, then a serial reduction writes s_out[0].
         *   ACCUMULATE=false overwrites s_out[0]; ACCUMULATE=true ADDS into it (for summing cost terms into one scalar).
         *   s_scratch must hold at least 58 elements.
         *
         * @param s_out is the scalar cost output (s_out[0])
         * @param s_x is the current value (size NUM_POS + NUM_VEL = 58)
         * @param s_x_des is the desired/target value (size NUM_POS + NUM_VEL = 58)
         * @param s_Q is the diagonal weight vector (size NUM_POS + NUM_VEL = 58)
         * @param s_scratch is shared scratch of size >= 58
         */
        template <typename T, bool ACCUMULATE = false>
        __device__
        void quadratic_state_cost(T *s_out, const T *s_x, const T *s_x_des, const T *s_Q, T *s_scratch) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 58; i += blockDim.x*blockDim.y){
                T r = s_x[i] - s_x_des[i];
                s_scratch[i] = static_cast<T>(0.5) * s_Q[i] * r * r;
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                for (int i = 0; i < 58; ++i) acc += s_scratch[i];
                if (ACCUMULATE) { s_out[0] += acc; } else { s_out[0] = acc; }
            }
        }

        /**
         * quadratic_state_cost_gradient: g[i] = s_Q[i] * (s_x[i] - s_x_des[i])
         *
         * Notes:
         *   ACCUMULATE=false overwrites s_grad; ACCUMULATE=true adds into it (for fusing into a packed [x;u] gradient).
         *
         * @param s_grad is the gradient output (size NUM_POS + NUM_VEL = 58)
         * @param s_x / s_x_des / s_Q as in the value function
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void quadratic_state_cost_gradient(T *s_grad, const T *s_x, const T *s_x_des, const T *s_Q) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 58; i += blockDim.x*blockDim.y){
                T g = s_Q[i] * (s_x[i] - s_x_des[i]);
                if (ACCUMULATE) { s_grad[i] += g; } else { s_grad[i] = g; }
            }
        }

        /**
         * quadratic_state_cost_hessian: Gauss-Newton hessian = diag(s_Q) (RATIFIED: GN outer product; for a quadratic cost this is exactly diag(W))
         *
         * Notes:
         *   Writes a dense column-major 58 x 58 matrix; off-diagonal entries are zero.
         *   ACCUMULATE=false overwrites; ACCUMULATE=true adds into the diagonal of an existing block.
         *
         * @param s_hess is the dense hessian output (size 58*58, column-major)
         * @param s_Q is the diagonal weight vector (size NUM_POS + NUM_VEL = 58)
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void quadratic_state_cost_hessian(T *s_hess, const T *s_Q) {
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3364; ind += blockDim.x*blockDim.y){
                int row = ind % 58;
                int col = ind / 58;
                T h = (row == col) ? s_Q[row] : static_cast<T>(0);
                if (ACCUMULATE) { s_hess[ind] += h; } else { s_hess[ind] = h; }
            }
        }

        /**
         * quadratic_state_cost_value_grad_hess: fused value + gradient + GN-diag hessian in one pass
         *
         * Notes:
         *   Convenience fusion of the three functions above; same conventions and ACCUMULATE semantics for grad/hess.
         *
         * @param s_out / s_grad / s_hess are the three outputs
         * @param s_x / s_x_des / s_Q / s_scratch as above
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void quadratic_state_cost_value_grad_hess(T *s_out, T *s_grad, T *s_hess, const T *s_x, const T *s_x_des, const T *s_Q, T *s_scratch) {
            quadratic_state_cost<T>(s_out, s_x, s_x_des, s_Q, s_scratch);
            quadratic_state_cost_gradient<T, ACCUMULATE>(s_grad, s_x, s_x_des, s_Q);
            quadratic_state_cost_hessian<T, ACCUMULATE>(s_hess, s_Q);
        }

        /**
         * quadratic_input_cost: value = 1/2 * sum_i s_R[i] * (s_u[i] - s_u_des[i])^2
         *
         * Notes:
         *   Block-cooperative: each thread accumulates its strided terms into s_scratch, then a serial reduction writes s_out[0].
         *   ACCUMULATE=false overwrites s_out[0]; ACCUMULATE=true ADDS into it (for summing cost terms into one scalar).
         *   s_scratch must hold at least 29 elements.
         *
         * @param s_out is the scalar cost output (s_out[0])
         * @param s_u is the current value (size NUM_VEL = 29)
         * @param s_u_des is the desired/target value (size NUM_VEL = 29)
         * @param s_R is the diagonal weight vector (size NUM_VEL = 29)
         * @param s_scratch is shared scratch of size >= 29
         */
        template <typename T, bool ACCUMULATE = false>
        __device__
        void quadratic_input_cost(T *s_out, const T *s_u, const T *s_u_des, const T *s_R, T *s_scratch) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                T r = s_u[i] - s_u_des[i];
                s_scratch[i] = static_cast<T>(0.5) * s_R[i] * r * r;
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                for (int i = 0; i < 29; ++i) acc += s_scratch[i];
                if (ACCUMULATE) { s_out[0] += acc; } else { s_out[0] = acc; }
            }
        }

        /**
         * quadratic_input_cost_gradient: g[i] = s_R[i] * (s_u[i] - s_u_des[i])
         *
         * Notes:
         *   ACCUMULATE=false overwrites s_grad; ACCUMULATE=true adds into it (for fusing into a packed [x;u] gradient).
         *
         * @param s_grad is the gradient output (size NUM_VEL = 29)
         * @param s_u / s_u_des / s_R as in the value function
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void quadratic_input_cost_gradient(T *s_grad, const T *s_u, const T *s_u_des, const T *s_R) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                T g = s_R[i] * (s_u[i] - s_u_des[i]);
                if (ACCUMULATE) { s_grad[i] += g; } else { s_grad[i] = g; }
            }
        }

        /**
         * quadratic_input_cost_hessian: Gauss-Newton hessian = diag(s_R) (RATIFIED: GN outer product; for a quadratic cost this is exactly diag(W))
         *
         * Notes:
         *   Writes a dense column-major 29 x 29 matrix; off-diagonal entries are zero.
         *   ACCUMULATE=false overwrites; ACCUMULATE=true adds into the diagonal of an existing block.
         *
         * @param s_hess is the dense hessian output (size 29*29, column-major)
         * @param s_R is the diagonal weight vector (size NUM_VEL = 29)
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void quadratic_input_cost_hessian(T *s_hess, const T *s_R) {
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 841; ind += blockDim.x*blockDim.y){
                int row = ind % 29;
                int col = ind / 29;
                T h = (row == col) ? s_R[row] : static_cast<T>(0);
                if (ACCUMULATE) { s_hess[ind] += h; } else { s_hess[ind] = h; }
            }
        }

        /**
         * quadratic_input_cost_value_grad_hess: fused value + gradient + GN-diag hessian in one pass
         *
         * Notes:
         *   Convenience fusion of the three functions above; same conventions and ACCUMULATE semantics for grad/hess.
         *
         * @param s_out / s_grad / s_hess are the three outputs
         * @param s_u / s_u_des / s_R / s_scratch as above
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void quadratic_input_cost_value_grad_hess(T *s_out, T *s_grad, T *s_hess, const T *s_u, const T *s_u_des, const T *s_R, T *s_scratch) {
            quadratic_input_cost<T>(s_out, s_u, s_u_des, s_R, s_scratch);
            quadratic_input_cost_gradient<T, ACCUMULATE>(s_grad, s_u, s_u_des, s_R);
            quadratic_input_cost_hessian<T, ACCUMULATE>(s_hess, s_R);
        }

        /**
         * Scalar log-barrier helpers: b = -mu*(log(x-lo)+log(hi-x)); isfinite-guarded so an inf bound contributes zero
         *
         * Notes:
         *   Margin floored at 1e-10 (value) / 1e-6 (grad,hess) to stay finite at the boundary.
         *
         */
        template <typename T> __device__ inline T grid_plant_log_barrier(T x, T lo, T hi, T mu) {
            T b = static_cast<T>(0);
            if (isfinite(lo)) { T d = x - lo; d = (d <= static_cast<T>(1e-10)) ? static_cast<T>(1e-10) : d; b -= log(d); }
            if (isfinite(hi)) { T d = hi - x; d = (d <= static_cast<T>(1e-10)) ? static_cast<T>(1e-10) : d; b -= log(d); }
            return mu * b;
        }
        
        template <typename T> __device__ inline T grid_plant_log_barrier_grad(T x, T lo, T hi, T mu) {
            T g = static_cast<T>(0);
            const T eps = static_cast<T>(1e-6);
            if (isfinite(lo)) { T d = x - lo; T a = (d < static_cast<T>(0)) ? -d : d; if (a < eps) a = eps; d = (d < static_cast<T>(0)) ? -a : a; g -= static_cast<T>(1) / d; }
            if (isfinite(hi)) { T d = hi - x; T a = (d < static_cast<T>(0)) ? -d : d; if (a < eps) a = eps; d = (d < static_cast<T>(0)) ? -a : a; g += static_cast<T>(1) / d; }
            return mu * g;
        }
        
        template <typename T> __device__ inline T grid_plant_log_barrier_hess(T x, T lo, T hi, T mu) {
            T h = static_cast<T>(0);
            const T eps = static_cast<T>(1e-6);
            if (isfinite(lo)) { T d = x - lo; T a = (d < static_cast<T>(0)) ? -d : d; if (a < eps) a = eps; h += static_cast<T>(1) / (a * a); }
            if (isfinite(hi)) { T d = hi - x; T a = (d < static_cast<T>(0)) ? -d : d; if (a < eps) a = eps; h += static_cast<T>(1) / (a * a); }
            return mu * h;
        }
        
        /**
         * joint_position_barrier: value += -mu * sum_i ( log(x_i - lo_i) + log(hi_i - x_i) ) over the NUM_POS q-DOFs
         *
         * Notes:
         *   Block-cooperative reduction into s_scratch then a serial add into s_out[0].
         *   s_lower / s_upper are explicit bound vectors (size 29); an inf entry skips that side (isfinite guard).
         *   s_scratch must hold at least 29 elements.
         *
         * @param s_out is the scalar barrier cost (added into s_out[0])
         * @param s_var is the variable vector (this barrier reads s_var[0 + i])
         * @param s_lower / s_upper are the per-DOF bounds (size 29)
         * @param mu is the barrier weight
         * @param s_scratch is shared scratch of size >= 29
         */
        template <typename T>
        __device__
        void joint_position_barrier(T *s_out, const T *s_var, const T *s_lower, const T *s_upper, const T mu, T *s_scratch) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                s_scratch[i] = grid_plant_log_barrier<T>(s_var[0 + i], s_lower[i], s_upper[i], mu);
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                for (int i = 0; i < 29; ++i) acc += s_scratch[i];
                s_out[0] += acc;
            }
        }

        /**
         * joint_position_barrier_gradient: s_grad[GRAD_OFFSET + i] += -mu*(1/(x_i-lo_i) - 1/(hi_i-x_i))
         *
         * Notes:
         *   Adds into the packed gradient at GRAD_OFFSET (a template arg so velocity/torque barriers land in the qd / u rows).
         *   isfinite-guarded per side; an unbounded DOF adds exactly zero.
         *
         * @param s_grad is the packed gradient output (added into)
         * @param s_var / s_lower / s_upper / mu as in the value function
         */
        template <typename T, int VAR_OFFSET = 0, int GRAD_OFFSET = 0>
        __device__
        void joint_position_barrier_gradient(T *s_grad, const T *s_var, const T *s_lower, const T *s_upper, const T mu) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                s_grad[GRAD_OFFSET + i] += grid_plant_log_barrier_grad<T>(s_var[VAR_OFFSET + i], s_lower[i], s_upper[i], mu);
            }
        }

        /**
         * joint_position_barrier_hessian: s_hess[(HESS_OFFSET+i)*HESS_STRIDE + (HESS_OFFSET+i)] += mu*(1/(x_i-lo_i)^2 + 1/(hi_i-x_i)^2)
         *
         * Notes:
         *   Adds the barrier curvature onto the DIAGONAL of a dense column-major HESS_STRIDE x HESS_STRIDE block.
         *   HESS_OFFSET places it in the qd / u block; HESS_STRIDE is the block leading dimension.
         *   isfinite-guarded per side; an unbounded DOF adds exactly zero.
         *
         * @param s_hess is the dense column-major hessian (added into)
         * @param s_var / s_lower / s_upper / mu as above
         */
        template <typename T, int HESS_STRIDE, int VAR_OFFSET = 0, int HESS_OFFSET = 0>
        __device__
        void joint_position_barrier_hessian(T *s_hess, const T *s_var, const T *s_lower, const T *s_upper, const T mu) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                int d = HESS_OFFSET + i;
                s_hess[d * HESS_STRIDE + d] += grid_plant_log_barrier_hess<T>(s_var[VAR_OFFSET + i], s_lower[i], s_upper[i], mu);
            }
        }

        /**
         * joint_velocity_barrier: value += -mu * sum_i ( log(x_i - lo_i) + log(hi_i - x_i) ) over the NUM_VEL qd-DOFs
         *
         * Notes:
         *   Block-cooperative reduction into s_scratch then a serial add into s_out[0].
         *   s_lower / s_upper are explicit bound vectors (size 29); an inf entry skips that side (isfinite guard).
         *   s_scratch must hold at least 29 elements.
         *
         * @param s_out is the scalar barrier cost (added into s_out[0])
         * @param s_var is the variable vector (this barrier reads s_var[29 + i])
         * @param s_lower / s_upper are the per-DOF bounds (size 29)
         * @param mu is the barrier weight
         * @param s_scratch is shared scratch of size >= 29
         */
        template <typename T>
        __device__
        void joint_velocity_barrier(T *s_out, const T *s_var, const T *s_lower, const T *s_upper, const T mu, T *s_scratch) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                s_scratch[i] = grid_plant_log_barrier<T>(s_var[29 + i], s_lower[i], s_upper[i], mu);
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                for (int i = 0; i < 29; ++i) acc += s_scratch[i];
                s_out[0] += acc;
            }
        }

        /**
         * joint_velocity_barrier_gradient: s_grad[GRAD_OFFSET + i] += -mu*(1/(x_i-lo_i) - 1/(hi_i-x_i))
         *
         * Notes:
         *   Adds into the packed gradient at GRAD_OFFSET (a template arg so velocity/torque barriers land in the qd / u rows).
         *   isfinite-guarded per side; an unbounded DOF adds exactly zero.
         *
         * @param s_grad is the packed gradient output (added into)
         * @param s_var / s_lower / s_upper / mu as in the value function
         */
        template <typename T, int VAR_OFFSET = 29, int GRAD_OFFSET = 0>
        __device__
        void joint_velocity_barrier_gradient(T *s_grad, const T *s_var, const T *s_lower, const T *s_upper, const T mu) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                s_grad[GRAD_OFFSET + i] += grid_plant_log_barrier_grad<T>(s_var[VAR_OFFSET + i], s_lower[i], s_upper[i], mu);
            }
        }

        /**
         * joint_velocity_barrier_hessian: s_hess[(HESS_OFFSET+i)*HESS_STRIDE + (HESS_OFFSET+i)] += mu*(1/(x_i-lo_i)^2 + 1/(hi_i-x_i)^2)
         *
         * Notes:
         *   Adds the barrier curvature onto the DIAGONAL of a dense column-major HESS_STRIDE x HESS_STRIDE block.
         *   HESS_OFFSET places it in the qd / u block; HESS_STRIDE is the block leading dimension.
         *   isfinite-guarded per side; an unbounded DOF adds exactly zero.
         *
         * @param s_hess is the dense column-major hessian (added into)
         * @param s_var / s_lower / s_upper / mu as above
         */
        template <typename T, int HESS_STRIDE, int VAR_OFFSET = 29, int HESS_OFFSET = 0>
        __device__
        void joint_velocity_barrier_hessian(T *s_hess, const T *s_var, const T *s_lower, const T *s_upper, const T mu) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                int d = HESS_OFFSET + i;
                s_hess[d * HESS_STRIDE + d] += grid_plant_log_barrier_hess<T>(s_var[VAR_OFFSET + i], s_lower[i], s_upper[i], mu);
            }
        }

        /**
         * joint_torque_barrier: value += -mu * sum_i ( log(x_i - lo_i) + log(hi_i - x_i) ) over the NUM_VEL u-DOFs
         *
         * Notes:
         *   Block-cooperative reduction into s_scratch then a serial add into s_out[0].
         *   s_lower / s_upper are explicit bound vectors (size 29); an inf entry skips that side (isfinite guard).
         *   s_scratch must hold at least 29 elements.
         *
         * @param s_out is the scalar barrier cost (added into s_out[0])
         * @param s_var is the variable vector (this barrier reads s_var[0 + i])
         * @param s_lower / s_upper are the per-DOF bounds (size 29)
         * @param mu is the barrier weight
         * @param s_scratch is shared scratch of size >= 29
         */
        template <typename T>
        __device__
        void joint_torque_barrier(T *s_out, const T *s_var, const T *s_lower, const T *s_upper, const T mu, T *s_scratch) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                s_scratch[i] = grid_plant_log_barrier<T>(s_var[0 + i], s_lower[i], s_upper[i], mu);
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                for (int i = 0; i < 29; ++i) acc += s_scratch[i];
                s_out[0] += acc;
            }
        }

        /**
         * joint_torque_barrier_gradient: s_grad[GRAD_OFFSET + i] += -mu*(1/(x_i-lo_i) - 1/(hi_i-x_i))
         *
         * Notes:
         *   Adds into the packed gradient at GRAD_OFFSET (a template arg so velocity/torque barriers land in the qd / u rows).
         *   isfinite-guarded per side; an unbounded DOF adds exactly zero.
         *
         * @param s_grad is the packed gradient output (added into)
         * @param s_var / s_lower / s_upper / mu as in the value function
         */
        template <typename T, int VAR_OFFSET = 0, int GRAD_OFFSET = 0>
        __device__
        void joint_torque_barrier_gradient(T *s_grad, const T *s_var, const T *s_lower, const T *s_upper, const T mu) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                s_grad[GRAD_OFFSET + i] += grid_plant_log_barrier_grad<T>(s_var[VAR_OFFSET + i], s_lower[i], s_upper[i], mu);
            }
        }

        /**
         * joint_torque_barrier_hessian: s_hess[(HESS_OFFSET+i)*HESS_STRIDE + (HESS_OFFSET+i)] += mu*(1/(x_i-lo_i)^2 + 1/(hi_i-x_i)^2)
         *
         * Notes:
         *   Adds the barrier curvature onto the DIAGONAL of a dense column-major HESS_STRIDE x HESS_STRIDE block.
         *   HESS_OFFSET places it in the qd / u block; HESS_STRIDE is the block leading dimension.
         *   isfinite-guarded per side; an unbounded DOF adds exactly zero.
         *
         * @param s_hess is the dense column-major hessian (added into)
         * @param s_var / s_lower / s_upper / mu as above
         */
        template <typename T, int HESS_STRIDE, int VAR_OFFSET = 0, int HESS_OFFSET = 0>
        __device__
        void joint_torque_barrier_hessian(T *s_hess, const T *s_var, const T *s_lower, const T *s_upper, const T mu) {
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                int d = HESS_OFFSET + i;
                s_hess[d * HESS_STRIDE + d] += grid_plant_log_barrier_hess<T>(s_var[VAR_OFFSET + i], s_lower[i], s_upper[i], mu);
            }
        }

        /**
         * Plant step: x_{k+1} = integrator(x_k, u_k, dt) (thin wrapper over grid::integrator_device)
         *
         * @param s_x_kp1 is the next state output (size NUM_POS + NUM_VEL)
         * @param s_x is the current state [q (NUM_POS); qd (NUM_VEL)]
         * @param s_u is the control torque vector (size NUM_VEL)
         * @param d_robotModel is the GPU model helpers (XImats, topology, ...)
         * @param gravity is the gravity constant
         * @param dt is the integration timestep
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool MUJOCO_OUTPUT = false>
        __device__
        void plant_step(T *s_x_kp1, const T *s_x, const T *s_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt) {
            const T *s_q  = s_x;
            const T *s_qd = &s_x[29];
            grid::integrator_device<T, IT>(s_x_kp1, s_q, s_qd, s_u, d_robotModel, nullptr, gravity, dt);
        }

        /**
         * Plant step gradient [A|B] (thin wrapper over grid::integrator_gradient_device — pass-through)
         *
         * @param s_dAB is the [A | B] output (2*NUM_VEL x 3*NUM_VEL, column-major)
         * @param s_x is the current state [q; qd] (NON-const: mutated across RK stages)
         * @param s_u is the control torque vector (size NUM_VEL)
         * @param s_df_du / s_dc_du / s_vaf / s_Minv / s_qdd are FD-grad in/out scratch (caller-placed)
         * @param s_q_orig / s_qd_orig / s_stage_grad_qdd / s_D_qdd_stage are multi-stage scratch (caller-placed)
         * @param s_dInt_q_6x6 / s_dInt_v_6x6 are floating-base SE(3) dIntegrate blocks (unused fixed-base)
         * @param s_temp / d_workspace / d_temp_spill are the integrator-gradient scratch arenas (caller-placed)
         * @param d_robotModel / gravity / dt as for plant_step
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false>
        __device__
        void plant_step_gradient(T *s_dAB, T *s_x, const T *s_u, T *s_df_du, T *s_dc_du, T *s_vaf, T *s_Minv, T *s_qdd, T *s_q_orig, T *s_qd_orig, T *s_stage_grad_qdd, T *s_D_qdd_stage, T *s_dInt_q_6x6, T *s_dInt_v_6x6, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt) {
            T *s_q  = s_x;
            T *s_qd = &s_x[29];
            grid::integrator_gradient_device<T, IT, SCRATCH_IN_SMEM, USE_DA_DF_SPILL>(s_dAB, s_q, s_qd, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, d_workspace, d_temp_spill, d_robotModel, nullptr, gravity, dt);
        }

        /**
         * Plant step gradient [A|B] + value (thin wrapper over grid::integrator_with_gradient_device — pass-through)
         *
         * @param s_dAB is the [A | B] output (2*NUM_VEL x 3*NUM_VEL, column-major)
         * @param s_x_kp1 is the next-state output (size NUM_POS + NUM_VEL)
         * @param s_x is the current state [q; qd] (NON-const: mutated across RK stages)
         * @param s_u is the control torque vector (size NUM_VEL)
         * @param s_df_du / s_dc_du / s_vaf / s_Minv / s_qdd are FD-grad in/out scratch (caller-placed)
         * @param s_q_orig / s_qd_orig / s_stage_grad_qdd / s_D_qdd_stage are multi-stage scratch (caller-placed)
         * @param s_dInt_q_6x6 / s_dInt_v_6x6 are floating-base SE(3) dIntegrate blocks (unused fixed-base)
         * @param s_temp / d_workspace / d_temp_spill are the integrator-gradient scratch arenas (caller-placed)
         * @param d_robotModel / gravity / dt as for plant_step
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool USE_DA_DF_SPILL = false>
        __device__
        void plant_step_gradient_and_value(T *s_dAB, T *s_x_kp1, T *s_x, const T *s_u, T *s_df_du, T *s_dc_du, T *s_vaf, T *s_Minv, T *s_qdd, T *s_q_orig, T *s_qd_orig, T *s_stage_grad_qdd, T *s_D_qdd_stage, T *s_dInt_q_6x6, T *s_dInt_v_6x6, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_temp_spill, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt) {
            T *s_q  = s_x;
            T *s_qd = &s_x[29];
            grid::integrator_with_gradient_device<T, IT, SCRATCH_IN_SMEM, USE_DA_DF_SPILL>(s_dAB, s_x_kp1, s_q, s_qd, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, d_workspace, d_temp_spill, d_robotModel, nullptr, gravity, dt);
        }

        /**
         * Plant step hessian s_d2AB (thin wrapper over grid::integrator_hessian_device — pass-through)
         *
         * @param s_d2AB is the Hessian output (2*NUM_VEL x 3*NUM_VEL x 3*NUM_VEL, row-major)
         * @param s_x is the current state [q; qd]
         * @param s_u is the control torque vector (size NUM_VEL)
         * @param s_df2 / s_idsva_so / s_Minv / s_df_du / s_qdd are fdsva_so in/out scratch (caller-placed)
         * @param s_temp / d_workspace / d_fd_grad_spill / s_fdsva_temp are the fdsva_so scratch arenas (caller-placed)
         * @param d_robotModel / gravity / dt as for plant_step
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool SCRATCH_IN_SMEM = true, bool FD_GRAD_USE_SPILL = false, bool CONTRACT_IN_SMEM = true>
        __device__
        void plant_step_hessian(T *s_d2AB, const T *s_x, const T *s_u, T *s_df2, T *s_idsva_so, T *s_Minv, T *s_df_du, T *s_qdd, T *s_XImats, int *s_topology_helpers, T *s_temp, T *d_workspace, T *d_fd_grad_spill, T *s_fdsva_temp, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt) {
            const T *s_q  = s_x;
            const T *s_qd = &s_x[29];
            grid::integrator_hessian_device<T, IT, SCRATCH_IN_SMEM, FD_GRAD_USE_SPILL, CONTRACT_IN_SMEM>(s_d2AB, s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_q, s_qd, s_u, s_XImats, s_topology_helpers, s_temp, d_workspace, d_fd_grad_spill, s_fdsva_temp, d_robotModel, gravity, dt);
        }

        /**
         * ee_pos_cost: value = 1/2 * sum_r W[r] * (p_r(q) - p_des_r)^2 over the 3 position axes
         *
         * Notes:
         *   Caller-scratch INNER: lays out the EE-pose scratch from s_scratch and calls grid::end_effector_pose_inner directly (NOT the auto-allocating _device), so it is callable from another kernel's block without aliasing that kernel's dynamic-smem arena.
         *   EE selects which end-effector (0..3).
         *   s_end_effector_pose must hold 6*NUM_EE; s_scratch must hold >= END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_COUNT elements of T.
         *
         * @param s_out is the scalar cost output (s_out[0])
         * @param s_q is the joint position vector (size NUM_POS)
         * @param s_p_des is the desired EE position (3-vector)
         * @param s_W is the per-axis position weight (3-vector)
         * @param s_end_effector_pose is scratch for the 6*NUM_EE pose (the position is rows 0..2 of EE block)
         * @param s_scratch is caller shared scratch for the EE-pose helper (>= END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_COUNT, 16B aligned)
         * @param d_robotModel is the GPU model helpers
         */
        template <typename T, int EE = 0, bool ACCUMULATE = false>
        __device__
        void ee_pos_cost(T *s_out, const T *s_q, const T *s_p_des, const T *s_W, T *s_end_effector_pose, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_XmatsHom[624]
            //   T s_temp[128]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(128);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(752, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            end_effector_pose_inner<T, true>(s_end_effector_pose, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                #pragma unroll
                for (int r = 0; r < 3; ++r) { T e = s_end_effector_pose[6*EE + r] - s_p_des[r]; acc += static_cast<T>(0.5) * s_W[r] * e * e; }
                if (ACCUMULATE) { s_out[0] += acc; } else { s_out[0] = acc; }
            }
        }

        /**
         * ee_pos_cost_gradient: grad_x = [J_p^T W (p - p_des) ; 0], over x = [q; qd]
         *
         * Notes:
         *   Caller-scratch INNER: ONE XmatsHom load feeds BOTH end_effector_pose_inner (for p) and end_effector_pose_gradient_inner (for J_p) -- s_Xhom is const in both inners, so the local homogeneous transforms are loaded once and shared (vs the old double-load through two auto-allocating _device calls). The geometric-Jacobian inner uses only s_Xhom (s_dXhom = nullptr), so no per-joint d-transform load is needed. Callable from another kernel's block without aliasing that kernel's dynamic-smem arena.
         *   J_p = rows 0..2 of s_end_effector_pose_gradient, layout s_end_effector_pose_gradient[6*NUM_VEL*ee + 6*vi + row].
         *   The qd-block of the gradient (entries NUM_VEL..57) is set to exactly zero.
         *   ACCUMULATE=false overwrites s_grad; true adds (for fusing with a state-cost gradient).
         *
         * @param s_grad is the gradient over x (size NUM_POS + NUM_VEL = 58)
         * @param s_q / s_p_des / s_W / d_robotModel as above
         * @param s_end_effector_pose is 6*NUM_EE pose scratch; s_end_effector_pose_gradient is 6*NUM_VEL*NUM_EE Jacobian scratch
         * @param s_scratch is caller shared scratch for the EE-pose+gradient helper (>= END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_COUNT, 16B aligned)
         */
        template <typename T, int EE = 0, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void ee_pos_cost_gradient(T *s_grad, const T *s_q, const T *s_p_des, const T *s_W, T *s_end_effector_pose, T *s_end_effector_pose_gradient, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_XmatsHom[624]
            //   T s_temp[1336]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1336);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(1960, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            end_effector_pose_inner<T, true>(s_end_effector_pose, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            end_effector_pose_gradient_inner<T, true>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                T g = static_cast<T>(0);
                #pragma unroll
                for (int r = 0; r < 3; ++r) {
                    T Jri = s_end_effector_pose_gradient[6*29*EE + 6*i + r];
                    T e   = s_end_effector_pose[6*EE + r] - s_p_des[r];
                    g += Jri * s_W[r] * e;
                }
                if (ACCUMULATE) { s_grad[i] += g; } else { s_grad[i] = g; }
            }
            if (!ACCUMULATE) {
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                    s_grad[29 + i] = static_cast<T>(0);
                }
            }
        }

        /**
         * ee_pos_cost_hessian: EE-position cost hessian. DEFAULT = full Newton = J_p^T W J_p + sum_r W[r] (p_r - p_des_r) d2p_r/dv2; GAUSS_NEWTON=true = ratified PSD GN term only
         *
         * Notes:
         *   DEFAULT (GAUSS_NEWTON=false) folds the exact residual-weighted EE-curvature term via the analytic d2ee (grid::end_effector_pose_hessian_inner). Not necessarily PSD away from the solution -- callers must regularize (e.g. the solver's rho schedule).
         *   GAUSS_NEWTON=true keeps the ratified PSD choice H = J_p^T diag(W) J_p (curvature dropped); s_p_des, s_end_effector_pose and s_end_effector_pose_hessian may be nullptr in that case.
         *   PSD_CLAMP=true (opt-in, default false) eigen-clamps the NV x NV q-block to >= psd_reg_eps (glass::eig_clamp) so the returned hessian is SPD and directly factorable even when the Newton curvature is indefinite -- a guaranteed-PSD alternative to a caller-side rho schedule. Costs one block-cooperative Jacobi eigensolve; s_scratch must hold NV*NV + eig_clamp_scratch when set.
         *   Caller-scratch INNER: ONE XmatsHom load feeds the needed inners (GN: gradient_inner only, s_dXhom = nullptr; Newton: pose_inner for the residual + hessian_inner, which also fills the gradient buffer), so it is callable from another kernel's block without aliasing that kernel's dynamic-smem arena.
         *   d2p layout: s_end_effector_pose_hessian[6*NV*NV*ee + r*NV*NV + vi*NV + vj] (pose row r, joint pair (vi, vj); tangent d/dv convention, position rows 0..2 symmetric in (vi, vj)).
         *   Dense column-major NX x NX (NX = NUM_POS + NUM_VEL = 58); only the top-left NUM_VEL x NUM_VEL q-block is non-zero.
         *   ACCUMULATE=false overwrites the whole NX x NX block; true adds the q-block into an existing hessian.
         *
         * @param s_hess is the dense x-hessian output (size 58*58, column-major)
         * @param s_q / s_p_des / s_W / d_robotModel as above (s_p_des is unused under GAUSS_NEWTON)
         * @param s_end_effector_pose is 6*NUM_EE pose scratch (Newton only); s_end_effector_pose_gradient is 6*NUM_VEL*NUM_EE Jacobian scratch; s_end_effector_pose_hessian is 6*NUM_VEL*NUM_VEL*NUM_EE d2ee scratch (Newton only)
         * @param s_scratch is caller shared scratch for the EE helpers (GN: >= END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_COUNT; Newton: >= END_EFFECTOR_POSE_HESSIAN_DYNAMIC_SHARED_MEM_COUNT covers it; 16B aligned)
         */
        template <typename T, int EE = 0, bool ACCUMULATE = false, bool GAUSS_NEWTON = false, bool MUJOCO_OUTPUT = false, bool PSD_CLAMP = false>
        __device__
        void ee_pos_cost_hessian(T *s_hess, const T *s_q, const T *s_p_des, const T *s_W, T *s_end_effector_pose, T *s_end_effector_pose_gradient, T *s_end_effector_pose_hessian, T *s_scratch, const grid::robotModel<T> *d_robotModel, T psd_reg_eps = static_cast<T>(1e-6)) {
            using namespace grid;
            if constexpr (!GAUSS_NEWTON) {
                // GRID shared arena layout
                //   T s_XmatsHom[624]
                //   T s_temp[2496]
                //   int s_topology_helpers[175]
                //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
                unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
                size_t s_arena_offset = 0;
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(624);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(2496);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
                int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(int) * static_cast<size_t>(175);
                unsigned char *s_linalg_smem = nullptr;
                if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                    s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                    s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                    s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
                }
                #ifdef GRID_CUDA_DEBUG_LAYOUT
                assert(s_arena_offset == grid_shared_arena_bytes<T>(3120, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
                #endif
                (void)s_arena_offset;
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_inner<T, true>(s_end_effector_pose, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
                __syncthreads();
                end_effector_pose_hessian_inner<T, true>(s_end_effector_pose_hessian, s_end_effector_pose_gradient, s_q, s_XmatsHom, s_topology_helpers, s_temp, nullptr, d_robotModel, s_linalg_smem);
                __syncthreads();
            }
            else {
                // GRID shared arena layout
                //   T s_XmatsHom[624]
                //   T s_temp[1336]
                //   int s_topology_helpers[175]
                //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
                unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
                size_t s_arena_offset = 0;
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(624);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
                T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(T) * static_cast<size_t>(1336);
                s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
                int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
                s_arena_offset += sizeof(int) * static_cast<size_t>(175);
                unsigned char *s_linalg_smem = nullptr;
                if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                    s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                    s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                    s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
                }
                #ifdef GRID_CUDA_DEBUG_LAYOUT
                assert(s_arena_offset == grid_shared_arena_bytes<T>(1960, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
                #endif
                (void)s_arena_offset;
                load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
                end_effector_pose_gradient_inner<T, true>(s_end_effector_pose_gradient, s_q, s_XmatsHom, nullptr, s_topology_helpers, s_temp, nullptr, s_linalg_smem);
                __syncthreads();
            }
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3364; ind += blockDim.x*blockDim.y){
                int row = ind % 58;
                int col = ind / 58;
                T h = static_cast<T>(0);
                if (row < 29 && col < 29) {
                    #pragma unroll
                    for (int r = 0; r < 3; ++r) {
                        T Jri = s_end_effector_pose_gradient[6*29*EE + 6*row + r];
                        T Jrj = s_end_effector_pose_gradient[6*29*EE + 6*col + r];
                        h += Jri * s_W[r] * Jrj;
                        if constexpr (!GAUSS_NEWTON) {
                            T e   = s_end_effector_pose[6*EE + r] - s_p_des[r];
                            T Hij = s_end_effector_pose_hessian[6*841*EE + r*841 + row*29 + col];
                            h += s_W[r] * e * Hij;
                        }
                    }
                }
                if (ACCUMULATE) { s_hess[ind] += h; } else { s_hess[ind] = h; }
            }
            if constexpr (PSD_CLAMP) {
                __syncthreads();
                T *s_psd_qb = s_scratch; T *s_psd_eig = &s_scratch[841];
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 841; ind += blockDim.x*blockDim.y){
                    int r = ind % 29; int c = ind / 29;
                    s_psd_qb[r + 29*c] = s_hess[r + 58*c];
                }
                __syncthreads();
                glass::eig_clamp<T, 29>(s_psd_qb, psd_reg_eps, s_psd_eig);
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 841; ind += blockDim.x*blockDim.y){
                    int r = ind % 29; int c = ind / 29;
                    s_hess[r + 58*c] = s_psd_qb[r + 29*c];
                }
                __syncthreads();
            }
        }

        /**
         * tracking_cost: total scalar cost = ee_pos_cost + quadratic_state_cost + quadratic_input_cost + joint_{position,velocity,torque}_barrier (GATO BSQP recipe, composed from the per-term inners)
         *
         * Notes:
         *   PRESET (sugar): one composition of the public per-term cost inners; users compose other mixes directly.
         *   ACCUMULATE=false overwrites s_out[0]; true adds (the first term carries ACCUMULATE, the rest add).
         *   s_end_effector_pose holds 6*NUM_EE; s_scratch must hold >= END_EFFECTOR_POSE_DYNAMIC_SHARED_MEM_COUNT (and >= NX).
         *   Fixed-base only (NUM_POS == NUM_VEL); floating-base composition is a follow-up.
         *
         * @param s_out is the scalar total-cost output (s_out[0])
         * @param s_x / s_u are the current state [q; qd] and control (sizes 58 / 29)
         * @param s_x_des / s_u_des / s_ee_des are the targets (state 58, input 29, EE position 3)
         * @param s_Q / s_R are the quadratic state/input diagonal weights (sizes 58 / 29); s_W is the per-axis EE position weight (3). Zero a weight to disable that term.
         * @param s_q_lower/upper + mu_q, s_qd_lower/upper + mu_qd, s_u_lower/upper + mu_u are the position / velocity / torque log-barrier bounds + weights (mu=0 or +/-inf bound disables).
         * @param EE selects the end-effector; running-vs-terminal weighting is caller-supplied (write terminal weights at the terminal knot — contract, not a baked branch).
         * @param s_end_effector_pose / s_scratch are caller EE-pose scratch; d_robotModel is the GPU model
         */
        template <typename T, int EE = 0, bool ACCUMULATE = false>
        __device__
        void tracking_cost(T *s_out, const T *s_x, const T *s_u, const T *s_x_des, const T *s_u_des, const T *s_ee_des, const T *s_Q, const T *s_R, const T *s_W, const T *s_q_lower, const T *s_q_upper, const T mu_q, const T *s_qd_lower, const T *s_qd_upper, const T mu_qd, const T *s_u_lower, const T *s_u_upper, const T mu_u, T *s_end_effector_pose, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            ee_pos_cost<T, EE, ACCUMULATE>(s_out, s_x, s_ee_des, s_W, s_end_effector_pose, s_scratch, d_robotModel);
            __syncthreads();
            quadratic_state_cost<T, true>(s_out, s_x, s_x_des, s_Q, s_scratch);
            __syncthreads();
            quadratic_input_cost<T, true>(s_out, s_u, s_u_des, s_R, s_scratch);
            __syncthreads();
            joint_position_barrier<T>(s_out, s_x, s_q_lower, s_q_upper, mu_q, s_scratch);
            __syncthreads();
            joint_velocity_barrier<T>(s_out, s_x, s_qd_lower, s_qd_upper, mu_qd, s_scratch);
            __syncthreads();
            joint_torque_barrier<T>(s_out, s_u, s_u_lower, s_u_upper, mu_u, s_scratch);
        }

        /**
         * tracking_cost_gradient: s_qk (state gradient, NX) + s_rk (input gradient, NU), composed from the per-term gradient inners
         *
         * Notes:
         *   State block s_qk = ee_pos_cost_gradient (J^T W r in q-block, 0 in qd) + quadratic_state_cost_gradient + joint_position_barrier_gradient (q-block) + joint_velocity_barrier_gradient (qd-block).
         *   Input block s_rk = quadratic_input_cost_gradient + joint_torque_barrier_gradient.
         *   ACCUMULATE=false overwrites the blocks; true adds into them (the EE / input-quadratic terms carry ACCUMULATE, the rest add).
         *   Sync between every accumulating term (different inners own different threads per index).
         *   s_scratch must hold >= END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_COUNT. Fixed-base only.
         *
         * @param s_qk is the state-block gradient output (size NX = 58)
         * @param s_rk is the input-block gradient output (size NU = 29)
         * @param s_x / s_u are the current state [q; qd] and control (sizes 58 / 29)
         * @param s_x_des / s_u_des / s_ee_des are the targets (state 58, input 29, EE position 3)
         * @param s_Q / s_R are the quadratic state/input diagonal weights (sizes 58 / 29); s_W is the per-axis EE position weight (3). Zero a weight to disable that term.
         * @param s_q_lower/upper + mu_q, s_qd_lower/upper + mu_qd, s_u_lower/upper + mu_u are the position / velocity / torque log-barrier bounds + weights (mu=0 or +/-inf bound disables).
         * @param EE selects the end-effector; running-vs-terminal weighting is caller-supplied (write terminal weights at the terminal knot — contract, not a baked branch).
         * @param s_end_effector_pose (6*NUM_EE) / s_end_effector_pose_gradient (6*NUM_VEL*NUM_EE) / s_scratch are caller EE scratch
         * @param d_robotModel is the GPU model
         */
        template <typename T, int EE = 0, bool ACCUMULATE = false>
        __device__
        void tracking_cost_gradient(T *s_qk, T *s_rk, const T *s_x, const T *s_u, const T *s_x_des, const T *s_u_des, const T *s_ee_des, const T *s_Q, const T *s_R, const T *s_W, const T *s_q_lower, const T *s_q_upper, const T mu_q, const T *s_qd_lower, const T *s_qd_upper, const T mu_qd, const T *s_u_lower, const T *s_u_upper, const T mu_u, T *s_end_effector_pose, T *s_end_effector_pose_gradient, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            // ---- state-block gradient s_qk (NX) ----
            ee_pos_cost_gradient<T, EE, ACCUMULATE>(s_qk, s_x, s_ee_des, s_W, s_end_effector_pose, s_end_effector_pose_gradient, s_scratch, d_robotModel);
            __syncthreads();
            quadratic_state_cost_gradient<T, true>(s_qk, s_x, s_x_des, s_Q);
            __syncthreads();
            joint_position_barrier_gradient<T, 0, 0>(s_qk, s_x, s_q_lower, s_q_upper, mu_q);
            __syncthreads();
            joint_velocity_barrier_gradient<T, 29, 29>(s_qk, s_x, s_qd_lower, s_qd_upper, mu_qd);
            __syncthreads();
            // ---- input-block gradient s_rk (NU) ----
            quadratic_input_cost_gradient<T, ACCUMULATE>(s_rk, s_u, s_u_des, s_R);
            __syncthreads();
            joint_torque_barrier_gradient<T, 0, 0>(s_rk, s_u, s_u_lower, s_u_upper, mu_u);
        }

        /**
         * tracking_cost_hessian: s_Qk (state GN hessian, NX*NX col-major) + s_Rk (input hessian, NU*NU), composed from the per-term hessian inners
         *
         * Notes:
         *   State block s_Qk = ee_pos_cost_hessian (J^T W J in q-block) + quadratic_state_cost_hessian (diag) + joint_position_barrier_hessian (q diagonal) + joint_velocity_barrier_hessian (qd diagonal).
         *   Input block s_Rk = quadratic_input_cost_hessian (diag) + joint_torque_barrier_hessian (diagonal).
         *   Gauss-Newton: the EE value-curvature is dropped (matches the per-term GN choice).
         *   ACCUMULATE=false overwrites; true adds (the EE / input-quadratic terms carry ACCUMULATE, the rest add).
         *   s_scratch must hold >= END_EFFECTOR_POSE_GRADIENT_DYNAMIC_SHARED_MEM_COUNT. Fixed-base only.
         *
         * @param s_Qk is the state GN hessian output (size NX*NX = 3364, column-major)
         * @param s_Rk is the input hessian output (size NU*NU = 841, column-major)
         * @param s_x / s_u are the current state and control
         * @param s_Q / s_R / s_W are the quadratic state/input + EE weights
         * @param s_q_lower/upper + mu_q, s_qd_lower/upper + mu_qd, s_u_lower/upper + mu_u are the barrier bounds + weights
         * @param s_end_effector_pose_gradient (6*NUM_VEL*NUM_EE) / s_scratch are caller EE scratch; d_robotModel is the GPU model
         */
        template <typename T, int EE = 0, bool ACCUMULATE = false>
        __device__
        void tracking_cost_hessian(T *s_Qk, T *s_Rk, const T *s_x, const T *s_u, const T *s_Q, const T *s_R, const T *s_W, const T *s_q_lower, const T *s_q_upper, const T mu_q, const T *s_qd_lower, const T *s_qd_upper, const T mu_qd, const T *s_u_lower, const T *s_u_upper, const T mu_u, T *s_end_effector_pose_gradient, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            // ---- state-block GN hessian s_Qk (NX*NX) ----
            ee_pos_cost_hessian<T, EE, ACCUMULATE, true>(s_Qk, s_x, nullptr, s_W, nullptr, s_end_effector_pose_gradient, nullptr, s_scratch, d_robotModel);
            __syncthreads();
            quadratic_state_cost_hessian<T, true>(s_Qk, s_Q);
            __syncthreads();
            joint_position_barrier_hessian<T, 58, 0, 0>(s_Qk, s_x, s_q_lower, s_q_upper, mu_q);
            __syncthreads();
            joint_velocity_barrier_hessian<T, 58, 29, 29>(s_Qk, s_x, s_qd_lower, s_qd_upper, mu_qd);
            __syncthreads();
            // ---- input-block hessian s_Rk (NU*NU) ----
            quadratic_input_cost_hessian<T, ACCUMULATE>(s_Rk, s_R);
            __syncthreads();
            joint_torque_barrier_hessian<T, 29, 0, 0>(s_Rk, s_u, s_u_lower, s_u_upper, mu_u);
        }

        /**
         * com_cost: value = 1/2 sum_r W[r] (p_com_r(q) - p_des_r)^2 over the 3 CoM axes
         *
         * Notes:
         *   Caller-scratch INNER: lays out the centroidal arena from s_scratch and runs centroidal_inner (fills s_com = CoM pos, s_A = CMM, s_extra = mass), NOT the auto-allocating grid::com_device, so it is callable from another kernel's block without aliasing that kernel's dynamic-smem arena.
         *   s_scratch must hold >= COM_DYNAMIC_SHARED_MEM_COUNT elements of T (16B aligned).
         *
         * @param s_out scalar cost
         * @param s_q joint positions
         * @param s_p_des desired CoM (3)
         * @param s_W per-axis weight (3)
         * @param s_scratch caller centroidal-arena scratch (>= COM_DYNAMIC_SHARED_MEM_COUNT)
         * @param d_robotModel GPU model helpers
         */
        template <typename T, bool ACCUMULATE = false>
        __device__
        void com_cost(T *s_out, const T *s_q, const T *s_p_des, const T *s_W, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_A[174]
            //   T s_com[3]
            //   T s_extra[4]
            //   T s_XmatsHom[624]
            //   T s_temp[6764]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_A = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(174);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_com = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_extra = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(4);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(6764);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7569, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            centroidal_inner<T, true>(s_A, s_com, s_extra, s_q, s_XmatsHom, d_robotModel, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                #pragma unroll
                for (int r = 0; r < 3; ++r) { T e = s_com[r] - s_p_des[r]; acc += static_cast<T>(0.5) * s_W[r] * e * e; }
                if (ACCUMULATE) { s_out[0] += acc; } else { s_out[0] = acc; }
            }
        }

        /**
         * com_cost_gradient: grad_x = [J_com^T W (p_com - p_des) ; 0]
         *
         * Notes:
         *   Caller-scratch INNER (centroidal_inner from s_scratch): J_com[r,vi] = s_A[r + 6*vi] / mass (top-3 rows of the CMM s_A / mass).
         *
         * @param s_grad gradient over x (58)
         * @param s_q / s_p_des / s_W / d_robotModel as above
         * @param s_scratch caller centroidal-arena scratch (>= COM_DYNAMIC_SHARED_MEM_COUNT)
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void com_cost_gradient(T *s_grad, const T *s_q, const T *s_p_des, const T *s_W, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_A[174]
            //   T s_com[3]
            //   T s_extra[4]
            //   T s_XmatsHom[624]
            //   T s_temp[6764]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_A = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(174);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_com = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_extra = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(4);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(6764);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7569, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            centroidal_inner<T, true>(s_A, s_com, s_extra, s_q, s_XmatsHom, d_robotModel, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            T inv_m = static_cast<T>(1) / s_extra[0];
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                T g = static_cast<T>(0);
                #pragma unroll
                for (int r = 0; r < 3; ++r) { T Jri = s_A[r + 6*i] * inv_m; T e = s_com[r] - s_p_des[r]; g += Jri * s_W[r] * e; }
                if (ACCUMULATE) { s_grad[i] += g; } else { s_grad[i] = g; }
            }
            if (!ACCUMULATE) {
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                    s_grad[29 + i] = static_cast<T>(0);
                }
            }
        }

        /**
         * com_cost_hessian: Gauss-Newton hessian = J_com^T diag(W) J_com in the q-block of the x-hessian
         *
         * Notes:
         *   Caller-scratch INNER (centroidal_inner from s_scratch); J_com[r,vi] = s_A[r + 6*vi] / mass.
         *   Dense column-major NX x NX; only the top-left NUM_VEL x NUM_VEL q-block is non-zero.
         *
         * @param s_hess dense x-hessian (3364)
         * @param s_q / s_W / d_robotModel as above
         * @param s_scratch caller centroidal-arena scratch (>= COM_DYNAMIC_SHARED_MEM_COUNT)
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void com_cost_hessian(T *s_hess, const T *s_q, const T *s_W, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_A[174]
            //   T s_com[3]
            //   T s_extra[4]
            //   T s_XmatsHom[624]
            //   T s_temp[6764]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_A = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(174);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_com = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_extra = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(4);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(6764);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7569, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            centroidal_inner<T, true>(s_A, s_com, s_extra, s_q, s_XmatsHom, d_robotModel, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            T inv_m = static_cast<T>(1) / s_extra[0];
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3364; ind += blockDim.x*blockDim.y){
                int row = ind % 58; int col = ind / 58;
                T h = static_cast<T>(0);
                if (row < 29 && col < 29) {
                    #pragma unroll
                    for (int r = 0; r < 3; ++r) { T Jri = s_A[r + 6*row] * inv_m; T Jrj = s_A[r + 6*col] * inv_m; h += Jri * s_W[r] * Jrj; }
                }
                if (ACCUMULATE) { s_hess[ind] += h; } else { s_hess[ind] = h; }
            }
        }

        /**
         * momentum_cost: value = 1/2 sum_r W[r] (h_r(q,qd) - h_des_r)^2 over the 6 centroidal components
         *
         * Notes:
         *   Caller-scratch INNER: lays out the centroidal arena from s_scratch and runs centroidal_inner (fills s_A = CMM 6 x NUM_VEL col-major), NOT the auto-allocating grid::ccrba_device. The momentum h = A*qd is computed here from s_A (ccrba's separate h-output is not in the arena).
         *   s_scratch must hold >= CCRBA_DYNAMIC_SHARED_MEM_COUNT elements of T (16B aligned).
         *
         * @param s_out scalar cost
         * @param s_q / s_qd joint position/velocity
         * @param s_h_des desired momentum (6)
         * @param s_W per-component weight (6)
         * @param s_scratch caller centroidal-arena scratch (>= CCRBA_DYNAMIC_SHARED_MEM_COUNT)
         * @param d_robotModel GPU model helpers
         */
        template <typename T, bool ACCUMULATE = false>
        __device__
        void momentum_cost(T *s_out, const T *s_q, const T *s_qd, const T *s_h_des, const T *s_W, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_A[174]
            //   T s_com[3]
            //   T s_extra[4]
            //   T s_XmatsHom[624]
            //   T s_temp[6764]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_A = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(174);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_com = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_extra = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(4);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(6764);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7569, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            centroidal_inner<T, true>(s_A, s_com, s_extra, s_q, s_XmatsHom, d_robotModel, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            __shared__ T s_e[6];
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 6; r += blockDim.x*blockDim.y){
                T h = static_cast<T>(0);
                #pragma unroll
                for (int vi = 0; vi < 29; ++vi) h += s_A[r + 6*vi] * s_qd[vi];
                s_e[r] = h - s_h_des[r];
            }
            __syncthreads();
            if(threadIdx.x == 0 && threadIdx.y == 0){
                T acc = static_cast<T>(0);
                #pragma unroll
                for (int r = 0; r < 6; ++r) { T e = s_e[r]; acc += static_cast<T>(0.5) * s_W[r] * e * e; }
                if (ACCUMULATE) { s_out[0] += acc; } else { s_out[0] = acc; }
            }
        }

        /**
         * momentum_cost_gradient: grad_x = [0 ; A^T W (h - h_des)] (q-block dropped, GN on A)
         *
         * Notes:
         *   Caller-scratch INNER (centroidal_inner from s_scratch): A = s_A[r + 6*vi] (6 x NUM_VEL column-major, the CMM); h = A*qd; J_h = A (GN drops dA/dq).
         *
         * @param s_grad gradient over x (58)
         * @param s_q / s_qd / s_h_des / s_W / d_robotModel as above
         * @param s_scratch caller centroidal-arena scratch (>= CCRBA_DYNAMIC_SHARED_MEM_COUNT)
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void momentum_cost_gradient(T *s_grad, const T *s_q, const T *s_qd, const T *s_h_des, const T *s_W, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_A[174]
            //   T s_com[3]
            //   T s_extra[4]
            //   T s_XmatsHom[624]
            //   T s_temp[6764]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_A = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(174);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_com = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_extra = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(4);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(6764);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7569, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            centroidal_inner<T, true>(s_A, s_com, s_extra, s_q, s_XmatsHom, d_robotModel, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            __shared__ T s_e[6];
            for(int r = threadIdx.x + threadIdx.y*blockDim.x; r < 6; r += blockDim.x*blockDim.y){
                T h = static_cast<T>(0);
                #pragma unroll
                for (int vi = 0; vi < 29; ++vi) h += s_A[r + 6*vi] * s_qd[vi];
                s_e[r] = h - s_h_des[r];
            }
            __syncthreads();
            if (!ACCUMULATE) {
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                    s_grad[i] = static_cast<T>(0);
                }
            }
            for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                T g = static_cast<T>(0);
                #pragma unroll
                for (int r = 0; r < 6; ++r) { g += s_A[r + 6*i] * s_W[r] * s_e[r]; }
                if (ACCUMULATE) { s_grad[29 + i] += g; } else { s_grad[29 + i] = g; }
            }
        }

        /**
         * momentum_cost_hessian: Gauss-Newton hessian = A^T diag(W) A in the qd-block of the x-hessian
         *
         * Notes:
         *   Caller-scratch INNER (centroidal_inner from s_scratch): A = s_A[r + 6*vi] (the CMM).
         *   Dense column-major NX x NX; only the bottom-right NUM_VEL x NUM_VEL qd-block is non-zero.
         *
         * @param s_hess dense x-hessian (3364)
         * @param s_q / s_qd / s_W / d_robotModel as above
         * @param s_scratch caller centroidal-arena scratch (>= CCRBA_DYNAMIC_SHARED_MEM_COUNT)
         */
        template <typename T, bool ACCUMULATE = false, bool MUJOCO_OUTPUT = false>
        __device__
        void momentum_cost_hessian(T *s_hess, const T *s_q, const T *s_qd, const T *s_W, T *s_scratch, const grid::robotModel<T> *d_robotModel) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_A[174]
            //   T s_com[3]
            //   T s_extra[4]
            //   T s_XmatsHom[624]
            //   T s_temp[6764]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_EE_LINALG_SHARED_BYTES<T>()]
            unsigned char *s_arena = reinterpret_cast<unsigned char *>(s_scratch);
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_A = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(174);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_com = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(3);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_extra = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(4);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XmatsHom = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(624);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(6764);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_EE_LINALG_SHARED_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(7569, 175, GRID_EE_LINALG_SHARED_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            load_update_XmatsHom_helpers<T>(s_XmatsHom, s_topology_helpers, s_q, d_robotModel, s_temp);
            centroidal_inner<T, true>(s_A, s_com, s_extra, s_q, s_XmatsHom, d_robotModel, s_temp, nullptr, s_linalg_smem);
            __syncthreads();
            for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 3364; ind += blockDim.x*blockDim.y){
                int row = ind % 58; int col = ind / 58;
                T h = static_cast<T>(0);
                if (row >= 29 && col >= 29) {
                    int vi = row - 29; int vj = col - 29;
                    #pragma unroll
                    for (int r = 0; r < 6; ++r) { T Ari = s_A[r + 6*vi]; T Arj = s_A[r + 6*vj]; h += Ari * s_W[r] * Arj; }
                }
                if (ACCUMULATE) { s_hess[ind] += h; } else { s_hess[ind] = h; }
            }
        }

        /**
         * quadratic_state_cost_kernel: value + gradient + GN-diag hessian per timestep
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad gradient (58 per timestep)
         * @param d_hess dense col-major hessian (58*58 per timestep)
         * @param d_x / d_x_des / d_Q inputs (58 per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, bool MUJOCO_OUTPUT = false>
        __global__
        void quadratic_state_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_x, const T *d_x_des, const T *d_Q, const int NUM_TIMESTEPS) {
            __shared__ T s_scratch[58];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                quadratic_state_cost_value_grad_hess<T>(&d_out[k], &d_grad[k*58], &d_hess[k*3364], &d_x[k*58], &d_x_des[k*58], &d_Q[k*58], s_scratch);
                __syncthreads();
            }
        }

        /**
         * quadratic_input_cost_kernel: value + gradient + GN-diag hessian per timestep
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad gradient (29 per timestep)
         * @param d_hess dense col-major hessian (29*29 per timestep)
         * @param d_u / d_u_des / d_R inputs (29 per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, bool MUJOCO_OUTPUT = false>
        __global__
        void quadratic_input_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_u, const T *d_u_des, const T *d_R, const int NUM_TIMESTEPS) {
            __shared__ T s_scratch[29];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                quadratic_input_cost_value_grad_hess<T>(&d_out[k], &d_grad[k*29], &d_hess[k*841], &d_u[k*29], &d_u_des[k*29], &d_R[k*29], s_scratch);
                __syncthreads();
            }
        }

        /**
         * joint_position_barrier_kernel: value + grad + hess-diagonal per timestep
         *
         * @param d_out scalar barrier cost (1 per timestep)
         * @param d_grad per-DOF gradient (29 per timestep)
         * @param d_hess_diag per-DOF hessian diagonal (29 per timestep)
         * @param d_var variable vector (29 per timestep)
         * @param d_lower / d_upper per-DOF bounds (29 per timestep)
         * @param mu barrier weight; NUM_TIMESTEPS is the batch size
         */
        template <typename T>
        __global__
        void joint_position_barrier_kernel(T *d_out, T *d_grad, T *d_hess_diag, const T *d_var, const T *d_lower, const T *d_upper, const T mu, const int NUM_TIMESTEPS) {
            __shared__ T s_scratch[29];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    d_out[k] = static_cast<T>(0);
                }
                __syncthreads();
                const T *s_var = &d_var[k*29]; const T *s_lo = &d_lower[k*29]; const T *s_hi = &d_upper[k*29];
                joint_position_barrier<T>(&d_out[k], s_var, s_lo, s_hi, mu, s_scratch);
                __syncthreads();
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                    d_grad[k*29 + i] = grid_plant_log_barrier_grad<T>(s_var[i], s_lo[i], s_hi[i], mu);
                    d_hess_diag[k*29 + i] = grid_plant_log_barrier_hess<T>(s_var[i], s_lo[i], s_hi[i], mu);
                }
                __syncthreads();
            }
        }

        /**
         * joint_velocity_barrier_kernel: value + grad + hess-diagonal per timestep
         *
         * @param d_out scalar barrier cost (1 per timestep)
         * @param d_grad per-DOF gradient (29 per timestep)
         * @param d_hess_diag per-DOF hessian diagonal (29 per timestep)
         * @param d_var variable vector (29 per timestep)
         * @param d_lower / d_upper per-DOF bounds (29 per timestep)
         * @param mu barrier weight; NUM_TIMESTEPS is the batch size
         */
        template <typename T>
        __global__
        void joint_velocity_barrier_kernel(T *d_out, T *d_grad, T *d_hess_diag, const T *d_var, const T *d_lower, const T *d_upper, const T mu, const int NUM_TIMESTEPS) {
            __shared__ T s_scratch[29];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    d_out[k] = static_cast<T>(0);
                }
                __syncthreads();
                const T *s_var = &d_var[k*29]; const T *s_lo = &d_lower[k*29]; const T *s_hi = &d_upper[k*29];
                joint_velocity_barrier<T>(&d_out[k], s_var, s_lo, s_hi, mu, s_scratch);
                __syncthreads();
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                    d_grad[k*29 + i] = grid_plant_log_barrier_grad<T>(s_var[i], s_lo[i], s_hi[i], mu);
                    d_hess_diag[k*29 + i] = grid_plant_log_barrier_hess<T>(s_var[i], s_lo[i], s_hi[i], mu);
                }
                __syncthreads();
            }
        }

        /**
         * joint_torque_barrier_kernel: value + grad + hess-diagonal per timestep
         *
         * @param d_out scalar barrier cost (1 per timestep)
         * @param d_grad per-DOF gradient (29 per timestep)
         * @param d_hess_diag per-DOF hessian diagonal (29 per timestep)
         * @param d_var variable vector (29 per timestep)
         * @param d_lower / d_upper per-DOF bounds (29 per timestep)
         * @param mu barrier weight; NUM_TIMESTEPS is the batch size
         */
        template <typename T>
        __global__
        void joint_torque_barrier_kernel(T *d_out, T *d_grad, T *d_hess_diag, const T *d_var, const T *d_lower, const T *d_upper, const T mu, const int NUM_TIMESTEPS) {
            __shared__ T s_scratch[29];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    d_out[k] = static_cast<T>(0);
                }
                __syncthreads();
                const T *s_var = &d_var[k*29]; const T *s_lo = &d_lower[k*29]; const T *s_hi = &d_upper[k*29];
                joint_torque_barrier<T>(&d_out[k], s_var, s_lo, s_hi, mu, s_scratch);
                __syncthreads();
                for(int i = threadIdx.x + threadIdx.y*blockDim.x; i < 29; i += blockDim.x*blockDim.y){
                    d_grad[k*29 + i] = grid_plant_log_barrier_grad<T>(s_var[i], s_lo[i], s_hi[i], mu);
                    d_hess_diag[k*29 + i] = grid_plant_log_barrier_hess<T>(s_var[i], s_lo[i], s_hi[i], mu);
                }
                __syncthreads();
            }
        }

        /**
         * plant_step kernel: x_{k+1} = integrator(x_k, u_k, dt) per timestep
         *
         * @param d_x_kp1 is the next-state output (NUM_POS+NUM_VEL per timestep)
         * @param d_x is the packed current state [q; qd] (NUM_POS+NUM_VEL per timestep)
         * @param d_u is the packed control torque (NUM_VEL per timestep)
         * @param stride_x / stride_u are the per-timestep strides
         * @param d_robotModel / gravity / dt as for plant_step
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool MUJOCO_OUTPUT = false>
        __global__
        void plant_step_kernel(T *d_x_kp1, const T *d_x, const T *d_u, const int stride_x, const int stride_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt, const int NUM_TIMESTEPS) {
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                plant_step<T, IT>(&d_x_kp1[k*58], &d_x[k*stride_x], &d_u[k*stride_u], d_robotModel, gravity, dt);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_STEP 1
        /**
         * plant_step_gradient kernel: [A|B] = integrator_gradient([q;qd], u, dt) per timestep (full-smem scratch arena; pass-through to grid::integrator_gradient_device)
         *
         * @param d_dAB is the [A|B] output (2*NUM_VEL*3*NUM_VEL per timestep, column-major)
         * @param d_x is the packed current state [q; qd] (NUM_POS+NUM_VEL per timestep)
         * @param d_u is the packed control torque (NUM_VEL per timestep)
         * @param stride_x / stride_u are the per-timestep strides
         * @param d_robotModel / gravity / dt as for plant_step
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, bool MUJOCO_OUTPUT = false>
        __global__
        __launch_bounds__(grid::MAX_PERF_LEVEL_THREADS)
        void plant_step_gradient_kernel(T *d_dAB, const T *d_x, const T *d_u, const int stride_x, const int stride_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt, const int NUM_TIMESTEPS) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_x[58]
            //   T s_u[29]
            //   T s_dAB[5046]
            //   T s_df_du[1682]
            //   T s_dc_du[1682]
            //   T s_vaf[522]
            //   T s_Minv[841]
            //   T s_qdd[29]
            //   T s_q_orig[29]
            //   T s_qd_orig[29]
            //   T s_stage_grad_qdd[116]
            //   T s_D_qdd_stage[10092]
            //   T s_dInt_q_6x6[36]
            //   T s_dInt_v_6x6[36]
            //   T s_XImats[2088]
            //   T s_temp[8574]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(58);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dAB = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(5046);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1682);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dc_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1682);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_vaf = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(522);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(841);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_q_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qd_orig = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_stage_grad_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(116);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_D_qdd_stage = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(10092);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_q_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_dInt_v_6x6 = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(36);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_temp = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(8574);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(30889, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 58; ind += blockDim.x*blockDim.y){
                    s_x[ind] = d_x[k*stride_x + ind];
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                    s_u[ind] = d_u[k*stride_u + ind];
                }
                __syncthreads();
                plant_step_gradient<T, IT, true, false>(s_dAB, s_x, s_u, s_df_du, s_dc_du, s_vaf, s_Minv, s_qdd, s_q_orig, s_qd_orig, s_stage_grad_qdd, s_D_qdd_stage, s_dInt_q_6x6, s_dInt_v_6x6, s_XImats, s_topology_helpers, s_temp, nullptr, nullptr, d_robotModel, gravity, dt);
                __syncthreads();
                if(threadIdx.x == 0 && threadIdx.y == 0){
                    for (int ind = 0; ind < 5046; ++ind) d_dAB[k*5046 + ind] = s_dAB[ind];
                }
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_STEP_GRADIENT 1
        template <typename T> __host__ __device__ inline size_t PLANT_HESSIAN_WORKSPACE_BYTES_PER_TIMESTEP() { return sizeof(T) * static_cast<size_t>(731670); }
        /**
         * plant_step_hessian kernel: s_d2AB = d^2 integrator([q;qd], u, dt) per timestep (tier-aware scratch; pass-through to grid::integrator_hessian_device)
         *
         * @param d_d2AB is the Hessian output (2*NUM_VEL*3*NUM_VEL*3*NUM_VEL per timestep, row-major)
         * @param d_workspace is the generated global spill workspace (nullptr at TIER_SHARED)
         * @param d_x is the packed current state [q; qd] (NUM_POS+NUM_VEL per timestep)
         * @param d_u is the packed control torque (NUM_VEL per timestep)
         * @param stride_x / stride_u are the per-timestep strides
         * @param d_robotModel / gravity / dt as for plant_step
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, grid::IntegratorType IT = grid::IntegratorType::EULER, int RESOURCE_TIER = grid::GRID_DEFAULT_RESOURCE_TIER, bool MUJOCO_OUTPUT = false>
        __global__
        __launch_bounds__(grid::tier_max_threads<RESOURCE_TIER>())
        void plant_step_hessian_kernel(T *d_d2AB, unsigned char *d_workspace, const T *d_x, const T *d_u, const int stride_x, const int stride_u, const grid::robotModel<T> *d_robotModel, const T gravity, const T dt, const int NUM_TIMESTEPS) {
            using namespace grid;
            // GRID shared arena layout
            //   T s_x[58]
            //   T s_u[29]
            //   T s_Minv[841]
            //   T s_df_du[1682]
            //   T s_qdd[29]
            //   T s_XImats[2088]
            //   int s_topology_helpers[175]
            //   bytes s_linalg_smem[GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()]
            extern __shared__ __align__(16) unsigned char s_arena[];
            size_t s_arena_offset = 0;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_x = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(58);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_u = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_Minv = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(841);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_df_du = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(1682);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_qdd = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(29);
            s_arena_offset = grid_align_up(s_arena_offset, alignof(T));
            T *s_XImats = grid_arena_ptr<T>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(T) * static_cast<size_t>(2088);
            T *s_temp = nullptr;
            s_arena_offset = grid_align_up(s_arena_offset, alignof(int));
            int *s_topology_helpers = grid_arena_ptr<int>(s_arena, s_arena_offset);
            s_arena_offset += sizeof(int) * static_cast<size_t>(175);
            unsigned char *s_linalg_smem = nullptr;
            if (static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()) > 0) {
                s_arena_offset = grid_align_up(s_arena_offset, static_cast<size_t>(16));
                s_linalg_smem = grid_arena_ptr<unsigned char>(s_arena, s_arena_offset);
                s_arena_offset += static_cast<size_t>(GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>());
            }
            #ifdef GRID_CUDA_DEBUG_LAYOUT
            assert(s_arena_offset == grid_shared_arena_bytes<T>(4727, 175, GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()));
            #endif
            (void)s_arena_offset;
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 58; ind += blockDim.x*blockDim.y){
                    s_x[ind] = d_x[k*stride_x + ind];
                }
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 29; ind += blockDim.x*blockDim.y){
                    s_u[ind] = d_u[k*stride_u + ind];
                }
                __syncthreads();
                T *d_ws = reinterpret_cast<T *>(&d_workspace[k*PLANT_HESSIAN_WORKSPACE_BYTES_PER_TIMESTEP<T>()]);
                size_t ws_off = 0;
                T *s_d2AB = &d_ws[ws_off]; ws_off += 439002;
                T *s_df2 = &d_ws[ws_off]; ws_off += 97556;
                T *s_idsva_so = &d_ws[ws_off]; ws_off += 97556;
                T *s_fdsva_pool = &d_ws[ws_off]; ws_off += 97556;
                (void)ws_off;
                plant_step_hessian<T, IT, false, false, false>(s_d2AB, s_x, s_u, s_df2, s_idsva_so, s_Minv, s_df_du, s_qdd, s_XImats, s_topology_helpers, s_temp, s_fdsva_pool, nullptr, s_fdsva_pool, d_robotModel, gravity, dt);
                __syncthreads();
                for(int ind = threadIdx.x + threadIdx.y*blockDim.x; ind < 439002; ind += blockDim.x*blockDim.y){
                    d_d2AB[k*439002 + ind] = s_d2AB[ind];
                }
                __syncthreads();
            }
        }

        template <typename T, int TIER = grid::GRID_DEFAULT_RESOURCE_TIER> __host__ __device__ inline size_t INTEGRATOR_HESSIAN_DYNAMIC_SHARED_MEM_BYTES() { if constexpr (TIER == grid::TIER_SHARED)    return grid::grid_shared_arena_bytes<T>(4727, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); else if constexpr (TIER == grid::TIER_LITE) return grid::grid_shared_arena_bytes<T>(4727, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); else                                        return grid::grid_shared_arena_bytes<T>(4727, grid::TOPOLOGY_HELPERS_COUNT, grid::GRID_LINALG_NVIDIA_MAX_HELPER_BYTES<T>()); }
        static const int GRID_PLANT_HESSIAN_USES_WORKSPACE_ANY_TIER = 1;
        #define GRID_PLANT_HAS_STEP_HESSIAN 1
        /**
         * ee_pos_cost_kernel: value + grad_x + GN hess_x per timestep (EE=0)
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad grad over x (58 per timestep)
         * @param d_hess dense col-major x-hessian (3364 per timestep)
         * @param d_q joint positions (NUM_POS per timestep)
         * @param d_p_des desired EE position (3 per timestep)
         * @param d_W per-axis weight (3 per timestep)
         * @param d_end_effector_pose / d_end_effector_pose_gradient global scratch (6*NUM_EES / 6*NUM_VEL*NUM_EES per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, int EE = 0, bool MUJOCO_OUTPUT = false>
        __global__
        void ee_pos_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_p_des, const T *d_W, T *d_end_effector_pose, T *d_end_effector_pose_gradient, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
            extern __shared__ __align__(16) T s_ee_arena[];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                const T *s_q = &d_q[k*29]; const T *s_p_des = &d_p_des[k*3]; const T *s_W = &d_W[k*3];
                T *s_end_effector_pose = &d_end_effector_pose[k*24]; T *s_end_effector_pose_gradient = &d_end_effector_pose_gradient[k*696];
                ee_pos_cost<T, EE>(&d_out[k], s_q, s_p_des, s_W, s_end_effector_pose, s_ee_arena, d_robotModel);
                __syncthreads();
                ee_pos_cost_gradient<T, EE>(&d_grad[k*58], s_q, s_p_des, s_W, s_end_effector_pose, s_end_effector_pose_gradient, s_ee_arena, d_robotModel);
                __syncthreads();
                ee_pos_cost_hessian<T, EE, false, true>(&d_hess[k*3364], s_q, s_p_des, s_W, s_end_effector_pose, s_end_effector_pose_gradient, nullptr, s_ee_arena, d_robotModel);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_EE_COST 1
        #define GRID_PLANT_HAS_TRACKING_COST 1
        /**
         * com_cost_kernel: value + grad_x + GN hess_x per timestep
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad grad over x (58 per timestep)
         * @param d_hess dense col-major x-hessian (3364 per timestep)
         * @param d_q joint positions (NUM_POS per timestep)
         * @param d_p_des desired CoM position (3 per timestep)
         * @param d_W per-axis weight (3 per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, bool MUJOCO_OUTPUT = false>
        __global__
        void com_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_p_des, const T *d_W, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
            extern __shared__ __align__(16) T s_com_arena[];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                const T *s_q = &d_q[k*29]; const T *s_p_des = &d_p_des[k*3]; const T *s_W = &d_W[k*3];
                com_cost<T>(&d_out[k], s_q, s_p_des, s_W, s_com_arena, d_robotModel);
                __syncthreads();
                com_cost_gradient<T>(&d_grad[k*58], s_q, s_p_des, s_W, s_com_arena, d_robotModel);
                __syncthreads();
                com_cost_hessian<T>(&d_hess[k*3364], s_q, s_W, s_com_arena, d_robotModel);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_COM_COST 1
        /**
         * momentum_cost_kernel: value + grad_x + GN hess_x per timestep
         *
         * @param d_out scalar cost (1 per timestep)
         * @param d_grad grad over x (58 per timestep)
         * @param d_hess dense col-major x-hessian (3364 per timestep)
         * @param d_q / d_qd joint positions/velocities (NUM_POS / NUM_VEL per timestep)
         * @param d_h_des desired centroidal momentum (6 per timestep)
         * @param d_W per-component weight (6 per timestep)
         * @param NUM_TIMESTEPS is the batch size
         */
        template <typename T, bool MUJOCO_OUTPUT = false>
        __global__
        void momentum_cost_kernel(T *d_out, T *d_grad, T *d_hess, const T *d_q, const T *d_qd, const T *d_h_des, const T *d_W, const grid::robotModel<T> *d_robotModel, const int NUM_TIMESTEPS) {
            extern __shared__ __align__(16) T s_ccrba_arena[];
            for(int k = blockIdx.x + blockIdx.y*gridDim.x; k < NUM_TIMESTEPS; k += gridDim.x*gridDim.y){
                const T *s_q = &d_q[k*29]; const T *s_qd = &d_qd[k*29];
                const T *s_h_des = &d_h_des[k*6]; const T *s_W = &d_W[k*6];
                momentum_cost<T>(&d_out[k], s_q, s_qd, s_h_des, s_W, s_ccrba_arena, d_robotModel);
                __syncthreads();
                momentum_cost_gradient<T>(&d_grad[k*58], s_q, s_qd, s_h_des, s_W, s_ccrba_arena, d_robotModel);
                __syncthreads();
                momentum_cost_hessian<T>(&d_hess[k*3364], s_q, s_qd, s_W, s_ccrba_arena, d_robotModel);
                __syncthreads();
            }
        }

        #define GRID_PLANT_HAS_MOMENTUM_COST 1
    }
